export const CURRICULO_ESTRUTURADO = {"Ciências": [{"a": "6", "t": "1", "c": "EF06CI01/ES", "e": "Matéria e Energia", "h": "Observar, reconhecer e identificar características de diferentes materiais e suas misturas, registrando suas observações antes e após a mistura, por meio de diferentes mídias e linguagens, classificando essas misturas como homogêneas ou heterogêneas (óleo, água e areia entre outros).", "o": "Misturas homogêneas e heterogêneas."}, {"a": "6", "t": "1", "c": "EF06CI02/ES", "e": "Matéria e Energia", "h": "Identificar evidências de transformações químicas a partir do resultado de práticas experimentais em que produtos originados de uma mistura sejam diferentes das substâncias iniciais, registrando suas observações antes e após da mistura, por meio de diferentes mídias e linguagens e discutindo sua aplicabilidade e influência na atividade humana e no meio ambiente.", "o": "Transformações químicas."}, {"a": "6", "t": "1", "c": "EF06CI03/ES", "e": "Matéria e Energia", "h": "Identificar processos de separação de materiais (como a produção de sal de cozinha, a destilação de petróleo, o tratamento de água e/ou efluentes, a produção do álcool, entre outros) e selecionar os métodos mais adequados para a separação de diferentes sistemas heterogêneos, relacionando sistemas produtivos locais ou regionais que utilizem a separação de materiais no seu processo, de forma a propor ações coletivas que promovam a consciência ambiental e um modo de vida sustentável.", "o": "Separação de materiais."}, {"a": "6", "t": "1", "c": "EF06CI04/ES", "e": "Matéria e Energia", "h": "Identificar os tipos de medicamentos (fitoterápicos, alopáticos, manipulados, entre outros) e de outros materiais sintéticos (fios de nylon, plásticos etc.) e associar a sua produção ao desenvolvimento científico e tecnológico, reconhecendo benefícios e avaliando impactos socioambientais, ao analisar as consequências de seu uso e descarte em sua região e no mundo.", "o": "Materiais sintéticos."}, {"a": "6", "t": "1", "c": "EF06CI15/ES", "e": "Matéria e Energia", "h": "Reconhecer que o movimento de pessoas e objetos possuem diferentes explicações expressas ao longo da história, comparando-as com interpretações espontâneas, não científicas, e não raro, encontráveis ainda hoje.", "o": "A ação de forças e o estado de movimento."}, {"a": "6", "t": "1", "c": "EF06CI16/ES", "e": "Matéria e Energia", "h": "Relacionar o estado de movimento de pessoas e objetos à ação de forças aplicadas, identificando as situações de equilíbrio estático e equilíbrio dinâmico", "o": "Condições de equilíbrio mecânico estático e dinâmico."}, {"a": "6", "t": "2", "c": "EF06CI05/ES", "e": "Vida e Evolução", "h": "Identificar e explicar a organização básica das células e seu papel como unidade estrutural e funcional dos seres vivos, representando-as por meio de modelos e simulações e reconhecendo-as como unidade básica da vida (teoria celular).", "o": "Célula como unidade da vida"}, {"a": "6", "t": "2", "c": "EF06CI06/ES", "e": "Vida e Evolução", "h": "Identificar e reconhecer os diferentes níveis de organização dos seres vivos (tecidos, órgãos e sistemas), por meio da análise de ilustrações e/ou representações tridimensionais, incluindo o uso de mídias digitais, comparando as suas características, de modo a classificá-los em uma perspectiva evolutiva e concluir que são constituídos de um complexo arranjo de sistemas com diferentes níveis de organização.", "o": "Níveis de organização dos seres vivos."}, {"a": "6", "t": "2", "c": "EF06CI07", "e": "Vida e Evolução", "h": "Justificar o papel do sistema nervoso na coordenação das ações motoras e sensoriais do corpo, com base na análise de suas estruturas básicas e respectivas funções.", "o": "Sistema nervoso."}, {"a": "6", "t": "2", "c": "EF06CI08/ES", "e": "Vida e Evolução", "h": "Explicar a importância da visão (captação e interpretação das imagens) na interação dos seres vivos com o meio, identificando as partes que compõem o olho em diferentes seres vivos, explicando suas funções e identificar as diferentes anomalias da visão e suas formas de correção.", "o": "O Sentido da visão."}, {"a": "6", "t": "2", "c": "EF06CI09/ES", "e": "Vida e Evolução", "h": "Identificar as partes e estruturas do sistema esquelético e muscular, compreendendo e explicando suas funções, de modo a deduzir que a estrutura, a sustentação e a movimentação dos animais resultam da interação entre esses sistemas, em conjunto com o sistema nervoso.", "o": "Sistemas esquelético e muscular"}, {"a": "6", "t": "3", "c": "EF06CI10/ES", "e": "Vida e Evolução", "h": "Identificar e classificar as substâncias psicoativas lícitas e ilícitas, reconhecendo os seus efeitos no organismo humano e classificando-as como depressoras, estimulantes ou alucinógenas, de modo a explicar como o funcionamento do sistema nervoso pode ser afetado por essas substâncias e discutir o seu uso em diferentes culturas, bem como os seus efeitos sociais na atualidade.", "o": "Efeitos de substâncias psicoativas sobre o sistema nervoso. Práticas experimentais de Ciências Sugestões de materiais"}, {"a": "6", "t": "3", "c": "EF06CI11/ES", "e": "Terra e Universo", "h": "Identificar as diferentes camadas que estruturam o planeta Terra (da estrutura interna à atmosfera) e suas principais características, diferenciando-as e descrevendo-as por meio de modelos bidimensionais e tridimensionais e reconhecer os distintos modelos representativos do planeta Terra em diferentes épocas e culturas, compreendendo o impacto do desenvolvimento científico na construção e reconstrução desses modelos.", "o": "Estrutura da Terra."}, {"a": "6", "t": "3", "c": "EF06CI12/ES", "e": "Terra e Universo", "h": "Identificar diferentes tipos de rocha, relacionando suas características à formação de fósseis em diferentes períodos geológicos, segundo uma perspectiva evolutiva que os encare como evidência e referência da vida no passado.", "o": "Tipos de rochas e formação de fósseis."}, {"a": "6", "t": "3", "c": "EF06CI13/ES", "e": "Terra e Universo", "h": "Selecionar argumentos a partir da identificação, da comparação e do reconhecimento de evidências que expliquem os modelos representativos da forma real da Terra.", "o": "Forma da Terra."}, {"a": "6", "t": "3", "c": "EF06CI14/ES", "e": "Terra e Universo", "h": "Inferir que as variações da radiação solar em cada região, ao longo do dia e em diferentes períodos do ano, evidenciadas pelas mudanças que ocorrem na projeção das sombras de diferentes objetos (gnômon, árvores, edifícios entre outros) se correlacionam com os movimentos relativos entre a Terra e o Sol e representar tais movimentos por meio de modelos bidimensionais e tridimensionais.", "o": "Movimentos relativos entre a Terra e o sol. Práticas experimentais de Ciências Sugestões de materiais"}, {"a": "7", "t": "1", "c": "EF07CI01/ES", "e": "Matéria e Energia", "h": "Identificar e compreender o que são máquinas simples e discutir a sua aplicação, ao longo da história, de forma a propor soluções e invenções de recursos ou equipamentos mecânicos que facilitem a realização de tarefas cotidianas. 7º ano", "o": "Máquinas simples."}, {"a": "7", "t": "1", "c": "EF07CI02/ES", "e": "Matéria e Energia", "h": "Diferenciar temperatura, calor e sensação térmica nas diferentes situações de equilíbrio termodinâmico cotidianas, reconhecendo as condições para existência de fluxo térmico e de equilíbrio termodinâmico e identificando formas de medir a temperatura de diferentes materiais e substâncias em diferentes condições.", "o": "Temperatura e calor."}, {"a": "7", "t": "1", "c": "EF07CI03/ES", "e": "Matéria e Energia", "h": "Reconhecer e classificar modos de propagação de calor entre diferentes meios e utilizar esse conhecimento para justificar a utilização de determinados materiais (condutores e isolantes) na vida cotidiana, explicar o princípio de funcionamento de alguns equipamentos (garrafa térmica, coletor solar etc.) e/ou construir soluções tecnológicas a partir desse conhecimento. 7º ano", "o": "Propagação do calor."}, {"a": "7", "t": "1", "c": "EF07CI04-a/ES", "e": "Matéria e Energia", "h": "Avaliar o papel do equilíbrio termodinâmico para a manutenção da vida na Terra, identificando as características ambientais necessárias para que a vida ocorra e propor a construção de modelos representativos, em diferentes mídias e formas de expressão, nos quais sejam identificadas as condições necessárias para a manutenção do equilíbrio ambiental.", "o": "Termodinâmica e Meio Ambiente."}, {"a": "7", "t": "1", "c": "EF07CI04-b/ES", "e": "Matéria e Energia", "h": "Identificar e compreender o que são as máquinas térmicas, construindo protótipos e/ou modelos bidimensionais e tridimensionais, de forma a entender como funcionam e avaliar o papel do equilíbrio termodinâmico em seu funcionamento.", "o": "Máquinas térmicas."}, {"a": "7", "t": "1", "c": "EF07CI05", "e": "Matéria e Energia", "h": "Discutir o uso de diferentes tipos de combustível e máquinas térmicas ao longo do tempo, para avaliar avanços, questões econômicas e problemas socioambientais causados pela produção e uso desses materiais e máquinas. 7º ano", "o": "História dos combustíveis e das máquinas térmicas."}, {"a": "7", "t": "1", "c": "EF07CI06", "e": "Matéria e Energia", "h": "Discutir e avaliar mudanças econômicas, culturais e sociais, tanto na vida cotidiana quanto no mundo do trabalho, decorrentes do desenvolvimento de novos materiais e tecnologias (como automação e informatização).", "o": "Desenvolvimento tecnológico. 7º ano"}, {"a": "7", "t": "2", "c": "EF07CI07", "e": "Vida e Evolução", "h": "Caracterizar os principais ecossistemas brasileiros quanto à paisagem, à quantidade de água, ao tipo de solo, à disponibilidade de luz solar, à temperatura etc., correlacionando essas características à flora e fauna específicas.", "o": "Ecossistemas brasileiros."}, {"a": "7", "t": "2", "c": "EF07CI08", "e": "Vida e Evolução", "h": "Avaliar como os impactos provocados por catástrofes naturais ou mudanças nos componentes físicos, biológicos ou sociais de um ecossistema afetam suas populações, podendo ameaçar ou provocar a extinção de espécies, alteração de hábitos, migração etc.", "o": "Fenômenos naturais e impactos socioambientais."}, {"a": "7", "t": "2", "c": "EF07CI09", "e": "Vida e Evolução", "h": "Interpretar as condições de saúde da comunidade, da cidade ou do estado, com base na análise e na comparação de indicadores de saúde (como taxa de mortalidade infantil, cobertura de saneamento básico e incidência de doenças de veiculação hídrica, atmosférica entre outras) e dos resultados de políticas públicas destinadas à saúde.", "o": "Programas e indicadores de saúde pública."}, {"a": "7", "t": "2", "c": "EF07CI10", "e": "Vida e Evolução", "h": "Argumentar sobre a importância da vacinação para a saúde pública, com base em informações sobre a maneira como a vacina atua no organismo e o papel histórico da vacinação para a manutenção da saúde ndividual e coletiva e para a erradicação de doenças.", "o": "Vacinação e saúde pública."}, {"a": "7", "t": "2", "c": "EF07CI11/ES", "e": "Vida e Evolução", "h": "Analisar o desenvolvimento científico e tecnológico o longo da história da humanidade, considerando indicadores ambientais e sociais, de modo a identificar e reconhecer avanços no tratamento e nas medidas de prevenção de doenças, na melhoria da saúde e da qualidade de vida das pessoas, incluindo a intervenção no modo e nos hábitos de vida.", "o": "Ciência, tecnologia e saúde."}, {"a": "7", "t": "3", "c": "EF07CI12/ES", "e": "Terra e Universo", "h": "Demonstrar que o ar é uma mistura de gases, identificando a sua composição, e discutir fenômenos naturais ou antrópicos que podem alterar essa composição e/ou interferir na saúde coletiva e no equilíbrio dos ecossistemas e em sua região.", "o": "Composição do ar."}, {"a": "7", "t": "3", "c": "EF07CI13", "e": "Terra e Universo", "h": "Descrever o mecanismo natural do efeito estufa, seu papel fundamental para o desenvolvimento da vida na Terra, discutir as ações humanas responsáveis pelo seu aumento artificial (queima dos combustíveis fósseis, desmatamento, queimadas e outras formas de interferência). E selecionar e implementar propostas para a reversão ou controle desse quadro.", "o": "Efeito estufa"}, {"a": "7", "t": "3", "c": "EF07CI14", "e": "Terra e Universo", "h": "Justificar a importância da camada de ozônio para a vida na Terra, identificando os fatores que aumentam ou diminuem sua presença na atmosfera, e discutir propostas individuais e coletivas para sua preservação.", "o": "Camada de ozônio."}, {"a": "7", "t": "3", "c": "EF07CI15/ES", "e": "Terra e Universo", "h": "Interpretar fenômenos naturais (como vulcões, terremotos e tsunamis), por meio de textos, artigos e dados, e justificar a rara ocorrência desses fenômenos no Brasil, com base no modelo das placas tectônicas.", "o": "Fenômenos naturais (vulcões, terremotos e tsunamis)."}, {"a": "7", "t": "3", "c": "EF07CI16/ES", "e": "Terra e Universo", "h": "Justificar o formato das costas brasileira e africana com base na teoria da deriva dos continentes, construindo modelos explicativos e ilustrativos que relacionem a costa brasileira e a africana a partir do movimento das massas continentais ao longo do tempo geológico do planeta Terra e de evidências paleoclimáticas, geológicas, geofísicas e biogeográficas.", "o": "Placas tectônicas e deriva continental"}, {"a": "8", "t": "1", "c": "EF08CI01/ES", "e": "Matéria e Energia", "h": "Identificar que a energia elétrica utilizada em residências, comunidades ou cidades pode ser obtida de fontes renováveis e/ou não renováveis, classificando-a de acordo com sua origem (eólica, hidrelétrica, solar, geotérmica, biomassa etc.).", "o": "Energia elétrica."}, {"a": "8", "t": "1", "c": "EF08CI02/ES", "e": "Matéria e Energia", "h": "Construir circuitos elétricos simples, a partir da compreensão de como ocorre a corrente elétrica, identificando a função dos elementos de circuito mais comuns (resistores, capacitores, geradores, etc.), reconhecendo medidas básicas de segurança ao lidar com eletricidade, e comparar as características desses circuitos com as dos circuitos elétricos residenciais.", "o": "Circuitos elétricos. Práticas experimentais de Ciências Sugestões de materiais"}, {"a": "8", "t": "1", "c": "EF08CI03", "e": "Matéria e Energia", "h": "Classificar equipamentos elétricos residenciais (chuveiro, ferro, lâmpadas, TV, rádio, geladeira etc.) de acordo com o tipo de transformação de energia (da energia elétrica para a térmica, luminosa, sonora e mecânica, por exemplo).", "o": "Transformação de energia."}, {"a": "8", "t": "1", "c": "EF08CI04", "e": "Matéria e Energia", "h": "Calcular o consumo de eletrodomésticos a partir dos dados de potência (descritos no próprio equipamento) e tempo médio de uso para avaliar o impacto de cada equipamento no consumo doméstico mensal.", "o": "Cálculo de consumo de energia elétrica."}, {"a": "8", "t": "1", "c": "EF08CI05", "e": "Matéria e Energia", "h": "Propor ações coletivas para otimizar o uso de energia elétrica em sua escola e/ou comunidade, com base na seleção de equipamentos segundo critérios de sustentabilidade (consumo de energia e eficiência energética) e hábitos de consumo responsável.", "o": "Uso consciente de energia elétrica."}, {"a": "8", "t": "1", "c": "EF08CI06", "e": "Matéria e Energia", "h": "Discutir e avaliar usinas de geração de energia elétrica (termelétricas, hidrelétricas, eólicas etc.), suas semelhanças e diferenças, seus impactos socioambientais, e como essa energia chega e é usada em sua cidade, comunidade, casa ou escola.", "o": "Uso consciente de energia elétrica."}, {"a": "8", "t": "2", "c": "EF08CI07/ES", "e": "Vida e Evolução", "h": "Comparar diferentes processos reprodutivos em plantas e animais, diferenciando e descrevendo as partes que compõem seus sistemas reprodutores e reconhecendo suas funções, bem como aspectos da reprodução sexuada e assexuada, dos tipos de fertilização, do desenvolvimento e da existência de cuidado parental, e explicar o papel dos mecanismos reprodutivos na conservação ou modificação de características que envolvem a adaptação dos seres vivos em um processo evolutivo. 8º ano", "o": "Mecanismos reprodutivos."}, {"a": "8", "t": "2", "c": "EF08CI08/ES", "e": "Vida e Evolução", "h": "Analisar e explicar as transformações que ocorrem na puberdade, considerando a atuação dos hormônios sexuais e do sistema nervoso, identificando e descrevendo as mudanças físicas e psicológicas que ocorrem nessa fase da vida, assim como as questões relacionadas à saúde que lhe são específicas e reconhecendo a diversidade de desenvolvimento e de construção de identidades sociais e culturais (tradições e ritos de passagem).", "o": "Adolescência e puberdade."}, {"a": "8", "t": "2", "c": "EF08CI09", "e": "Vida e Evolução", "h": "Comparar o modo de ação e a eficácia dos diversos métodos contraceptivos e justificar a necessidade de compartilhar a responsabilidade na escolha e na utilização do método mais adequado à prevenção da gravidez precoce e indesejada e de Doenças Sexualmente Transmissíveis (DST).", "o": "Métodos contraceptivos. 8º ano"}, {"a": "8", "t": "2", "c": "EF08CI10/ES", "e": "Vida e Evolução", "h": "Identificar os principais sintomas, modos de transmissão e tratamento de algumas DST (Gonorreia, Sífilis, HPV, Aids, Herpes, etc.), e discutir estratégias e selecionar métodos de prevenção mais adequados às diferentes DST, envolvendo a responsabilidade e consciência sobre a sua saúde sexual.", "o": "Doenças Sexualmente Transmissíveis."}, {"a": "8", "t": "2", "c": "EF08CI11/ES", "e": "Vida e Evolução", "h": "Selecionar argumentos que evidenciem as múltiplas dimensões da sexualidade humana (biológica, sociocultural, afetiva e ética), reconhecendo, compreendendo e discutindo aspectos como o cuidado e o respeito a si mesmo e ao outro, a construção da identidade social e cultural, a afetividade e a compreensão dos aspectos culturais envolvidos na sexualidade humana.", "o": "Sexualidade humana."}, {"a": "8", "t": "3", "c": "EF08CI12/ES", "e": "Terra e Universo", "h": "Justificar a ocorrência das fases da Lua e dos eclipses lunares e solares, a partir da observação do céu, da leitura de textos e artigos científicos e da utilização de recursos digitais, representando o sistema sol, Terra e lua por meio de modelos bidimensionais e tridimensionais.", "o": "Sistema sol, Terra e lua."}, {"a": "8", "t": "3", "c": "EF08CI13/ES", "e": "Terra e Universo", "h": "Compreender, descrever e ilustrar os movimentos de rotação e translação da Terra, representando o sistema sol e Terra por meio de modelos bidimensionais e tridimensionais, relacionando o movimento orbital da Terra e a sua exposição aos raios solares à ocorrência das estações do ano e explicar a influência desses fenômenos em seu cotidiano e sobre o modo de vida na Terra.", "o": "Movimento orbital da Terra e estações do ano."}, {"a": "8", "t": "3", "c": "EF08CI14/ES", "e": "Terra e Universo", "h": "Compreender e explicar o deslocamento das massas de ar e sua relação com as diferenças de temperatura e pressão existentes na atmosfera terrestre e na dinâmica da temperatura nos oceanos, de modo a relacionar climas regionais aos padrões de circulação atmosférica e oceânica e ao aquecimento desigual causado pela forma e pelos movimentos da Terra.", "o": "Tempo e clima."}, {"a": "8", "t": "3", "c": "EF08CI15/ES", "e": "Terra e Universo", "h": "Identificar as principais variáveis envolvidas na previsão do tempo e simular situações nas quais elas possam ser medidas, associando a intervenção humana às mudanças dessas variáveis, com destaque para as que interferem na paisagem e na agricultura bem como para as consequências que acarretam no clima local e global.", "o": "Variáveis meteorológicas."}, {"a": "8", "t": "3", "c": "EF08CI16", "e": "Terra e Universo", "h": "Discutir iniciativas que contribuam para restabelecer o equilíbrio ambiental a partir da identificação de alterações climáticas regionais e globais provocadas pela intervenção humana.", "o": "Alterações climáticas e equilíbrio ambiental."}, {"a": "9", "t": "1", "c": "EF09CI01/ES", "e": "Matéria e Energia", "h": "Explicar estados físicos da matéria e suas transformações, com base no modelo de constituição submicroscópica, estimulando a interpretação de dados para o levantamento e desenvolvimento de hipóteses sobre a aplicação de determinados processos na solução de problemas no cotidiano e no sistema produtivo.", "o": "Estados físicos da matéria e suas transformações."}, {"a": "9", "t": "1", "c": "EF09CI02/ES", "e": "Matéria e Energia", "h": "Comparar quantidades de reagentes e produtos envolvidos em transformações químicas do cotidiano e em geral, estabelecendo a proporção entre as suas massas utilizando atividades investigativas experimentais para identificar e representar substâncias simples e compostas e explorar símbolos, fórmulas e equações, com ênfase na proporção de massas.", "o": "Aspectos quantitativos das transformações químicas."}, {"a": "9", "t": "1", "c": "EF09CI03/ES", "e": "Matéria e Energia", "h": "Identificar modelos que descrevem a estrutura da matéria (constituição do átomo e composição de moléculas simples), descrevendo-os e representando-os em diferentes mídias, linguagens e formas de expressão e reconhecer a sua evolução histórica.", "o": "Estrutura da matéria."}, {"a": "9", "t": "1", "c": "EF09CI04/ES", "e": "Matéria e Energia", "h": "Planejar e executar experimentos que evidenciem fenômenos relacionados à decomposição da luz e à percepção de cores, investigando a relação do espectro eletromagnético com a percepção das cores em diferentes materiais do cotidiano, quando expostos a diferentes fontes de iluminação e reconhecer como o sistema visual dos seres vivos interpreta as cores.", "o": "A luz como radiação eletromagnética visível."}, {"a": "9", "t": "1", "c": "EF09CI05/ES", "e": "Matéria e Energia", "h": "Investigar os principais mecanismos envolvidos na transmissão e recepção de imagem e som que revolucionaram os sistemas de comunicação humana, identificando, analisando, categorizando e explicando os processos de transmissão e recepção de imagem e som, relacionando-os às radiações eletromagnéticas e reconhecendo a evolução dos meios de comunicação e suas implicações na vida humana.", "o": "Uso das radiações telecomunicações. eletromagnéticas nas"}, {"a": "9", "t": "1", "c": "EF09CI06/ES", "e": "Matéria e Energia", "h": "Classificar as radiações eletromagnéticas por suas frequências, fontes e aplicações, relacionar as ondas eletromagnéticas ao seu uso em diferentes tecnologias e avaliar os desdobramentos da aplicação tecnológica das radiações em uma perspectiva socioambiental.", "o": "Características das radiações eletromagnéticas."}, {"a": "9", "t": "1", "c": "EF09CI07", "e": "Matéria e Energia", "h": "Discutir e avaliar o papel do avanço tecnológico na aplicação da radiação eletromagnética no diagnóstico (raios-X, ultrassom, ressonância nuclear magnética) e tratamento de doenças (radioterapia, cirurgia ótica a laser etc.).", "o": "Aplicações das radiações eletromagnéticas na saúde."}, {"a": "9", "t": "2", "c": "EF09CI08/ES", "e": "Vida e Evolução", "h": "Associar os gametas à transmissão das características hereditárias, identificando as estruturas celulares, do DNA e os cromossomos, por meio de exemplos e modelos ilustrativos, de modo a reconhecer os princípios da hereditariedade, para estabelecer relações entre ancestrais e descendentes, reconhecendo suas características físicas como hereditárias, congênitas, adquiridas ou genéticas.", "o": "Hereditariedade."}, {"a": "9", "t": "2", "c": "EF09CI09", "e": "Vida e Evolução", "h": "Discutir as ideias de Mendel sobre hereditariedade (fatores hereditários, segregação, gametas, fecundação), considerando-as para resolver problemas envolvendo a transmissão de características hereditárias em diferentes organismos.", "o": "Leis de Mendel."}, {"a": "9", "t": "2", "c": "EF09CI10", "e": "Vida e Evolução", "h": "Comparar as ideias evolucionistas de Lamarck e Darwin apresentadas em textos científicos e históricos, identificando semelhanças e diferenças entre essas ideias e compreendendo a sua importância para explicar a diversidade biológica.", "o": "Ideias evolucionistas."}, {"a": "9", "t": "2", "c": "EF09CI11", "e": "Vida e Evolução", "h": "Discutir a evolução e a diversidade das espécies com base na atuação da seleção natural sobre as variantes de uma mesma espécie, resultantes de processo reprodutivo.", "o": "Variabilidade genética e seleção natural. 9º ano"}, {"a": "9", "t": "2", "c": "EF09CI12/ES", "e": "Vida e Evolução", "h": "Justificar a importância das unidades de conservação para a preservação da biodiversidade e do patrimônio nacional, considerando os diferentes tipos de unidades (parques, reservas e florestas nacionais), as populações humanas e atividades a eles relacionadas, reconhecendo as legislações e as regulamentações que asseguram existência das unidades de conservação, de modo a propor soluções sustentáveis para a composição dessas unidades em diferentes ecossistemas.", "o": "Preservação da biodiversidade."}, {"a": "9", "t": "2", "c": "EF09CI13", "e": "Vida e Evolução", "h": "Propor iniciativas individuais e coletivas para a solução de problemas ambientais da cidade ou da comunidade, com base na análise de ações sustentáveis bemsucedidas.", "o": "Responsabilidade Socioambiental."}, {"a": "9", "t": "3", "c": "EF09CI14", "e": "", "h": "Descrever a composição e a estrutura do sistema solar (sol, planetas rochosos, planetas gigantes gasosos e corpos menores), assim como a localização do sistema solar na nossa Galáxia (a Via Láctea) e dela no universo (apenas uma galáxia dentre bilhões).", "o": "Composição, estrutura e localização do sistema solar no universo."}, {"a": "9", "t": "3", "c": "EF09CI15", "e": "Terra e Universo", "h": "Relacionar diferentes leituras do céu e explicações sobre a origem da Terra, do sol ou do sistema solar às necessidades de distintas culturas (a agricultura, a caça, os mitos, as formas e instrumentos de orientação espacial e temporal entre outros.).", "o": "Astronomia e cultura."}, {"a": "9", "t": "3", "c": "EF09CI16/ES", "e": "Terra e Universo", "h": "Selecionar argumentos sobre a viabilidade da sobrevivência humana fora da Terra, com base nas condições necessárias à vida, nas características dos planetas, nas distâncias e nos tempos envolvidos em viagens interplanetárias e interestelares e analisar se esses elementos podem ser encontrados na zona habitável do sistema solar, a partir de informações obtidas sobre outros astros, considerando aspectos da exploração espacial que desafiaram o modo de vida que se desenvolveu na Terra sob condições adversas, como radiação, suporte à vida, tempo, entre outros.", "o": "Vida humana fora da Terra."}, {"a": "9", "t": "3", "c": "EF09CI17", "e": "Terra e Universo", "h": "Analisar o ciclo evolutivo do sol (nascimento, vida e morte) baseado no conhecimento das etapas de evolução de estrelas de diferentes dimensões e os efeitos desse processo no nosso planeta.", "o": "Evolução estelar."}], "Artes": [{"a": "6", "t": "1", "c": "EF69AR01-06/ES", "e": "", "h": "Pesquisar, apreciar e analisar formas distintas das artes visuais que identifiquem a formação do povo brasileiro, tradicionais e contemporâneas, em obras de artistas brasileiros e estrangeiros de diferentes épocas e em diferentes matrizes estéticas e culturais, de modo a ampliar a experiência com diferentes contextos e práticas artístico-visuais e cultivar a percepção, o imaginário, a capacidade de simbolizar e o repertório imagético.", "o": "• Contextos e práticas."}, {"a": "6", "t": "1", "c": "EF69AR02-06/ES", "e": "", "h": "Pesquisar e analisar diferentes estilos visuais nas obras da arte brasileira, contextualizando-os com estilos internacionais no tempo e no espaço.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "1", "c": "EF69AR03-06/ES", "e": "", "h": "Analisar situações nas quais as linguagens das artes visuais se integram às linguagens audiovisuais (cinema, animações, vídeos etc.), gráficas (capas de livros, ilustrações de textos diversos etc.), cenográficas, coreográficas, musicais etc., principalmente na produção da arte brasileira.", "o": "• Contextos e práticas"}, {"a": "6", "t": "1", "c": "EF69AR04", "e": "", "h": "Analisar os elementos constitutivos das artes visuais (ponto, linha, forma, direção, cor, tom, escala, dimensão, espaço, movimento etc.) na apreciação de diferentes produções artísticas.", "o": "• Elementos da Linguagem."}, {"a": "6", "t": "1", "c": "EF69AR05-06/ES", "e": "", "h": "Experimentar e analisar diferentes formas de expressão artística (desenho, pintura, colagem, quadrinhos, dobradura, escultura, modelagem, instalação, vídeo, fotografia, performance, etc.), percebendo as potencialidades e possibilidades de cada meio, materiais e instrumentos utilizados por diferentes artistas brasileiros.", "o": "• Materialidades."}, {"a": "6", "t": "1", "c": "EF69AR06-06/ES", "e": "", "h": "Desenvolver processos de criação em artes visuais, com base em temas ou interesses artísticos presentes na arte brasileira, de modo individual, coletivo e colaborativo, fazendo uso de materiais, instrumentos e recursos convencionais, alternativos e digitais, propiciando novos desafios e possibilidades na construção de uma narrativa própria.", "o": "• Processos de criação."}, {"a": "6", "t": "1", "c": "EF69AR07-06/ES", "e": "", "h": "Dialogar com princípios conceituais, proposições temáticas, repertórios imagéticos e processos de criação nas suas produções visuais, aprofundando a poética pessoal e ampliando o vocabulário próprio.", "o": "• Processos de criação."}, {"a": "6", "t": "1", "c": "EF69AR08-06/ES", "e": "", "h": "Diferenciar as categorias artísticas, artesão, produtor cultural, curador, designer, entre outras, estabelecendo relações entre os profissionais do sistema das artes visuais, conhecendo a função de cada um desses agentes na elaboração de saraus, exposições, eventos culturais, etc.", "o": "• Sistemas da linguagem."}, {"a": "6", "t": "1", "c": "EF69AR31-06/ES", "e": "", "h": "Relacionar as práticas artísticas às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética, percebendo a formação da arte brasileira na identidade do povo que constitui essa nação.", "o": "• Contextos e práticas."}, {"a": "6", "t": "1", "c": "EF69AR33-06/ES", "e": "", "h": "Analisar aspectos históricos, sociais e políticos da produção artística, problematizando as narrativas eurocêntricas e as diversas categorizações da arte (arte, artesanato, folclore, design etc.), percebendo e respeitando a diversidade étnica na formação do povo brasileiro.", "o": "• Matrizes estéticas e culturais."}, {"a": "6", "t": "1", "c": "EF69AR34-06/ES", "e": "", "h": "Analisar e valorizar o patrimônio cultural, material e imaterial, de culturas diversas, em especial a brasileira, incluindo suas matrizes indígenas, africanas e europeias, de diferentes épocas, e favorecendo a construção de vocabulário e repertório relativos às diferentes linguagens artísticas, participando da identificação do que constitui o patrimônio material, imaterial, histórico, artístico e natural.", "o": "• Patrimônio cultural."}, {"a": "6", "t": "1", "c": "EF69AR35-06/ES", "e": "", "h": "Identificar e manipular diferentes tecnologias e recursos digitais para acessar, apreciar, produzir, registrar e compartilhar práticas e repertórios artísticos, de modo reflexivo, ético e responsável, utilizando recursos tecnológicos para ressignificar a arte brasileira.", "o": "• Arte e tecnologia."}, {"a": "6", "t": "2", "c": "EF69AR09-06/ES", "e": "", "h": "Pesquisar e analisar diferentes formas de expressão, representação e encenação da dança, reconhecendo e apreciando composições de dança de artistas e grupos brasileiros e estrangeiros, em destaque para apreciação de grupos e dançarinos brasileiros nos diferentes contextos e épocas.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR10-06/ES", "e": "", "h": "Observar e explorar elementos constitutivos do movimento cotidiano e do movimento dançado, abordando, criticamente, o desenvolvimento das formas da dança em sua história tradicional e contemporânea, percebendo os significados desses elementos na dança brasileira.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "2", "c": "EF69AR16-06/ES", "e": "", "h": "Analisar criticamente, por meio da apreciação musical, usos e funções da música em seus contextos de produção e circulação, principalmente no que diz respeito à diversidade musical brasileira, relacionando as práticas musicais às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR17-06/ES", "e": "", "h": "Explorar e analisar, criticamente, diferentes meios e equipamentos culturais de circulação da música e do conhecimento musical produzido no Brasil.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR18-06/ES", "e": "", "h": "Reconhecer e apreciar o papel de músicos e grupos de música brasileiros e estrangeiros que contribuíram para o desenvolvimento de formas e gêneros musicais, evidenciando as transformações da música ao longo do tempo.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR19-06/ES", "e": "", "h": "Identificar e analisar diferentes estilos musicais, a fim de ampliar o repertório, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética musical.", "o": "• Contextos e práticas."}, {"a": "6", "t": "2", "c": "EF69AR20-06/ES", "e": "", "h": "Explorar e analisar elementos constitutivos da música (altura, intensidade, timbre, melodia, ritmo etc.), por meio de recursos naturais e tecnológicos (games e plataformas digitais), jogos, canções e práticas diversas de composição/criação, execução e apreciação musicais, ampliando a percepção dos parâmetros do som e os elementos básicos da música.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "2", "c": "EF69AR21-06/ES", "e": "", "h": "Explorar e analisar fontes e materiais sonoros em práticas de composição/criação, execução e apreciação musical, reconhecendo timbres e características de instrumentos musicais diversos característicos da cultura brasileira.", "o": "• Materialidades."}, {"a": "6", "t": "2", "c": "EF69AR22-06/ES", "e": "", "h": "Explorar e identificar diferentes formas de registro musical não convencional (como partituras criativas e procedimentos da música contemporânea), bem como procedimentos e técnicas de registro em áudio e audiovisual e reconhecer os princípios da notação musical convencional.", "o": "• Notação e registro musical."}, {"a": "6", "t": "2", "c": "EF69AR23-06/ES", "e": "", "h": "Explorar e criar improvisações, composições, arranjos, jingles, trilhas sonoras, entre outros, utilizando vozes, sons corporais e/ou instrumentos acústicos ou eletrônicos, convencionais ou não convencionais, expressando ideias musicais de maneira individual, coletiva e colaborativa. Além disso, estimular-se para um fazer musical espontâneo e autêntico, com respeito e valorização dos elementos que constituem a diversidade cultural brasileira.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR11-06/ES", "e": "", "h": "Experimentar e analisar os fatores de movimento (tempo, peso, fluência e espaço) como elementos que, combinados, geram as ações corporais e o movimento dançado, ampliando seu próprio repertório.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "3", "c": "EF69AR12-06/ES", "e": "", "h": "Investigar e experimentar procedimentos de improvisação e criação do movimento como fonte para a construção de vocabulários e repertórios próprios, pesquisando, de maneira autônoma e /ou colaborativa, formas expressivas de dança.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR13-06/ES", "e": "", "h": "Investigar e vivenciar brincadeiras, jogos e danças coletivas, sobretudo as brasileiras, além de outras práticas de dança de diferentes matrizes estéticas e culturais como referência para a criação e a composição de danças autorais, individualmente e em grupo.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR14-06/ES", "e": "", "h": "Analisar e experimentar diferentes elementos (figurino, iluminação, cenário, trilha sonora etc.) e espaços (convencionais e não convencionais) para composição cênica e apresentação coreográfica, investigando e analisando os elementos e espaços da dança brasileira.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR15-06/ES", "e": "", "h": "Discutir as experiências pessoais e coletivas em dança vivenciadas na escola e em outros contextos, problematizando estereótipos e preconceitos, apreciando estilos de danças brasileiras de diferentes épocas.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR24-06/ES", "e": "", "h": "Reconhecer e apreciar artistas e grupos de teatro brasileiros e estrangeiros de diferentes épocas, investigando os modos de criação, produção, divulgação, circulação e organização da atuação profissional em teatro, além de pesquisar a formação do povo brasileiro na produção teatral.", "o": "• Contextos e práticas."}, {"a": "6", "t": "3", "c": "EF69AR25-06/ES", "e": "", "h": "Identificar e analisar diferentes estilos cênicos (tragédia clássica, tragédia moderna, comédia clássica, comédia moderna, entre outros), a fim de ampliar o repertório, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética teatral, principalmente a brasileira.", "o": "• Contextos e práticas."}, {"a": "6", "t": "3", "c": "EF69AR26-06/ES", "e": "", "h": "Explorar diferentes elementos envolvidos na composição dos acontecimentos cênicos (figurinos, adereços, cenário, iluminação e sonoplastia) e reconhecer seus vocabulários, percebendo as características desses elementos na produção teatral brasileira de diferentes épocas.", "o": "• Elementos da linguagem."}, {"a": "6", "t": "3", "c": "EF69AR27-06/ES", "e": "", "h": "Pesquisar e criar formas de dramaturgia e espaços cênicos para o acontecimento teatral, em diálogo com o teatro contemporâneo, pesquisando nas salas de aula, na escola ou em ambiente externos a possibilidade de espaços físicos em espaços cênicos.", "o": "• Processos de criação"}, {"a": "6", "t": "3", "c": "EF69AR28-06/ES", "e": "", "h": "Investigar e experimentar diferentes funções teatrais e discutir os limites e desafios do trabalho artístico coletivo e colaborativo, experimentando a construção de roteiros/cenas que tenham: enredo, história, conflito dramático, personagens, diálogo local e ações dramáticas definidas.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR29-06/ES", "e": "", "h": "Experimentar a gestualidade e as construções corporais e vocais de maneira imaginativa na improvisação teatral e no jogo cênico, utilizando a capacidade de expressar e criar significados no plano sensório-corporal.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR30-06/ES", "e": "", "h": "Compor improvisações e acontecimentos cênicos com base em textos dramáticos ou outros estímulos (música, imagens, objetos etc.), caracterizando personagens (com figurinos e adereços), cenário, iluminação e sonoplastia e considerando a relação com o espectador.", "o": "• Processos de criação."}, {"a": "6", "t": "3", "c": "EF69AR32-06/ES", "e": "", "h": "Analisar e explorar, em projetos temáticos, as relações processuais entre diversas linguagens artísticas, valorizando a identidade do povo brasileiro.", "o": "• Processos de criação."}, {"a": "7", "t": "1", "c": "EF69AR01-07/ES", "e": "", "h": "Pesquisar, apreciar e analisar formas distintas das artes visuais tradicionais e contemporâneas que se apresentem em espaços públicos e/ou arquitetônicos: espaços urbanos, paisagens naturais, ciberespaços, entre outros, em obras de artistas brasileiros e estrangeiros de diferentes épocas e em diferentes matrizes estéticas e culturais, de modo a ampliar a experiência com diferentes contextos e práticas artístico-visuais e cultivar a percepção, o imaginário, a capacidade de simbolizar e o repertório imagético.", "o": "• Contextos e práticas."}, {"a": "7", "t": "1", "c": "EF69AR02-07/ES", "e": "", "h": "Pesquisar e analisar diferentes estilos visuais, contextualizando-os no tempo e no espaço, comparando obras de artes de diferentes espaços públicos (nacionais e internacionais) com obras realizadas em espaços naturais em diversos lugares.", "o": "• Contextos e práticas."}, {"a": "7", "t": "1", "c": "EF69AR03-07/ES", "e": "", "h": "Analisar situações nas quais as linguagens das artes visuais se integram às linguagens audiovisuais (cinema, animações, vídeos etc.), gráficas (capas de livros, ilustrações de textos diversos etc.), cenográficas, coreográficas, musicais etc., principalmente em espaços públicos.", "o": "• Contextos e práticas."}, {"a": "7", "t": "1", "c": "EF69AR04-07/ES", "e": "", "h": "Analisar os elementos constitutivos das artes visuais (ponto, linha, forma, direção, cor, tom, escala, dimensão, espaço, movimento etc.) na apreciação de diferentes produções artísticas, considerando os conteúdos gerados a partir de suas articulações internas e contextuais.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "1", "c": "EF69AR05-07/ES", "e": "", "h": "Experimentar e analisar diferentes formas de expressão artística (desenho, pintura, colagem, quadrinhos, dobradura, escultura, modelagem, instalação, vídeo, fotografia, performance etc.), percebendo as potencialidades e possibilidades de cada meio, materiais e instrumentos utilizados por diferentes artistas brasileiros.", "o": "• Materialidades."}, {"a": "7", "t": "1", "c": "EF69AR06-07/ES", "e": "", "h": "Desenvolver processos de criação em artes visuais, com base em temas ou interesses artísticos, potencializando a criação em arte como ocupação de diferentes espaços, de modo individual, coletivo e colaborativo, fazendo uso de materiais, instrumentos e recursos convencionais, alternativos e digitais.", "o": "• Processos de criação."}, {"a": "7", "t": "1", "c": "EF69AR07-07/ES", "e": "", "h": "Dialogar com princípios conceituais, proposições temáticas, repertórios imagéticos e processos de criação nas suas produções visuais, aprofundando a poética pessoal e ampliando o vocabulário próprio.", "o": "• Processos de criação."}, {"a": "7", "t": "1", "c": "EF69AR08-07/ES", "e": "", "h": "Diferenciar as categorias de artista, artesão, produtor cultural, curador, designer, entre outras, estabelecendo relações entre os profissionais do sistema das artes visuais, conhecendo a função de cada um desses agentes na elaboração de saraus, exposições, eventos culturais, etc.", "o": "• Sistemas da linguagem."}, {"a": "7", "t": "1", "c": "EF69AR31-07/ES", "e": "", "h": "Relacionar as práticas artísticas às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética, a partir de uma situação local ou da região e da experiência com o teatro de espaços não convencionais, possibilitando observação ou pesquisa presencial, exercitando a escuta e a construção de um olhar preceptivo.", "o": "• Contextos e práticas."}, {"a": "7", "t": "1", "c": "EF69AR33-07/ES", "e": "", "h": "Analisar aspectos históricos, sociais e políticos da produção artística, problematizando as narrativas eurocêntricas e as diversas categorizações da arte (arte, artesanato, folclore, design etc.), identificando das diferentes matrizes estéticas nas produções de arte públicas.", "o": "• Matrizes estéticas e culturais."}, {"a": "7", "t": "1", "c": "EF69AR34-07/ES", "e": "", "h": "Analisar e valorizar o patrimônio cultural, material e imaterial, de culturas diversas, em especial a brasileira, incluindo suas matrizes indígenas, africanas e europeias, de diferentes épocas, e favorecendo a construção de vocabulário e repertório relativos às diferentes linguagens artísticas, relacionando a arte pública à educação patrimonial.", "o": "• Patrimônio cultural."}, {"a": "7", "t": "1", "c": "EF69AR35-07/ES", "e": "", "h": "Identificar e manipular diferentes tecnologias e recursos digitais para acessar, apreciar, produzir, registrar e compartilhar práticas e repertórios artísticos, de modo reflexivo, ético e responsável, permeando os espaços públicos de diferentes contextos.", "o": "• Arte e tecnologia."}, {"a": "7", "t": "2", "c": "EF69AR09-07/ES", "e": "", "h": "Pesquisar e analisar diferentes formas de expressão, representação e encenação da dança, reconhecendo e apreciando composições de dança de artistas e grupos brasileiros e estrangeiros, de diferentes épocas, que se apresentam em diferentes espaços públicos: praças, ruas, escolas, igrejas, tribos, terreiros, etc.", "o": "• Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR10-07/ES", "e": "", "h": "Explorar elementos constitutivos do movimento cotidiano e do movimento dançado, abordando, criticamente, o desenvolvimento das formas da dança, em sua história tradicional e contemporânea, percebendo os significados desses elementos nas danças em espaços públicos.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "2", "c": "EF69AR16-07/ES", "e": "", "h": "Analisar criticamente, por meio da apreciação musical, usos e funções da música em seus contextos de produção e circulação, observando as manifestações musicais que acontecem em diferentes espaços públicos: carnaval, festivais, festas urbanas, festas tradicionais etc., relacionando as práticas musicais às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética.", "o": "• Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR17-07/ES", "e": "", "h": "Explorar e analisar, criticamente, diferentes meios e equipamentos culturais de circulação da música e do conhecimento musical, ampliando a concepção de espaço de criação e apresentação musical e reconhecendo as ruas, praças e demais espaços coletivos como potencialidades.", "o": "• Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR18-07/ES", "e": "", "h": "Reconhecer e apreciar o papel de músicos e grupos de música brasileiros e estrangeiros que contribuíram para o desenvolvimento de formas e gêneros musicais presentes nas ruas das cidades e nos espaços do campo do interior do país.", "o": "• Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR19-07/ES", "e": "", "h": "Identificar e analisar diferentes estilos musicais, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética musical, percebendo os estilos que se popularizaram entre as massas e que estão presentes nos grandes festivais de música, analisando seus impactos nos processos de construção ética e cultural.", "o": "•Contextos e práticas."}, {"a": "7", "t": "2", "c": "EF69AR20-07/ES", "e": "", "h": "Explorar e analisar elementos constitutivos da música (altura, intensidade, timbre, melodia, ritmo etc.), por meio de recursos tecnológicos (games e plataformas digitais), jogos, canções e práticas diversas de composição/criação, execução e apreciação musicais presentes nos diversos espaços do território nacional.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "2", "c": "EF69AR21", "e": "", "h": "Explorar e analisar fontes e materiais sonoros em práticas de composição/criação, execução e apreciação musical, reconhecendo timbres e características de instrumentos musicais diversos.", "o": "• Materialidades."}, {"a": "7", "t": "2", "c": "EF69AR22-07/ES", "e": "", "h": "Explorar e identificar diferentes formas de registro musical não convencional (como partituras criativas e procedimentos da música contemporânea brasileira), bem como procedimentos e técnicas de registro em áudio e audiovisual e reconhecer princípios da notação musical convencional.", "o": "• Notação e registro musical."}, {"a": "7", "t": "2", "c": "EF69AR23-07/ES", "e": "", "h": "Explorar e criar improvisações, composições, arranjos, jingles, trilhas sonoras, entre outros, utilizando vozes, sons corporais e/ou instrumentos acústicos ou eletrônicos, convencionais ou não convencionais, expressando ideias musicais de maneira individual, coletiva e colaborativa, além de relacionar as experiências propostas com a apreciação de diferentes músicos ou músicas apresentados em espaços públicos.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR11-07/ES", "e": "", "h": "Experimentar e analisar os fatores de movimento (tempo, peso, fluência e espaço) como elementos que, combinados, geram as ações corporais e o movimento dançado, ampliando o seu próprio repertório.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "3", "c": "EF69AR12-07/ES", "e": "", "h": "Investigar e experimentar procedimentos de improvisação e criação do movimento como fonte para a construção de vocabulários e repertórios próprios.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR13-07/ES", "e": "", "h": "Investigar brincadeiras, jogos, danças coletivas e outras práticas de dança de diferentes matrizes estéticas e culturais como referência para a criação e a composição de danças autorais, individualmente e em grupo, procurando interagir com diferentes espaços públicos.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR14-07/ES", "e": "", "h": "Analisar e experimentar diferentes elementos (figurino, iluminação, cenário, trilha sonora etc.) e espaços (convencionais e não convencionais) para composição cênica e apresentação coreográfica em diferentes espaços públicos.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR15-07/ES", "e": "", "h": "Discutir as experiências pessoais e coletivas em dança vivenciadas na escola e em outros contextos, problematizando estereótipos e preconceitos, principalmente aqueles vinculados às danças de comunidades marginalizadas.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR24-07/ES", "e": "", "h": "Reconhecer e apreciar artistas e grupos de teatro brasileiros e estrangeiros de diferentes épocas, investigando os modos de criação, produção, divulgação, circulação e organização da atuação profissional em teatro, dando ênfase na produção de teatro realizada em espaços exteriores às construções tradicionais, como nas ruas, praças, mercados, metrôs, universidades e outros.", "o": "• Contextos e práticas."}, {"a": "7", "t": "3", "c": "EF69AR25-07/ES", "e": "", "h": "Identificar e analisar diferentes estilos cênicos (realista, tragédia clássica, tragédia moderna, comédia clássica, comédia moderna, teatro contemporâneo, teatro de rua, teatro de bonecos, circo, entre outros), a fim de ampliar o repertório, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética teatral.", "o": "• Contextos e práticas."}, {"a": "7", "t": "3", "c": "EF69AR26-07/ES", "e": "", "h": "Explorar diferentes elementos envolvidos na composição dos acontecimentos cênicos (figurinos, adereços, cenário, iluminação e sonoplastia) e reconhecer seus vocabulários, percebendo as características desses elementos na produção teatral presente em diferentes territorialidades.", "o": "• Elementos da linguagem."}, {"a": "7", "t": "3", "c": "EF69AR27-07/ES", "e": "", "h": "Pesquisar e criar formas de dramaturgias e espaços cênicos para o acontecimento teatral, em diálogo com o teatro contemporâneo, pesquisando, nos espaços da escola e em ambientes externos, a possibilidade de uso dos espaços físicos como espaços cênicos.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR28-07/ES", "e": "", "h": "Investigar e experimentar diferentes funções teatrais e discutir os limites e desafios do trabalho artístico de coletivos teatrais, de forma coletiva e colaborativa, experimentando a construção de roteiros/cenas que tenham: enredo/história/ conflito dramático/ personagens/ diálogo local e ação dramática definida.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR29-07/ES", "e": "", "h": "Experimentar a gestualidade e as construções corporais e vocais de maneira imaginativa na improvisação teatral e no jogo cênico, utilizando a capacidade de expressar e criar significados no plano sensório-corporal.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR30-07/ES", "e": "", "h": "Compor improvisações e acontecimentos cênicos com base em textos dramáticos ou outros estímulos (música, imagens, objetos etc.), caracterizando personagens (com figurinos e adereços), cenário, iluminação e sonoplastia e considerando a relação com o espectador.", "o": "• Processos de criação."}, {"a": "7", "t": "3", "c": "EF69AR32-07/ES", "e": "", "h": "Analisar e explorar, em projetos temáticos, as relações processuais entre diversas linguagens artísticas, valorizando a produção de arte em espaços públicos.", "o": "• Processos de criação."}, {"a": "8", "t": "1", "c": "EF69AR01-08/ES", "e": "", "h": "Pesquisar, apreciar e analisar formas distintas das artes visuais tradicionais e contemporâneas, em que se identifiquem as lutas ideológicas, sociais e políticas, em obras de artistas brasileiros e estrangeiros de diferentes épocas e em diferentes matrizes estéticas e culturais, de modo a ampliar a experiência com diversos contextos e práticas artístico-visuais e cultivar a percepção, o imaginário, a capacidade de simbolizar e o repertório imagético, possibilitando sua compreensão e ressignificação.", "o": "• Contextos e práticas."}, {"a": "8", "t": "1", "c": "EF69AR02-08/ES", "e": "", "h": "Pesquisar e analisar diferentes estilos visuais que produziram uma arte de reflexão e contestação, contextualizando-os no tempo e no espaço, compreendendo os momentos históricos e socioculturais ao longo das diferentes histórias das artes.", "o": "• Contextos e práticas."}, {"a": "8", "t": "1", "c": "EF69AR03-08/ES", "e": "", "h": "Analisar situações nas quais as linguagens das artes visuais se integram às linguagens audiovisuais (cinema, animações, vídeos etc.), gráficas (capas de livros, ilustrações de textos diversos etc.), cenográficas, coreográficas, musicais etc., pesquisando, principalmente nas obras de arte de cunho social, político, ecológico e ideológico.", "o": "• Contextos e práticas."}, {"a": "8", "t": "1", "c": "EF69AR04-08/ES", "e": "", "h": "Analisar os elementos constitutivos das artes visuais (ponto, linha, forma, direção, cor, tom, escala, dimensão, espaço, movimento etc.) na apreciação de diferentes produções artísticas, identificando-os conforme o material e o meio em que a obra é realizada, além de refletir sobre as relações dos elementos visuais, tanto internas quanto contextuais.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "1", "c": "EF69AR05-08/ES", "e": "", "h": "Experimentar e analisar diferentes formas de expressão artística (desenho, pintura, colagem, quadrinhos, dobradura, escultura, modelagem, instalação, vídeo, fotografia, performance, etc.), percebendo as possibilidades criativas de cada suporte, meio, instrumento e materiais utilizados nas obras.", "o": "• Materialidades."}, {"a": "8", "t": "1", "c": "EF69AR06-08/ES", "e": "", "h": "Desenvolver processos de criação em artes visuais, com base em temas ou interesses artísticos, de modo individual, coletivo e colaborativo, fazendo uso de materiais, instrumentos e recursos convencionais, alternativos e digitais, aprimorando seu pensamento criativo em arte.", "o": "• Processos de criação."}, {"a": "8", "t": "1", "c": "EF69AR07-08/ES", "e": "", "h": "Dialogar com princípios conceituais, proposições temáticas, repertórios imagéticos e processos de criação, nas suas produções visuais, estabelecendo relações com o repertório do aluno.", "o": "• Processos de criação."}, {"a": "8", "t": "1", "c": "EF69AR08-08/ES", "e": "", "h": "Diferenciar as categorias de artista, artesão, produtor cultural, curador, designer, entre outras, ampliando a compreensão das categorias e estabelecendo relações entre os profissionais do sistema das artes visuais.", "o": "• Sistemas da linguagem."}, {"a": "8", "t": "1", "c": "EF69AR31-08/ES", "e": "", "h": "Relacionar as práticas artísticas às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética, possibilitando a escuta e a construção de um olhar perceptivo, apreendendo a arte como instrumento de expressão e de comunicação de ideias políticas, sociais e ambientais.", "o": "• Contextos e práticas."}, {"a": "8", "t": "1", "c": "EF69AR33-08/ES", "e": "", "h": "Analisar aspectos históricos, sociais e políticos da produção artística, problematizando as narrativas eurocêntricas e as diversas categorizações da arte (arte, artesanato, folclore, design etc.), percebendo a arte como ferramenta de fortalecimento de diferentes etnias.", "o": "• Matrizes estéticas e culturais."}, {"a": "8", "t": "1", "c": "EF69AR34-08/ES", "e": "", "h": "Analisar e valorizar o patrimônio cultural, material e imaterial, de culturas diversas, em especial a brasileira, incluindo suas matrizes indígenas, africanas e europeias, de diferentes épocas, e favorecendo a construção de vocabulário e repertório relativos às diversas linguagens artísticas, participando da identificação do que constitui o patrimônio material (arquitetura), imaterial, histórico, artístico e natural.", "o": "• Patrimônio Cultural."}, {"a": "8", "t": "1", "c": "EF69AR35-08/ES", "e": "", "h": "Identificar e manipular diferentes tecnologias e recursos digitais para acessar, apreciar, produzir, registrar e compartilhar práticas e repertórios artísticos, de modo reflexivo, ético e responsável, dialogando com a arte de reflexão.", "o": "• Arte e tecnologia."}, {"a": "8", "t": "2", "c": "EF69AR09-08/ES", "e": "", "h": "Pesquisar e analisar diferentes formas de expressão, representação e encenação da dança que articulam um pensamento crítico e reflexivo, reconhecendo e apreciando composições de dança de artistas e grupos brasileiros e estrangeiros de diferentes épocas.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR10-08/ES", "e": "", "h": "Explorar elementos constitutivos do movimento cotidiano e do movimento dançado, abordando, criticamente, o desenvolvimento das formas da dança em sua história tradicional e contemporânea, reconhecendo a potencialidade expressiva do gesto e do movimento cotidiano para transformar-se em dança.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "2", "c": "EF69AR16-08/ES", "e": "", "h": "Analisar criticamente, por meio da apreciação musical, usos e funções da música em seus contextos de produção e circulação, relacionando as práticas musicais às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética, destacando o caráter crítico, político e social de diferentes músicas e gêneros musicais.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR17-08/ES", "e": "", "h": "Explorar e analisar, criticamente, diferentes meios e equipamentos culturais de circulação da música e do conhecimento musical, ampliando e/ou desenvolvendo uma escuta crítica da música.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR18-08/ES", "e": "", "h": "Reconhecer e apreciar o papel de músicos e grupos de música brasileiros e estrangeiros que contribuíram para o desenvolvimento de formas e gêneros musicais, em especial músicos e bandas de ativismos políticos, ideológicos e sociais.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR19-08/ES", "e": "", "h": "Identificar e analisar diferentes estilos musicais, contextualizando-os no tempo e no espaço, de modo a aprimorar e ampliar a capacidade de apreciação da estética musical.", "o": "• Contextos e práticas."}, {"a": "8", "t": "2", "c": "EF69AR20-08/ES", "e": "", "h": "Explorar e analisar elementos constitutivos da música (altura, intensidade, timbre, melodia, ritmo etc.), por meio de recursos tecnológicos (games e plataformas digitais), jogos, canções e práticas diversas de composição/ criação, execução e apreciação musicais, ampliando a percepção dos parâmetros do som e os elementos básicos da música.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "2", "c": "EF69AR21-08/ES", "e": "", "h": "Explorar e analisar fontes e materiais sonoros locais e regionais em práticas de composição/criação, execução e apreciação musical, reconhecendo timbres e características de instrumentos musicais diversos.", "o": "• Materialidades."}, {"a": "8", "t": "2", "c": "EF69AR22-08/ES", "e": "", "h": "Explorar e identificar diferentes formas de registro musical não convencional (como partituras criativas e procedimentos da música contemporânea brasileira), bem como procedimentos e técnicas de registro em áudio e audiovisual e reconhecer princípios da notação musical convencional.", "o": "• Notação e registro musical."}, {"a": "8", "t": "2", "c": "EF69AR23-08/ES", "e": "", "h": "Explorar e criar improvisações, composições, arranjos, jingles, trilhas sonoras, entre outros, utilizando vozes, sons corporais e/ou instrumentos acústicos ou eletrônicos, convencionais ou não convencionais, expressando ideias musicais de maneira individual, coletiva e colaborativa, relacionando as experiências propostas com a apreciação de diferentes músicos ou músicas, locais, nacionais e internacionais.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR11-08/ES", "e": "", "h": "Experimentar e analisar os fatores de movimento (tempo, peso, fluência e espaço) como elementos que, combinados, geram as ações corporais e o movimento dançado, ampliando o seu próprio repertório.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "3", "c": "EF69AR12-08/ES", "e": "", "h": "Investigar e experimentar procedimentos de improvisação e criação do movimento como fonte para a construção de vocabulários e repertórios próprios, inspirados ou não em manifestações de dança.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR13-08/ES", "e": "", "h": "Investigar e experimentar brincadeiras, jogos, danças coletivas e outras práticas de dança de diferentes matrizes estéticas e culturais como referência para a criação e a composição de danças autorais, individualmente e em grupo.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR14", "e": "", "h": "Analisar e experimentar diferentes elementos (figurino, iluminação, cenário, trilha sonora etc.) e espaços (convencionais e não convencionais) para composição cênica e apresentação coreográfica.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR15-08/ES", "e": "", "h": "Discutir as experiências pessoais e coletivas em dança vivenciadas na escola e em outros contextos, problematizando estereótipos e preconceitos.", "o": "•Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR24-08/ES", "e": "", "h": "Reconhecer e apreciar artistas e grupos de teatro brasileiros e estrangeiros de diferentes épocas, investigando os modos de criação, produção, divulgação, circulação e organização da atuação profissional em teatro e identificando as diferentes visões socioculturais, antropológicas e políticas no Teatro.", "o": "• Contextos e práticas."}, {"a": "8", "t": "3", "c": "EF69AR25-08/ES", "e": "", "h": "Identificar e analisar diferentes estilos cênicos (melodrama, teatro de revista, peças didáticas, entre outros), contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética teatral.", "o": "• Contextos e práticas."}, {"a": "8", "t": "3", "c": "EF69AR26-08/ES", "e": "", "h": "Explorar diferentes elementos (figurinos, adereços, cenário, iluminação e sonoplastia) envolvidos na composição dos acontecimentos cênicos e reconhecer seus vocabulários.", "o": "• Elementos da linguagem."}, {"a": "8", "t": "3", "c": "EF69AR27-08/ES", "e": "", "h": "Pesquisar e criar formas de dramaturgia e espaços cênicos para o acontecimento teatral, em diálogo com o teatro contemporâneo, pesquisando nos espaços da escola e em ambientes externos a possibilidade de uso dos espaços físicos como espaços cênicos.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR28-08/ES", "e": "", "h": "Investigar e experimentar diferentes funções teatrais, além de discutir, de forma coletiva e colaborativa, os limites e desafios do trabalho artístico de coletivos teatrais, experimentando a construção de roteiros/ cenas que tenham: enredo/ história/ conflito dramático/ personagens/ diálogo local e ação dramática definida.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR29-08/ES", "e": "", "h": "Experimentar a gestualidade e as construções corporais e vocais, de maneira imaginativa, na improvisação teatral e no jogo cênico, utilizando a capacidade de expressar e criar significados no plano sensório-corporal.", "o": "•Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR30-08/ES", "e": "Teatro.", "h": "Compor improvisações e acontecimentos cênicos com base em textos dramáticos ou outros estímulos (música, imagens, objetos etc.), caracterizando personagens (com figurinos e adereços), cenário, iluminação e sonoplastia e considerando a relação com o espectador.", "o": "• Processos de criação."}, {"a": "8", "t": "3", "c": "EF69AR32-08/ES", "e": "Artes integradas.", "h": "Analisar e explorar, em projetos temáticos, as relações processuais entre diversas linguagens artísticas, utilizandose da arte como instrumento de transformação política e social.", "o": "• Processos de criação."}, {"a": "9", "t": "1", "c": "EF69AR01-09/ES", "e": "", "h": "Pesquisar, apreciar e analisar formas distintas das artes visuais tradicionais e contemporâneas, a partir de manifestações artísticas com o uso de computadores, criações multimídias, fotografia, vídeo e som, em obras de artistas brasileiros e estrangeiros de diferentes épocas e em diferentes matrizes estéticas e culturais, de modo a ampliar a experiência com diversificados contextos e práticas artístico-visuais e cultivar a percepção, o imaginário, a capacidade de simbolizar e o repertório imagético.", "o": "•Contextos e práticas."}, {"a": "9", "t": "1", "c": "EF69AR02-09/ES", "e": "", "h": "Pesquisar e analisar diferentes estilos visuais relacionados às mídias digitais: conteúdos, temas, histórias e interfaces com as mídias tradicionais, contextualizando-os no tempo e no espaço.", "o": "• Contextos e práticas."}, {"a": "9", "t": "1", "c": "EF69AR03-09/ES", "e": "", "h": "Analisar situações nas quais as linguagens das artes visuais se integram às linguagens audiovisuais (cinema, animações, vídeos etc.), gráficas (capas de livros, ilustrações de textos diversos etc.), cenográficas, coreográficas, musicais etc, pesquisando sobre as novas relações entre arte, tecnologia e ciências.", "o": "• Contextos e práticas."}, {"a": "9", "t": "1", "c": "EF69AR04-09/ES", "e": "", "h": "Analisar os elementos constitutivos das artes visuais (ponto, linha, forma, direção, cor, tom, escala, dimensão, espaço, movimento etc.) na apreciação de diferentes produções artísticas, considerando os conteúdos gerados a partir de suas articulações internas e contextuais.", "o": "• Elementos da linguagem."}, {"a": "9", "t": "1", "c": "EF69AR05-09/ES", "e": "", "h": "Experimentar e analisar diferentes formas de expressão artística (desenho, pintura, colagem, quadrinhos, dobradura, escultura, modelagem, instalação, vídeo, fotografia, performance etc.), incorporando equipamentos multimídia, ambientes imersivos e códigos de programação.", "o": "• Materialidades."}, {"a": "9", "t": "1", "c": "EF69AR06-09/ES", "e": "", "h": "Desenvolver processos de criação em artes visuais, com base em temas ou interesses artísticos, de modo individual, coletivo e colaborativo, fazendo uso de materiais, instrumentos e recursos convencionais, alternativos e digitais, expandido a criação com as mídias digitais.", "o": "• Processos de criação."}, {"a": "9", "t": "1", "c": "EF69AR07-09/ES", "e": "", "h": "Dialogar com princípios conceituais, proposições temáticas, repertórios imagéticos e processos de criação nas suas produções visuais, experimentando obras de arte com abrangência multissensorial (obras interativas e ambientes imersivos).", "o": "• Processos de criação."}, {"a": "9", "t": "1", "c": "EF69AR08-09/ES", "e": "", "h": "Diferenciar as categorias de artista, artesão, produtor cultural, curador, designer, entre outras, estabelecendo relações entre os profissionais do sistema das artes visuais, com a observação do designer como criação em novas tecnologias.", "o": "• Sistemas de linguagem."}, {"a": "9", "t": "1", "c": "EF69AR31-09/ES", "e": "", "h": "Relacionar as práticas artísticas tecnológicas às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética.", "o": "• Contextos e práticas."}, {"a": "9", "t": "1", "c": "EF69AR33-09/ES", "e": "", "h": "Analisar aspectos históricos, sociais e políticos que influenciaram as diversas produções artísticas, problematizando as narrativas eurocêntricas, reconhecendo diferentes áreas culturais e intentando não mostrar um passado somente eurocêntrico, mas as diversas categorizações da arte (arte, artesanato, folclore, design etc.).", "o": "• Matrizes estéticas e culturais."}, {"a": "9", "t": "1", "c": "EF69AR34-09/ES", "e": "", "h": "Analisar e valorizar o patrimônio cultural, material (bens históricos, paisagísticos, etnográficos, obras de arte, entre outros) e imaterial (os saberes, habilidades, crenças, celebrações, manifestações, entre outros), de culturas diversas, em especial a brasileira, incluindo suas matrizes indígenas, africanas e europeias, de diferentes épocas, e favorecendo a construção de vocabulário e repertório relativos às diferentes linguagens artísticas.", "o": "• Patrimônio cultural."}, {"a": "9", "t": "1", "c": "EF69AR35-09/ES", "e": "", "h": "Identificar e manipular diferentes tecnologias e recursos digitais para acessar, apreciar, produzir, registrar e compartilhar práticas e repertórios artísticos, de modo reflexivo, ético e responsável.", "o": "• Arte e tecnologia."}, {"a": "9", "t": "2", "c": "EF69AR09-09/ES", "e": "", "h": "Pesquisar e analisar diferentes formas de expressão, representação e encenação da dança que estabeleçam a relação entre arte e tecnologia, reconhecendo e apreciando composições de dança de artistas e grupos brasileiros e estrangeiros de diferentes épocas.", "o": "• Contextos e práticas."}, {"a": "9", "t": "2", "c": "EF69AR10-09/ES", "e": "", "h": "Explorar elementos constitutivos do movimento cotidiano e do movimento dançado, abordando, criticamente, o desenvolvimento das formas da dança em sua história tradicional e contemporânea, com observação nos efeitos visuais, jogos de luz, efeitos sonoros e utilização de multimídias na dança.", "o": "• Elementos da linguagem"}, {"a": "9", "t": "2", "c": "EF69AR16-09/ES", "e": "", "h": "Analisar criticamente, por meio da apreciação musical, usos e funções da música em seus contextos de produção e circulação, incluindo as novas plataformas, dispositivos e aplicativos de produção e distribuição de música, relacionando as práticas musicais às diferentes dimensões da vida social, cultural, política, histórica, econômica, estética e ética.", "o": "• Contextos e práticas"}, {"a": "9", "t": "2", "c": "EF69AR17-09/ES", "e": "", "h": "Explorar e analisar, criticamente, diferentes meios e equipamentos culturais de circulação da música e do conhecimento musical, percebendo a relação da música com a tecnologia.", "o": "• Contextos e práticas."}, {"a": "9", "t": "2", "c": "EF69AR18-09/ES", "e": "", "h": "Reconhecer e apreciar o papel de músicos e grupos de música brasileiros e estrangeiros que contribuíram para o desenvolvimento de formas e gêneros musicais, incluindo manifestações musicais contemporâneas produzidas a partir de novas tecnologias (música eletrônica, música eletroacústica e músicas produzidas a partir de aplicativos e dispositivos eletrônicos).", "o": "• Contextos e práticas"}, {"a": "9", "t": "2", "c": "EF69AR19-09/ES", "e": "", "h": "Identificar e analisar diferentes estilos musicais, incluindo as músicas produzidas através de novas tecnologias, contextualizando-os no tempo e no espaço, de modo a aprimorar a capacidade de apreciação da estética musical contemporânea.", "o": "• Contextos e práticas."}, {"a": "9", "t": "2", "c": "EF69AR20-09/ES", "e": "", "h": "Explorar e analisar elementos constitutivos da música (altura, intensidade, timbre, melodia, ritmo etc.), por meio de recursos tecnológicos (games e plataformas digitais), jogos, canções e práticas diversas de composição/ criação, execução e apreciação musicais, ampliando a percepção dos parâmetros do som e os elementos básicos da música.", "o": "• Elementos de linguagem."}, {"a": "9", "t": "2", "c": "EF69AR21-09/ES", "e": "", "h": "Explorar e analisar fontes e materiais sonoros em práticas de composição/criação, execução e apreciação musical, reconhecendo timbres e características de instrumentos musicais diversos: acústicos, elétricos e eletrônicos.", "o": "•Materialidades."}, {"a": "9", "t": "2", "c": "EF69AR22", "e": "", "h": "Explorar e identificar diferentes formas de registro musical (notação musical tradicional, partituras criativas e procedimentos da música contemporânea), bem como procedimentos e técnicas de registro em áudio e audiovisual.", "o": "• Notação e registro musical."}, {"a": "9", "t": "2", "c": "EF69AR23-09/ES", "e": "", "h": "Explorar e criar improvisações, composições, arranjos, jingles, trilhas sonoras, entre outros, utilizando vozes, sons corporais e/ou instrumentos acústicos ou eletrônicos, convencionais ou não convencionais, expressando ideias musicais de maneira individual, coletiva e colaborativa.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR11-09/ES", "e": "", "h": "Experimentar e analisar os fatores de movimento (tempo, peso, fluência e espaço) como elementos que, combinados, geram as ações corporais e o movimento dançado, ampliando o seu próprio repertório.", "o": "• Elementos da linguagem."}, {"a": "9", "t": "3", "c": "EF69AR12-09/ES", "e": "", "h": "Investigar e experimentar procedimentos de improvisação e criação do movimento, em performance e instalação, como fonte para a construção de vocabulários e repertórios próprios.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR13-09/ES", "e": "", "h": "Investigar brincadeiras, jogos, danças coletivas e outras práticas de dança de diferentes matrizes estéticas e culturais como referência para a criação e a composição de danças autorais, individualmente e em grupo, utilizando de mídias digitais e outras tecnologias.", "o": "• Processos de criação"}, {"a": "9", "t": "3", "c": "EF69AR14-09/ES", "e": "", "h": "Analisar e experimentar diferentes elementos (figurino, iluminação, cenário, trilha sonora etc.) e espaços (convencionais e não convencionais) para composição cênica e apresentação coreográfica, conhecendo a especificidade dos elementos na criação e produção artística da dança.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR15-09/ES", "e": "", "h": "Discutir as experiências pessoais e coletivas em dança vivenciadas na escola e em outros contextos, problematizando estereótipos e preconceitos.", "o": "• Processos de criação"}, {"a": "9", "t": "3", "c": "EF69AR24-09/ES", "e": "", "h": "Reconhecer e apreciar artistas e grupos de teatro brasileiros e estrangeiros de diferentes épocas, investigando os modos de criação, produção, divulgação, circulação e organização da atuação profissional em teatro, integrando linguagens, tecnologia e o público.", "o": "• Contextos e práticas."}, {"a": "9", "t": "3", "c": "EF69AR25-09/ES", "e": "", "h": "Identificar e analisar diferentes estilos cênicos, contextualizando-os no tempo e no espaço de modo a aprimorar a capacidade de apreciação da estética teatral. Ademais, ampliar a experiência de aprendizagem com a projeção de vídeos de espetáculos teatrais de diversas matrizes culturais.", "o": "• Contextos e práticas"}, {"a": "9", "t": "3", "c": "EF69AR26-09/ES", "e": "", "h": "Explorar diferentes elementos (figurinos, adereços, cenário, iluminação e sonoplastia) envolvidos na composição dos acontecimentos cênicos e reconhecer seus vocabulários.", "o": "• Elementos da linguagem."}, {"a": "9", "t": "3", "c": "EF69AR27-09/ES", "e": "", "h": "Pesquisar e criar formas de dramaturgia e espaços cênicos como possibilidades de transformação de um local físico para o acontecimento teatral, em diálogo com o teatro contemporâneo.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR28-09/ES", "e": "", "h": "Investigar e experimentar diferentes funções teatrais e discutir os limites e desafios do trabalho artístico coletivo e colaborativo, permitindo a compreensão dos modos coletivizados e de diretriz dialógica de fazerem teatro.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR29-09/ES", "e": "", "h": "Experimentar a gestualidade e as construções corporais e vocais de maneira imaginativa na improvisação teatral e no jogo cênico, potencializando a imaginação e narrativas para o exercício dessas expressividades.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR30-09/ES", "e": "", "h": "Compor e encenar improvisações e acontecimentos cênicos com base em textos dramáticos ou outros estímulos (música, imagens, objetos etc.), caracterizando personagens (com figurinos e adereços), cenário, iluminação e sonoplastia e considerando a relação com o espectador.", "o": "• Processos de criação."}, {"a": "9", "t": "3", "c": "EF69AR32-09/ES", "e": "", "h": "Analisar e praticar, em projetos temáticos, as relações processuais entre diversas linguagens artísticas (teatro, dança, música e artes visuais).", "o": "• Processos de criação."}], "Educação Física": [{"a": "6", "t": "1", "c": "EF67EF03-06/ES", "e": "Esportes", "h": "Experimentar e fruir esportes de marca, precisão, invasão e técnico-combinatórios que façam parte do contexto social dos estudantes, valorizando o trabalho coletivo e o protagonismo, por meio de atividades lúdicas e criativas.", "o": "Esportes de Marca •Exemplos: Corridas, Saltos, Arremesso e Lançamentos do Atletismo; •Prática de habilidades específicas de esportes de marca, como técnica de corrida, saltos e arremessos, promovendo o desenvolvimento motor e a superação de desafios individuais e coletivos."}, {"a": "6", "t": "1", "c": "EF67EF04", "e": "Esportes", "h": "Praticar um ou mais esportes de marca, precisão, invasão e técnico-combinatórios oferecidos pela escola, usando habilidades técnico-táticas básicas e respeitando regras.", "o": "Esportes de Marca •Regras; •Fundamentos básicos (técnico-tático) dos esportes trabalhados; • Simulações de jogo para aplicar fundamentos técnicos e táticos, compreendendo as dinâmicas dos esportes de marca."}, {"a": "6", "t": "1", "c": "EF67EF05", "e": "Esportes", "h": "Planejar e utilizar estratégias para solucionar os desafios técnicos e táticos, tanto nos esportes de marca, precisão, invasão e técnico-combinatórios como nas modalidades esportivas escolhidas para praticar de forma específica.", "o": "Esportes de Marca •Análise das situações de jogo para identificar oportunidades e desafios, promovendo o desenvolvimento de soluções criativas e adaptativas nas práticas dos esportes de marca."}, {"a": "6", "t": "1", "c": "EF67EF06", "e": "Esportes", "h": "Analisar as transformações na organização e na prática dos esportes em suas diferentes manifestações (profissional e comunitário/lazer).", "o": "Esportes de Marca •Conceituação de prática profissional e prática amadora no esporte; •Análise das influências culturais e sociais na prática dos esportes de marca, incluindo o papel da mídia e da comunidade."}, {"a": "6", "t": "1", "c": "EF67EF07", "e": "Esportes", "h": "Propor e produzir alternativas para experimentação dos esportes não disponíveis e/ou acessíveis na comunidade e das demais práticas corporais tematizadas na escola.", "o": "Esportes de Marca •Adaptação de jogos e atividades esportivas com materiais acessíveis, promovendo inclusão e experimentação."}, {"a": "6", "t": "1", "c": "EF67EF08/ES", "e": "", "h": "Experimentar e fruir exercícios físicos que solicitem diferentes capacidades físicas, identificando seus tipos (força, velocidade, resistência, flexibilidade) e as sensações corporais provocadas pela sua prática, evidenciando a importância do aprimoramento das capacidades físicas para realizar tarefas em situações do cotidiano.", "o": "Ginástica de condicionamento físico • Capacidades físicas voltadas para a promoção da saúde e aprimoramento funcional; • Desenvolvimento das capacidades físicas para a realização eficiente de tarefas diárias, promovendo autonomia e bem-estar; • Atividades relacionadas às capacidades físicas abordadas, além das respostas corporais que eles provocam (ex.: suor, alteração da frequência cardíaca, alteração da temperatura corporal etc.)."}, {"a": "6", "t": "1", "c": "EF67EF09-06/ES", "e": "", "h": "Construir, coletivamente, procedimentos e normas de convívio que viabilizem a participação de todos na prática de exercícios físicos, com o objetivo de promover a saúde. Enfatizando processos que levem os estudantes a compreenderem a relação entre o exercício físico e a saúde, identificando as principais capacidades físicas e estruturas corporais envolvidas nesse processo.", "o": "Ginástica de condicionamento físico •Adaptação de exercícios para respeitar as limitações individuais, garantindo a participação de todos e promovendo a saúde."}, {"a": "6", "t": "1", "c": "EF67EF10", "e": "Ginásticas", "h": "Diferenciar exercício físico de atividade física e propor alternativas para a prática de exercícios físicos dentro e fora do ambiente escolar.", "o": "Ginástica de condicionamento físico •Diferenciação entre Atividade Física e Exercício Físico; •Exploração de formas acessíveis e criativas de realizar exercícios físicos no cotidiano, considerando os recursos disponíveis dentro e fora do ambiente escolar."}, {"a": "6", "t": "2", "c": "EF67EF14", "e": "Lutas", "h": "Experimentar, fruir e recriar diferentes lutas do Brasil, valorizando a própria segurança e integridade física, bem como as dos demais.", "o": "Lutas do Brasil •Tarracá, Jiu-Jitsu Brasileiro, Capoeira, Maculelê, Luta Marajoara, entre outras; •Cuidados e segurança durante a execução das lutas; •Modalidades (curta, média e longa distância)."}, {"a": "6", "t": "2", "c": "EF67EF15", "e": "Lutas", "h": "Planejar e utilizar estratégias básicas das lutas do Brasil, respeitando o colega como oponente.", "o": "Lutas do Brasil •Desenvolvimento da leitura de movimento e antecipação para identificar oportunidades nas lutas, priorizando o respeito e a segurança do colega."}, {"a": "6", "t": "2", "c": "EF67EF16", "e": "Lutas", "h": "Identificar as características (códigos, rituais, elementos técnico-táticos, indumentária, materiais, instalações, instituições) das lutas do Brasil.", "o": "Lutas do Brasil •Elementos constitutivos das lutas do Brasil (códigos, rituais, elementos técnico-táticos, indumentária, materiais, instalações, instituições); •Análise da diversidade regional das lutas do Brasil, destacando como as influências culturais locais moldam as práticas, os rituais e os estilos de luta."}, {"a": "6", "t": "2", "c": "EF67EF17", "e": "Lutas", "h": "Problematizar preconceitos e estereótipos relacionados ao universo das lutas e demais práticas corporais, propondo alternativas para superá-los, com base na solidariedade, na justiça, na equidade e no respeito.", "o": "Lutas do Brasil •Origem e herança cultural; •Racismo e exclusão social atrelados às lutas; •Comportamentos preconceituosos/ injustos relacionados às lutas brasileiras; •Problematização das lutas como atividade ligada ao universo masculino"}, {"a": "6", "t": "3", "c": "EF67EF01/ES", "e": "Brincadeiras e jogos", "h": "Experimentar e fruir, na escola e fora dela, jogos eletrônicos diversos atrelados as práticas corporais e de diferentes gêneros, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais e etários.", "o": "Jogos eletrônicos •Jogos eletrônicos individuais e de interação coletiva com ênfase nos que envolvam o corpo em movimento; •Análise dos aspectos culturais e sociais dos jogos eletrônicos, promovendo respeito e inclusão entre diferentes gêneros e grupos etários."}, {"a": "6", "t": "3", "c": "EF67EF02", "e": "Brincadeiras e jogos", "h": "Identificar as transformações nas características dos jogos eletrônicos em função dos avanços das tecnologias e nas respectivas exigências corporais colocadas por esses diferentes tipos de jogos.", "o": "Jogos eletrônicos •Caracterização de diferentes tipos de jogos eletrônicos; •Influência dos jogos eletrônicos no sedentarismo; •Influência dos jogos eletrônicos na dependência tecnológica."}, {"a": "6", "t": "3", "c": "EF67EF11-06/ES", "e": "", "h": "Experimentar, fruir e recriar danças urbanas, identificando seus elementos constitutivos (ritmo, espaço, gestos), bem como capacidades físicas durante as práticas das danças, como a coordenação motora, o equilíbrio, a agilidade, a flexibilidade, entre outras. Promovendo aprendizagens sobre o percurso histórico das danças urbanas, partindo-se das suas modalidades originais. O estudo do elemento constituinte espaço possibilita interações com o componente curricular Geografia.", "o": "Danças urbanas •Hip Hop, Funk, Freestyle, Passinho e outros; •Elementos constitutivos da dança urbana (ritmo e expressão corporal; tempo, organização espacial e marcação musical)."}, {"a": "6", "t": "3", "c": "EF67EF12", "e": "Danças", "h": "Planejar e utilizar estratégias para aprender elementos constitutivos das danças urbanas.", "o": "Danças urbanas •Criação de sequências coreográficas que integrem os elementos das danças urbanas, promovendo a criatividade e a expressão individual."}, {"a": "6", "t": "3", "c": "EF67EF13/ES", "e": "", "h": "Diferenciar as danças urbanas das demais manifestações da dança, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais. Há, aqui, oportunidade de trabalho interdisciplinar com o componente curricular da Arte, no que se refere à investigação de diferentes tipos de dança.", "o": "Danças urbanas •Aspectos do contexto sociocultural (ritmos, passos básicos, expressão corporal, espaços, vestimentas) das danças urbanas e sua diferenciação das demais manifestações de dança; • Análise dos aspectos históricos e culturais que diferenciam as danças urbanas de outras formas de dança, ressaltando a valorização da diversidade cultural."}, {"a": "6", "t": "3", "c": "EF67EF18-06/ES", "e": "Práticas corporais de aventura", "h": "Experimentar e fruir diferentes práticas corporais de aventura urbanas, que sejam conhecidas ou praticadas pelos estudantes, valorizando a própria segurança e integridade física, bem como as dos demais.", "o": "Práticas corporais de aventura urbanas •Parkour, Rapel, Skate, Slackline e outros; •Cuidados/Riscos relacionados à prática; •Limites corporais e superação do receio da realização da prática de uma determina prática de aventura; •Adaptação de espaços para a prática."}, {"a": "6", "t": "3", "c": "EF67EF19", "e": "Práticas corporais de aventura", "h": "Identificar os riscos durante a realização de práticas corporais de aventura urbanas e planejar estratégias para sua superação.", "o": "Práticas corporais de aventura urbanas •Equipamentos de segurança necessários para a prática de cada modalidade; •Riscos envolvidos nas práticas corporais de aventura no meio urbano; •Importância da preparação física e mental, incluindo aquecimento, alongamento e técnicas de respiração, para minimizar riscos nas práticas de aventura urbanas."}, {"a": "6", "t": "3", "c": "EF67EF20/ES", "e": "Práticas corporais de aventura", "h": "Executar práticas corporais de aventura urbanas, que sejam conhecidas ou praticadas pelos estudantes, respeitando o patrimônio público e utilizando alternativas para a prática segura em diversos espaços.", "o": "Práticas corporais de aventura urbanas •Exploração de espaços urbanos adequados para atividades de aventura, enfatizando segurança, legalidade e respeito ao patrimônio público, promovendo consciência cidadã."}, {"a": "6", "t": "3", "c": "EF67EF21", "e": "Práticas corporais de aventura", "h": "Identificar a origem das práticas corporais de aventura e as possibilidades de recriá-las, reconhecendo as características (instrumentos, equipamentos de segurança, indumentária, organização) e seus tipos de práticas.", "o": "Práticas corporais de aventura urbanas •Definição e caracterização das práticas; •Análise das influências culturais e sociais que moldam as práticas de aventura, incluindo tradições locais e sua adaptação aos contextos urbanos; •Evolução tecnológica dos itens de segurança e equipamentos."}, {"a": "7", "t": "1", "c": "EF67EF03-07/ES", "e": "Esportes", "h": "Experimentar e fruir esportes de marca, precisão, invasão e técnico-combinatórios, por meio de modalidades menos familiares aos estudantes, valorizando o trabalho coletivo e o protagonismo.", "o": "Esportes de Invasão •Exemplos: Futebol, Futsal, Handebol, basquetebol, entre outros."}, {"a": "7", "t": "1", "c": "EF67EF05", "e": "Esportes", "h": "Planejar e utilizar estratégias para solucionar os desafios técnicos e táticos, tanto nos esportes de marca, precisão, invasão e técnicocombinatórios como nas modalidades esportivas escolhidas para praticar de forma específica.", "o": "Esportes de Invasão •Análise das situações de jogo para identificar oportunidades e desafios, promovendo o desenvolvimento de soluções criativas e adaptativas nas práticas dos esportes de invasão."}, {"a": "7", "t": "1", "c": "EF67EF06", "e": "Esportes", "h": "Analisar as transformações na organização e na prática dos esportes em suas diferentes manifestações (profissional e comunitário/lazer).", "o": "Esportes de Invasão •Conceituação de prática profissional e prática amadora no esporte; •Análise das influências culturais e sociais na prática dos esportes de invasão, incluindo o papel da mídia e da comunidade."}, {"a": "7", "t": "1", "c": "EF67EF07", "e": "Esportes.", "h": "Propor e produzir alternativas para experimentação dos esportes não disponíveis e/ou acessíveis na comunidade e das demais práticas corporais tematizadas na escola.", "o": "Esportes de Invasão •Adaptação de jogos e atividades esportivas com materiais acessíveis, promovendo inclusão e experimentação."}, {"a": "7", "t": "1", "c": "EF67EF08/ES", "e": "", "h": "Experimentar e fruir exercícios físicos que solicitem diferentes capacidades físicas, identificando seus tipos (força, velocidade, resistência, flexibilidade) e as sensações corporais provocadas pela sua prática, evidenciando a importância do aprimoramento das capacidades físicas para realizar tarefas em situações do cotidiano.", "o": "Ginástica de condicionamento físico •Capacidades físicas voltadas para a promoção da saúde e aprimoramento funcional; •Desenvolvimento das capacidades físicas para a realização eficiente de tarefas diárias, promovendo autonomia e bem-estar; • Atividades relacionadas às capacidades físicas abordadas, além das respostas corporais que eles provocam (ex.: suor, alteração da frequência cardíaca, alteração da temperatura corporal etc.)."}, {"a": "7", "t": "1", "c": "EF67EF09-07/ES", "e": "", "h": "Construir, coletivamente, procedimentos e normas de convívio que viabilizem a participação de todos na prática de exercícios físicos, com o objetivo de promover a saúde. Enfatizando processos que levem os estudantes a reconhecerem que existem diferenças de condicionamento físico entre eles e propor atividades que sejam adequadas a todos.", "o": "Ginástica de condicionamento físico •Adaptação de exercícios para respeitar as limitações individuais, garantindo a participação de todos e promovendo a saúde."}, {"a": "7", "t": "1", "c": "EF67EF10", "e": "Ginásticas", "h": "Diferenciar exercício físico de atividade física e propor alternativas para a prática de exercícios físicos dentro e fora do ambiente escolar.", "o": "Ginástica de condicionamento físico •Diferenciação entre Exercício Físico e Atividade Física; •Exploração de formas acessíveis e criativas de realizar exercícios físicos no cotidiano, considerando os recursos disponíveis dentro e fora do ambiente escolar."}, {"a": "7", "t": "2", "c": "EF67EF04", "e": "Esportes", "h": "Praticar um ou mais esportes de marca, precisão, invasão e técnico-combinatórios oferecidos pela escola, usando habilidades técnico-táticas básicas e respeitando regras.", "o": "Esportes de Invasão •Regras; •Fundamentos básicos (técnico-tático) dos esportes trabalhados; •Simulações de jogo para aplicar fundamentos técnicos e táticos, compreendendo as dinâmicas dos esportes de invasão."}, {"a": "7", "t": "2", "c": "EF67EF14", "e": "Lutas", "h": "Experimentar, fruir e recriar diferentes lutas do Brasil, valorizando a própria segurança e integridade física, bem como as dos demais.", "o": "Lutas do Brasil •Tarracá, Jiu-Jitsu Brasileiro, Capoeira, Maculelê, Luta Marajoara, entre outras; •Cuidados e segurança durante a execução das lutas; •Modalidades (curta, média e longa distância)."}, {"a": "7", "t": "2", "c": "EF67EF15", "e": "Lutas", "h": "Planejar e utilizar estratégias básicas das lutas do Brasil, respeitando o colega como oponente.", "o": "Lutas do Brasil •Desenvolvimento da leitura de movimento e antecipação para identificar oportunidades nas lutas, priorizando o respeito e a segurança do/a colega."}, {"a": "7", "t": "2", "c": "EF67EF16", "e": "Lutas", "h": "Identificar as características (códigos, rituais, elementos técnico-táticos, indumentária, materiais, instalações, instituições) das lutas do Brasil.", "o": "Lutas do Brasil •Elementos constitutivos das lutas do Brasil (códigos, rituais, elementos técnico-táticos, indumentária, materiais, instalações, instituições); •Análise da diversidade regional das lutas do Brasil, destacando como as influências culturais locais moldam as práticas, os rituais e os estilos de luta."}, {"a": "7", "t": "2", "c": "EF67EF17", "e": "Lutas", "h": "Problematizar preconceitos e estereótipos relacionados ao universo das lutas e demais práticas corporais, propondo alternativas para superá-los, com base na solidariedade, na justiça, na equidade e no respeito.", "o": "Lutas do Brasil •Origem e herança cultural; •Racismo e exclusão social atrelados às lutas; •Comportamentos preconceituosos/ injustos relacionados às lutas brasileiras; •Problematização das lutas como atividade ligada ao universo masculino."}, {"a": "7", "t": "3", "c": "EF67EF01/ES", "e": "Brincadeiras e jogos", "h": "Experimentar e fruir, na escola e fora dela, jogos eletrônicos diversos e de diferentes gêneros, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais e etários.", "o": "Jogos eletrônicos •Jogos eletrônicos individuais e de interação coletiva com ênfase nos que envolvam o corpo em movimento; •Análise dos aspectos culturais e sociais dos jogos eletrônicos, promovendo respeito e inclusão entre diferentes gêneros e grupos etários."}, {"a": "7", "t": "3", "c": "EF67EF02", "e": "Brincadeiras e jogos", "h": "Identificar as transformações nas características dos jogos eletrônicos em função dos avanços das tecnologias e nas respectivas exigências corporais colocadas por esses diferentes tipos de jogos.", "o": "Jogos eletrônicos •Caracterização de diferentes tipos de jogos eletrônicos; •Influência dos jogos eletrônicos no sedentarismo; •Análise da influência dos jogos eletrônicos na dependência tecnológica."}, {"a": "7", "t": "3", "c": "EF67EF11-07/ES", "e": "", "h": "Experimentar, fruir e recriar danças urbanas, identificando seus elementos constitutivos (ritmo, espaço, gestos) bem como capacidades físicas durante as práticas das danças, utilizando-as como fator de ampliação de repertório motor dos estudantes. Promovendo aprendizagens sobre o percurso histórico das danças urbanas que são praticadas nos dias de hoje.", "o": "Danças urbanas •Hip Hop, Funk, Freestyle, Passinho e outros; •Elementos constitutivos da dança urbana (ritmo e expressão corporal; tempo, organização espacial e marcação musical)."}, {"a": "7", "t": "3", "c": "EF67EF12", "e": "Danças", "h": "Planejar e utilizar estratégias para aprender elementos constitutivos das danças urbanas.", "o": "Danças urbanas •Criação de sequências coreográficas que integrem os elementos das danças urbanas, promovendo a criatividade e a expressão individual."}, {"a": "7", "t": "3", "c": "EF67EF13/ES", "e": "", "h": "Diferenciar as danças urbanas das demais manifestações da dança, valorizando e respeitando os sentidos e significados atribuídos a eles por diferentes grupos sociais. Há, aqui, oportunidade de trabalho interdisciplinar com o componente curricular da Arte, no que se refere à investigação de diferentes tipos de dança.", "o": "Danças urbanas • Aspectos do contexto sociocultural (ritmos, passos básicos, expressão corporal, espaços, vestimentas) das danças urbanas e sua diferenciação das demais manifestações de dança; • Análise dos aspectos históricos e culturais que diferenciam as danças urbanas de outras formas de dança, ressaltando a valorização da diversidade cultural."}, {"a": "7", "t": "3", "c": "EF67EF18-07/ES", "e": "Práticas corporais de aventura", "h": "Experimentar e fruir diferentes práticas corporais de aventura urbanas, que não façam parte do contexto social dos estudantes, valorizando a própria segurança e integridade física, bem como as dos demais.", "o": "Práticas corporais de aventura urbanas •Parkour, Rapel, Skate, Slackline e outros; •Cuidados/Riscos relacionados à prática; •Limites corporais e superação do receio da realização da prática de uma determina prática de aventura; •Adaptação de espaços para a prática."}, {"a": "7", "t": "3", "c": "EF67EF19", "e": "Práticas corporais de aventura", "h": "Identificar os riscos durante a realização de práticas corporais de aventura urbanas e planejar estratégias para sua superação.", "o": "Práticas corporais de aventura urbanas •Equipamentos de segurança necessários para a prática de cada modalidade; •Importância da preparação física e mental, incluindo aquecimento, alongamento e técnicas de respiração, para minimizar riscos nas práticas de aventura urbanas. •Riscos envolvidos nas práticas corporais de aventura no meio urbano;"}, {"a": "7", "t": "3", "c": "EF67EF20", "e": "Práticas corporais de aventura", "h": "Executar práticas corporais de aventura urbanas, respeitando o patrimônio público e utilizando alternativas para a prática segura em diversos espaços.", "o": "Práticas corporais de aventura urbanas •Exploração de espaços urbanos adequados para atividades de aventura, enfatizando segurança, legalidade e respeito ao patrimônio público, promovendo consciência cidadã."}, {"a": "7", "t": "3", "c": "EF67EF21", "e": "Práticas corporais de aventura", "h": "Identificar a origem das práticas corporais de aventura e as possibilidades de recriá-las, reconhecendo as características (instrumentos, equipamentos de segurança, indumentária, organização) e seus tipos de práticas.", "o": "Práticas corporais de aventura urbanas •Definição e caracterização das práticas; •Análise das influências culturais e sociais que moldam as práticas de aventura, incluindo tradições locais e sua adaptação aos contextos urbanos; •Evolução tecnológica dos itens de segurança e equipamentos."}, {"a": "8", "t": "1", "c": "EF89EF01/ES", "e": "", "h": "Experimentar diferentes papéis (jogador, árbitro e técnico) e fruir os esportes de rede/parede, campo e taco, invasão e combate, valorizando o trabalho coletivo e o protagonismo. A experimentação de diferentes papéis nos esportes possibilita explorar situações de aprendizagem nas quais os estudantes exercitem o senso de justiça, o diálogo e a alteridade.", "o": "Esportes de Invasão •Esportes de invasão (Basquetebol, frisbee, futebol, futsal, futebol americano, handebol, hóquei, rúgbi, entre outros); •Vivência de outros papéis vinculados ao esporte."}, {"a": "8", "t": "1", "c": "EF89EF02", "e": "Esportes", "h": "Praticar um ou mais esportes de rede/parede, campo e taco, invasão e combate oferecidos pela escola, usando habilidades técnico-táticas básicas.", "o": "Esportes de Invasão •Técnicas de fundamentos básicos dos esportes de invasão, como dribles, passes, arremessos e movimentação, enfatizando sua aplicação prática nas situações de jogo."}, {"a": "8", "t": "1", "c": "EF89EF03", "e": "Esportes", "h": "Formular e utilizar estratégias para solucionar os desafios técnicos e táticos, tanto nos esportes de campo e taco, rede/parede, invasão e combate como nas modalidades esportivas escolhidas para praticar de forma específica.", "o": "Esportes de Invasão •Análise de situações de jogo para identificar oportunidades e desafios, formulando táticas para superá-los, como posicionamento em campo/quadra e movimentação em equipe."}, {"a": "8", "t": "1", "c": "EF89EF04", "e": "Esportes", "h": "Identificar os elementos técnicos ou técnico táticos individuais, combinações táticas, sistemas de jogo e regras das modalidades esportivas praticadas, bem como diferenciar as modalidades esportivas com base nos critérios da lógica interna das categorias de esporte: rede/parede, campo e taco, invasão e combate.", "o": "Esportes de Invasão •Análise das características dos esportes de invasão, enfocando a dinâmica de posse de bola, movimentação sem a bola e uso do espaço, além da colaboração entre jogadores/as e sua influência nas estratégias coletivas."}, {"a": "8", "t": "1", "c": "EF89EF05", "e": "Esportes", "h": "Identificar as transformações históricas do fenômeno esportivo e discutir alguns de seus problemas (doping, corrupção, violência, etc.) e a forma como as mídias os apresentam.", "o": "Esportes de Invasão •Transformações históricas do fenômeno esportivo; •Exclusão e invisibilidade feminina nos esportes; •Racismo no esporte e na mídia; •Influência das mídias sociais e tradicionais na percepção dos esportes de invasão."}, {"a": "8", "t": "1", "c": "EF89EF06", "e": "Esportes", "h": "Verificar locais disponíveis na comunidade para a prática de esportes e das demais práticas corporais tematizadas na escola, propondo e produzindo alternativas para utilizá-los no tempo livre.", "o": "Esportes de Invasão •Identificação de equipamentos e materiais necessários para a prática segura dos esportes de invasão nos espaços comunitários."}, {"a": "8", "t": "1", "c": "EF89EF16", "e": "Lutas", "h": "Experimentar e fruir a execução dos movimentos pertencentes às lutas do mundo, adotando procedimentos de segurança e respeitando o oponente.", "o": "Lutas do mundo •Lutas de diferentes lugares do mundo (aikido, kung fu, wing chun, kendo, judô, boxe, karatê, muay thai, esgrima, luta greco-romana, entre outros); •Discussão sobre a importância do respeito e da ética nas lutas, promovendo um ambiente seguro e saudável para todos/as os/as praticantes."}, {"a": "8", "t": "1", "c": "EF89EF17", "e": "Lutas", "h": "Planejar e utilizar estratégias básicas das lutas experimentadas, reconhecendo as suas características técnico-táticas.", "o": "Lutas do mundo •Análise das características técnico-táticas específicas de cada modalidade de luta, incluindo posições, movimentos e combinações; •Reflexão sobre como adaptar as estratégias de luta para diferentes contextos e oponentes, promovendo a flexibilidade tática."}, {"a": "8", "t": "1", "c": "EF89EF18", "e": "Lutas", "h": "Discutir as transformações históricas, o processo de esportivização e a midiatização de uma ou mais lutas, valorizando e respeitando as culturas de origem.", "o": "Lutas do mundo •Características e transformações históricas das lutas estudadas; •Processo de esportivização das lutas; •Influência da mídia nas competições de lutas; •Diferenciação entre luta, arte marcial e esporte de combate; •Filosofia das lutas."}, {"a": "8", "t": "2", "c": "EF89EF07-08/ES", "e": "", "h": "Experimentar e fruir um ou mais programas de exercícios físicos, inicialmente investigando e experimentando programas e tipos de exercícios físicos existentes, identificando as exigências corporais desses diferentes programas e reconhecendo a importância de uma prática individualizada, adequada às características e necessidades de cada sujeito.", "o": "Ginástica de condicionamento físico •Ginásticas de condicionamento físico (calistenia, musculação, jump, step, ginástica localizada, treinamento funcional, entre outros); •Diferenciação entre os objetivos de cada programa (perda de peso, ganho de massa muscular, aumento da resistência cardiovascular, etc.); •Associação das características, necessidades e interesses de cada sujeito ao programa mais adequado."}, {"a": "8", "t": "2", "c": "EF89EF08", "e": "Ginásticas", "h": "Discutir as transformações históricas dos padrões de desempenho, saúde e beleza, considerando a forma como são apresentados nos diferentes meios (científico, midiático etc.).", "o": "Ginástica de condicionamento físico •Evolução histórica dos padrões de desempenho, saúde e beleza; • Impacto da indústria da saúde e do fitness na formação de conceitos sobre desempenho físico e estética; •Conceito de beleza e marginalização de corpos negros e indígenas; •Relação entre saúde física, mental e a pressão estética imposta por padrões midiáticos."}, {"a": "8", "t": "2", "c": "EF89EF09", "e": "Ginásticas", "h": "Problematizar a prática excessiva de exercícios físicos e o uso de medicamentos para a ampliação do rendimento ou potencialização das transformações corporais.", "o": "Ginástica de condicionamento físico •Transtornos de imagem corporal e seus impactos na saúde; •Discussão sobre a ética no uso de medicamentos e suplementos no contexto esportivo e fitness; •Problematização do uso de medicamentos e suplementação; •Alternativas saudáveis para a melhoria do condicionamento físico, enfatizando a importância de um estilo de vida equilibrado."}, {"a": "8", "t": "2", "c": "EF89EF10-08/ES", "e": "Ginásticas", "h": "Experimentar e fruir um ou mais tipos de ginástica de conscientização corporal, que os estudantes conheçam ou pratiquem, identificando as exigências corporais dos mesmos.", "o": "Ginástica de conscientização corporal •Ginásticas de conscientização corporal (yoga, thai chi chuan, pilates, meditação) e exigências corporais relacionadas."}, {"a": "8", "t": "2", "c": "EF89EF11", "e": "Ginásticas", "h": "Identificar as diferenças e semelhanças entre a ginástica de conscientização corporal e as de condicionamento físico e discutir como a prática de cada uma dessas manifestações pode contribuir para a melhoria das condições de vida, saúde, bem-estar e cuidado consigo mesmo.", "o": "Ginástica de conscientização corporal •Conscientização corporal e condicionamento físico: definição, objetivos, elementos e características; •Benefícios dessas práticas para as qualidades de vida, saúde, bem-estar e cuidado consigo mesmo; •Reflexão sobre a percepção corporal e como ela pode impactar a autoestima e a autoconfiança."}, {"a": "8", "t": "3", "c": "EF89EF12/ES", "e": "Danças", "h": "Experimentar, fruir e recriar danças de salão, valorizando a diversidade cultural e respeitando a tradição dessas culturas. Há, aqui, oportunidade de trabalho interdisciplinar com o componente curricular da Arte, no que se refere à experimentação e fruição de diversos tipos de dança.", "o": "Danças de salão •Danças de salão (forró, samba de gafieira, zouk, salsa, cumbia, valsa, kizomba, bolero, bachata, xote, maxixe, soltinho, lambada, entre outros)."}, {"a": "8", "t": "3", "c": "EF89EF13/ES", "e": "Danças", "h": "Planejar e utilizar estratégias para se apropriar dos elementos constitutivos (ritmo, espaço, gestos) das danças de salão. O estudo do elemento constituinte espaço possibilita interações com o componente curricular Geografia.", "o": "Danças de salão •Elementos que compõem as danças de salão trabalhadas, como passos, ritmos, estilos, espaços e vestimentas."}, {"a": "8", "t": "3", "c": "EF89EF14/ES", "e": "Danças", "h": "Discutir estereótipos e preconceitos relativos às danças de salão e demais práticas corporais e propor alternativas para sua superação. Há, aqui, oportunidade de trabalho interdisciplinar com Arte, no que se refere à problematização de estereótipos e preconceitos relacionados às práticas corporais.", "o": "Danças de salão •Estereótipos sobre os papéis de gênero tradicionalmente estabelecidos nas danças de salão; •Variações regionais das danças de salão e histórico de opressões ou marginalização racial, particularmente de culturas afrodescendentes; •Uso de músicas e estilos de dança que reflitam a diversidade cultural e social, representando diferentes grupos étnicos e classes sociais; •Diversidade e inclusão nas danças de salão."}, {"a": "8", "t": "3", "c": "EF89EF15", "e": "Danças", "h": "Analisar as características (ritmos, gestos, coreografias e músicas) das danças de salão, bem como suas transformações históricas e os grupos de origem.", "o": "Danças de salão •Discussão sobre os grupos sociais que originaram e popularizaram as danças de salão, incluindo aspectos de classe, etnia e cultura; •Exame das transformações nas danças de salão ao longo do tempo, considerando mudanças nos estilos, ritmos e contextos sociais."}, {"a": "8", "t": "3", "c": "EF89EF19-08/ES", "e": "Práticas corporais de aventura", "h": "Experimentar e fruir diferentes práticas corporais de aventura na natureza, partindo de modalidades com exigências mais simples, valorizando a própria segurança e integridade física, bem como as dos demais, respeitando o patrimônio natural e minimizando os impactos de degradação ambiental.", "o": "Práticas corporais de aventura na natureza •Práticas corporais de aventura na natureza (arborismo, trekking, escalada, corrida de orientação/aventura, rapel, stand up paddle, slackline/waterline, sandboard, kitesurf, surfe, bodyboard, entre outros), enfatizando os cuidados durante a prática; •Educação ambiental e sustentabilidade; •Responsabilidade ambiental."}, {"a": "8", "t": "3", "c": "EF89EF20", "e": "Práticas corporais de aventura", "h": "Identificar riscos, formular estratégias e observar normas de segurança para superar os desafios na realização de práticas corporais de aventura na natureza.", "o": "Práticas corporais de aventura na natureza •Riscos e normas de segurança nas práticas abordadas; •Discussão sobre a importância da hidratação e nutrição antes, durante e após as atividades de aventura."}, {"a": "8", "t": "3", "c": "EF89EF21", "e": "Práticas corporais de aventura", "h": "Identificar as características (equipamentos de segurança, instrumentos, indumentária, organização) das práticas corporais de aventura na natureza, bem como suas transformações históricas.", "o": "Práticas corporais de aventura na natureza •Caracterização das práticas de aventura abordadas: organização, equipamentos de segurança, vestimentas; •Histórico das práticas corporais de aventura, destacando marcos significativos, influências culturais e a evolução das técnicas e equipamentos utilizados."}, {"a": "9", "t": "1", "c": "EF89EF01/ES", "e": "", "h": "Experimentar diferentes papéis (jogador, árbitro e técnico) e fruir os esportes de rede/parede, campo e taco, invasão e combate, valorizando o trabalho coletivo e o protagonismo. A experimentação de diferentes papéis nos esportes possibilita explorar situações de aprendizagem nas quais os estudantes exercitem o senso de justiça, o diálogo e a alteridade.", "o": "Esportes de Rede e Parede •Esportes de rede/parede (Voleibol, tênis de campo, tênis de mesa, badminton, peteca, voleibol de praia, punhobol, raquetebol, squash, beach tênis, entre outros); •Vivência de outros papéis vinculados ao esporte."}, {"a": "9", "t": "1", "c": "EF89EF02", "e": "Esportes", "h": "Praticar um ou mais esportes de rede/parede, campo e taco, invasão e combate oferecidos pela escola, usando habilidades técnico-táticas básicas.", "o": "Esportes de Rede e Parede •Técnicas de fundamentos básicos dos esportes de rede e parede, enfatizando sua aplicação prática nas situações de jogo."}, {"a": "9", "t": "1", "c": "EF89EF03", "e": "Esportes", "h": "Formular e utilizar estratégias para solucionar os desafios técnicos e táticos, tanto nos esportes de campo e taco, rede/parede, invasão e combate como nas modalidades esportivas escolhidas para praticar de forma específica.", "o": "Esportes de Rede e Parede •Análise de situações de jogo para identificar oportunidades e desafios, formulando táticas para superá-los, como posicionamento em campo/quadra e movimentação."}, {"a": "9", "t": "1", "c": "EF89EF04", "e": "Esportes", "h": "Identificar os elementos técnicos ou técnico-táticos individuais, combinações táticas, sistemas de jogo e regras das modalidades esportivas praticadas, bem como diferenciar as modalidades esportivas com base nos critérios da lógica interna das categorias de esporte: rede/parede, campo e taco, invasão e combate.", "o": "Esportes de Rede e Parede •Identificação das combinações táticas e sistemas de jogo nos esportes de rede e parede; •Exploração das variações nas regras e suas implicações na dinâmica de jogo nos esportes de rede e parede."}, {"a": "9", "t": "1", "c": "EF89EF06", "e": "Esportes", "h": "Verificar locais disponíveis na comunidade para a prática de esportes e das demais práticas corporais tematizadas na escola, propondo e produzindo alternativas para utilizá-los no tempo livre.", "o": "Esportes de Rede e Parede •Identificação de equipamentos e materiais necessários para a prática segura dos esportes de rede e parede nos espaços comunitários."}, {"a": "9", "t": "1", "c": "EF89EF16", "e": "Lutas", "h": "Experimentar e fruir a execução dos movimentos pertencentes às lutas do mundo, adotando procedimentos de segurança e respeitando o oponente.", "o": "Lutas do mundo •Lutas de diferentes lugares do mundo (aikido, kung fu, wing chun, kendo, judô, boxe, karatê, muay thai, esgrima, luta greco-romana, entre outros); •Discussão sobre a importância do respeito e da ética nas lutas, promovendo um ambiente seguro e saudável para todos/as os/as praticantes."}, {"a": "9", "t": "1", "c": "EF89EF17", "e": "Lutas", "h": "Planejar e utilizar estratégias básicas das lutas experimentadas, reconhecendo as suas características técnico-táticas.", "o": "Lutas do mundo •Análise das características técnico-táticas específicas de cada modalidade de luta, incluindo posições, movimentos e combinações; •Reflexão sobre como adaptar as estratégias de luta para diferentes contextos e oponentes, promovendo a flexibilidade tática."}, {"a": "9", "t": "1", "c": "EF89EF18", "e": "Lutas", "h": "Discutir as transformações históricas, o processo de esportivização e a midiatização de uma ou mais lutas, valorizando e respeitando as culturas de origem.", "o": "Lutas do mundo •Características e transformações históricas das lutas estudadas; •Processo de esportivização das lutas; •Influência da mídia nas competições de lutas; •Diferenciação entre luta, arte marcial e esporte de combate; •Filosofia das lutas."}, {"a": "9", "t": "2", "c": "EF89EF07-09/ES", "e": "", "h": "Experimentar e fruir um ou mais programas de exercícios físicos, identificando as exigências corporais desses diferentes programas e reconhecendo a importância de uma prática individualizada, adequada às características e necessidades de cada sujeito. A partir das experiências e expectativas vivenciadas no ano anterior, propor sequências de atividades individualizadas para que pratiquem individualmente e coletivamente.", "o": "Ginástica de condicionamento físico •Ginásticas de condicionamento físico (calistenia, musculação, jump, step, ginástica localizada, treinamento funcional, entre outros); •Diferenciação entre os objetivos de cada programa (perda de peso, ganho de massa muscular, aumento da resistência cardiovascular etc.); •Associação das características, necessidades e interesses de cada sujeito ao programa mais adequado."}, {"a": "9", "t": "2", "c": "EF89EF08", "e": "Ginásticas", "h": "Discutir as transformações históricas dos padrões de desempenho, saúde e beleza, considerando a forma como são apresentados nos diferentes meios (científico, midiático etc.).", "o": "Ginástica de condicionamento físico •Evolução histórica dos padrões de desempenho, saúde e beleza; •Impacto da indústria da saúde e do fitness na formação de conceitos sobre desempenho físico e estética; •Conceito de beleza e marginalização de corpos negros e indígenas; •Relação entre saúde física, mental e a pressão estética imposta por padrões midiáticos."}, {"a": "9", "t": "2", "c": "EF89EF09", "e": "Ginásticas", "h": "Problematizar a prática excessiva de exercícios físicos e o uso de medicamentos para a ampliação do rendimento ou potencialização das transformações corporais.", "o": "Ginástica de condicionamento físico •Transtornos de imagem corporal e seus impactos na saúde; •Discussão sobre a ética no uso de medicamentos e suplementos no contexto esportivo e fitness; •Problematização do uso de medicamentos e suplementação; •Alternativas saudáveis para a melhoria do condicionamento físico, enfatizando a importância de um estilo de vida equilibrado."}, {"a": "9", "t": "2", "c": "EF89EF10-09/ES", "e": "Ginásticas", "h": "Experimentar e fruir um ou mais tipos de ginástica de conscientização corporal, menos familiares aos estudantes, identificando as exigências corporais dos mesmos.", "o": "Ginástica de conscientização corporal •Ginásticas de conscientização corporal (yoga, thai chi chuan, pilates, meditação) e exigências corporais relacionadas; •Atividades práticas para explorar a conexão mentecorpo em cada uma das modalidades."}, {"a": "9", "t": "2", "c": "EF89EF11", "e": "Ginásticas", "h": "Identificar as diferenças e semelhanças entre a ginástica de conscientização corporal e as de condicionamento físico e discutir como a prática de cada uma dessas manifestações pode contribuir para a melhoria das condições de vida, saúde, bem-estar e cuidado consigo mesmo.", "o": "Ginástica de conscientização corporal •Conscientização corporal e condicionamento físico: definição, objetivos, elementos e características; •Benefícios dessas práticas para as qualidades de vida, saúde, bem-estar e cuidado consigo mesmo; •Reflexão sobre a percepção corporal e como ela pode impactar a autoestima e a autoconfiança."}, {"a": "9", "t": "2", "c": "EF89EF12/ES", "e": "Danças", "h": "Experimentar, fruir e recriar danças de salão, valorizando a diversidade cultural e respeitando a tradição dessas culturas. Há, aqui, oportunidade de trabalho interdisciplinar com o componente curricular da Arte, no que se refere à experimentação e fruição de diversos tipos de dança.", "o": "Danças de salão •Danças de salão (forró, samba de gafieira, zouk, salsa, cumbia, valsa, kizomba, bolero, bachata, xote, maxixe, soltinho, lambada, entre outros)."}, {"a": "9", "t": "2", "c": "EF89EF13/ES", "e": "Danças", "h": "Planejar e utilizar estratégias para se apropriar dos elementos constitutivos (ritmo, espaço, gestos) das danças de salão. O estudo do elemento constituinte espaço possibilita interações com o componente curricular Geografia.", "o": "Danças de salão •Elementos que compõem as danças de salão trabalhadas, como passos, ritmos, estilos, espaços e vestimentas."}, {"a": "9", "t": "2", "c": "EF89EF14/ES", "e": "", "h": "Discutir estereótipos e preconceitos relativos às danças de salão e demais práticas corporais e propor alternativas para sua superação. Há, aqui, oportunidade de trabalho interdisciplinar com Arte, no que se refere à problematização de estereótipos e preconceitos relacionados às práticas corporais. Há oportunidade de trabalho com Língua Portuguesa.", "o": "Danças de salão •Estereótipos sobre os papéis de gênero tradicionalmente estabelecidos nas danças de salão; •Variações regionais das danças de salão e histórico de opressões ou marginalização racial, particularmente de culturas afrodescendentes; •Uso de músicas e estilos de dança que reflitam a diversidade cultural e social, representando diferentes grupos étnicos e classes sociais; •Diversidade e inclusão nas danças de salão."}, {"a": "9", "t": "2", "c": "EF89EF15", "e": "Danças", "h": "Analisar as características (ritmos, gestos, coreografias e músicas) das danças de salão, bem como suas transformações históricas e os grupos de origem.", "o": "Danças de salão •Discussão sobre os grupos sociais que originaram e popularizaram as danças de salão, incluindo aspectos de classe, etnia e cultura; •Exame das transformações nas danças de salão ao longo do tempo, considerando mudanças nos estilos, ritmos e contextos sociais."}, {"a": "9", "t": "3", "c": "EF89EF05", "e": "Esportes", "h": "Identificar as transformações históricas do fenômeno esportivo e discutir alguns de seus problemas (doping, corrupção, violência, etc.) e a forma como as mídias os apresentam.", "o": "Esportes de Rede e Parede •Transformações históricas do fenômeno esportivo; •Representações Midiáticas e estereótipos de Gênero; •Racismo e desigualdade racial nos esportes; •Elitismo e exclusão social; •LGBTfobia nos esportes; •Violência e ética nos esportes."}, {"a": "9", "t": "3", "c": "EF89EF19-09/ES", "e": "Práticas corporais de aventura", "h": "Experimentar e fruir diferentes práticas corporais de aventura na natureza, com modalidades com exigências um pouco mais complexas, valorizando a própria segurança e integridade física, bem como as dos demais, respeitando o patrimônio natural e minimizando os impactos de degradação ambiental.", "o": "Práticas corporais de aventura na natureza •Práticas corporais de aventura na natureza (arborismo, trekking, escalada, corrida de orientação/aventura, rapel, stand up paddle, slackline/waterline, sandboard, kitesurf, surfe, bodyboard, entre outros), enfatizando os cuidados durante a prática; •Educação ambiental e sustentabilidade; •Princípios de respeito e cuidado com a biodiversidade durante as atividades, incluindo a observação de fauna e flora sem causar danos."}, {"a": "9", "t": "3", "c": "EF89EF20", "e": "Práticas corporais de aventura", "h": "Identificar riscos, formular estratégias e observar normas de segurança para superar os desafios na realização de práticas corporais de aventura na natureza.", "o": "Práticas corporais de aventura na natureza •Riscos e normas de segurança nas práticas abordadas; •Discussão sobre a importância da hidratação e nutrição antes, durante e após as atividades de aventura."}, {"a": "9", "t": "3", "c": "EF89EF21", "e": "Práticas corporais de aventura", "h": "Identificar as características (equipamentos de segurança, instrumentos, indumentária, organização) das práticas corporais de aventura na natureza, bem como suas transformações históricas.", "o": "Práticas corporais de aventura na natureza •Caracterização das práticas de aventura abordadas: organização, equipamentos de segurança, vestimentas; •Histórico das práticas corporais de aventura, destacando marcos significativos, influências culturais e a evolução das técnicas e equipamentos utilizados."}], "Ensino Religioso": [{"a": "6", "t": "1", "c": "EF06ER01", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer o papel da tradição escrita na preservação de memórias, acontecimentos e ensinamentos religiosos.", "o": "Tradição escrita: registro dos ensinamentos sagrados. •Conhecendo o sagrado pelos textos religiosos; •Textos religiosos e modos de vida; •Textos religiosos e interpretação."}, {"a": "6", "t": "1", "c": "EF06ER02", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer e valorizar a diversidade de textos religiosos escritos (textos do Budismo, Cristianismo, Espiritismo, Hinduísmo, Islamismo, Judaísmo, entre outros).", "o": "Tradição escrita: registro dos ensinamentos sagrados. •Conhecendo o sagrado pelos textos religiosos; •Textos religiosos e modos de vida; •Textos religiosos e interpretação."}, {"a": "6", "t": "2", "c": "EF06ER03", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer, em textos escritos, ensinamentos relacionados a modos de ser e viver evidenciando os códigos morais das religiões estudadas.", "o": "Ensinamentos da tradição escrita •Textos religiosos e interpretação (Possíveis tópicos a serem trabalhados: Livro de Mórmon, Codificação Espírita, Tradição oral do Candomblé, da Umbanda e de povos indígenas brasileiros, Tao Te Ching, Vedas, Bíblia, dentre outros); •Funções dos textos sagrados."}, {"a": "6", "t": "2", "c": "EF06ER04", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer que os textos escritos são utilizados pelas tradições religiosas de maneiras diversas.", "o": "Ensinamentos da tradição escrita •Textos religiosos e interpretação (Possíveis tópicos a serem trabalhados: Livro de Mórmon, Codificação Espírita, Tradição oral do Candomblé, da Umbanda e de povos indígenas brasileiros, Tao Te Ching, Vedas, Bíblia, dentre outros); •Funções dos textos sagrados."}, {"a": "6", "t": "2", "c": "EF06ER05", "e": "Crenças religiosas e filosofias de vida", "h": "Discutir como o estudo e a interpretação dos textos religiosos influenciam os adeptos a vivenciarem os ensinamentos das tradições religiosas, por exemplo, noções de \"Certo e errado\" / \"Bem e mal\".", "o": "Ensinamentos da tradição escrita •Textos religiosos e interpretação (Possíveis tópicos a serem trabalhados: Livro de Mórmon, Codificação Espírita, Tradição oral do Candomblé, da Umbanda e de povos indígenas brasileiros, Tao Te Ching, Vedas, Bíblia, dentre outros); •Funções dos textos sagrados."}, {"a": "6", "t": "3", "c": "EF06ER06", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer a importância dos mitos, ritos, símbolos e textos na estruturação das diferentes crenças, tradições e movimentos religiosos.", "o": "Símbolos, ritos e mitos religiosos •A linguagem simbólica – o conceito de símbolo; •Conceito de mito. •Os tipos de mito (Mitos heroicos, mitos de origem e de criação, mitos de fim do mundo e de morte, dentre outros.); •Conceito de rito; •Ritos religiosos e ritos seculares."}, {"a": "6", "t": "3", "c": "EF06ER07", "e": "Crenças religiosas e filosofias de vida", "h": "Exemplificar a relação entre mito, rito e símbolo nas práticas celebrativas de diferentes tradições religiosas.", "o": "Símbolos, ritos e mitos religiosos •A linguagem simbólica – o conceito de símbolo; •Conceito de mito. •Os tipos de mito (Mitos heroicos, mitos de origem e de criação, mitos de fim do mundo e de morte, dentre outros.); •Conceito de rito; •Ritos religiosos e ritos seculares."}, {"a": "7", "t": "1", "c": "EF07ER01", "e": "Manifestações religiosas", "h": "Reconhecer e respeitar as práticas de comunicação com as divindades em distintas manifestações e tradições religiosas.", "o": "Místicas e espiritualidades •Conceitos de mística e de experiências místicas; •Conceitos e práticas de espiritualidade; •Espiritualidade e religião; •O silêncio e a comunicação com as divindades (votos de silêncio, o Mauna, as danças dos povos indígenas, nas religiões afro-brasileiras, a dança dervixe, dentre outras)."}, {"a": "7", "t": "1", "c": "EF07ER02", "e": "Manifestações religiosas", "h": "Identificar práticas de espiritualidade utilizadas pelas pessoas em determinadas situações (acidentes, doenças, fenômenos climáticos, anseios pessoais e familiares e morte).", "o": "Místicas e espiritualidades •Conceitos de mística e de experiências místicas; •Conceitos e práticas de espiritualidade; •Espiritualidade e religião; •O silêncio e a comunicação com as divindades (votos de silêncio, o Mauna, as danças dos povos indígenas, nas religiões afro-brasileiras, a dança dervixe, dentre outras)."}, {"a": "7", "t": "2", "c": "EF07ER03", "e": "Manifestações religiosas", "h": "Reconhecer os papéis atribuídos às lideranças de diferentes tradições religiosas.", "o": "Lideranças religiosas •O conceito de liderança; •Formação de líderes; •Exemplos de grandes líderes e grandes líderes religiosos (Malala Yousafzai, Irmã Dorothy Stang, Moisés, papa Francisco, Chico Xavier, dentre outros); •Líderes religiosos das mais diversas religiões; •Lideranças religiosas e a busca pelo bem comum."}, {"a": "7", "t": "2", "c": "EF07ER04", "e": "Manifestações religiosas", "h": "Exemplificar líderes religiosos que se destacaram por suas contribuições à sociedade na busca pela cultura da paz.", "o": "Lideranças religiosas •O conceito de liderança; •Formação de líderes; •Exemplos de grandes líderes e grandes líderes religiosos (Malala Yousafzai, Irmã Dorothy Stang, Moisés, papa Francisco, Chico Xavier, dentre outros); •Líderes religiosos das mais diversas religiões; •Lideranças religiosas e a busca pelo bem comum."}, {"a": "7", "t": "2", "c": "EF07ER05", "e": "Manifestações religiosas", "h": "Discutir estratégias que promovam a convivência ética e respeitosa entre as religiões.", "o": "Lideranças religiosas •O conceito de liderança; •Formação de líderes; •Exemplos de grandes líderes e grandes líderes religiosos (Malala Yousafzai, Irmã Dorothy Stang, Moisés, papa Francisco, Chico Xavier, dentre outros); •Líderes religiosos das mais diversas religiões; •Lideranças religiosas e a busca pelo bem comum."}, {"a": "7", "t": "3", "c": "EF07ER06", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar princípios éticos em diferentes tradições religiosas e filosofias de vida, discutindo como podem influenciar condutas pessoais e práticas sociais.", "o": "Princípios éticos e valores religiosos •O conceito de ética e moral; •Ética, moral, religião e valores religiosos; •Ética nas mais diversas religiões e filosofias de vida: dos povos indígenas, no Budismo, no Judaísmo, no Cristianismo, a ética do consenso e outras; •Ética global e religiões."}, {"a": "7", "t": "3", "c": "EF07ER07", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar e discutir o papel das lideranças religiosas e seculares na defesa e promoção dos direitos humanos.", "o": "Lideranças e direitos humanos •O conceito de direitos humanos e a história dos direitos humanos; •As religiões e os direitos humanos; •Direitos humanos e respeito entre as religiões; •Líderes religiosos e seculares e a defesa dos direitos humanos."}, {"a": "7", "t": "3", "c": "EF07ER08", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer o direito à liberdade de consciência, crença ou convicção, questionando concepções e práticas sociais que a violam.", "o": "Lideranças e direitos humanos •O conceito de direitos humanos e a história dos direitos humanos; •As religiões e os direitos humanos; •Direitos humanos e respeito entre as religiões; •Líderes religiosos e seculares e a defesa dos direitos humanos."}, {"a": "8", "t": "1", "c": "EF08ER01", "e": "Crenças religiosas e filosofias de vida", "h": "Discutir como as crenças e convicções podem influenciar escolhas e atitudes pessoais e coletivas.", "o": "Crenças, convicções e atitudes •Sociedade Plural; •Valores pessoais e coletivos; •Crenças religiosas e princípios éticos; •Pespectivas não-religiosas: materialismo, agnosticismo, ateísmo, ceticismo, dentre outras; •Alteridade e respeito."}, {"a": "8", "t": "1", "c": "EF08ER02", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar filosofias de vida, manifestações e tradições religiosas destacando seus princípios éticos.", "o": "Crenças, convicções e atitudes •Sociedade Plural; •Valores pessoais e coletivos; •Crenças religiosas e princípios éticos; •Pespectivas não-religiosas: materialismo, agnosticismo, ateísmo, ceticismo, dentre outras; •Alteridade e respeito."}, {"a": "8", "t": "2", "c": "EF08ER03", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar doutrinas das diferentes tradições religiosas e suas concepções de mundo, vida e morte.", "o": "Doutrinas religiosas •Diversos conceitos de pessoa nas mais diversas religiões e filosofias de vida; •Conceitos de mundo nas mais diversas religiões e filosofias de vida; •Conceitos de vida e de existência nas mais diversas religiões e filosofias de vida; •Conceitos de morte nas mais diversas religiões e filosofias de vida; •Ancestralidade e culto aos antepassados."}, {"a": "8", "t": "2", "c": "EF08ER04", "e": "Crenças religiosas e filosofias de vida", "h": "Discutir como filosofias de vida, tradições e instituições religiosas podem influenciar diferentes campos da esfera pública (política, saúde, educação, economia).", "o": "Crenças, filosofias de vida e esfera pública •Esferas Públicas e Privadas; •Sociedade Plural; •Sociedade, Estado e religião; •Estados teocráticos e Estados Laicos; •Liberdade de pensamento, consciência e religião; •Pespectivas não-religiosas: materialismo, agnosticismo, ateísmo, ceticismo, dentre outros."}, {"a": "8", "t": "2", "c": "EF08ER05", "e": "Crenças religiosas e filosofias de vida", "h": "Debater sobre as possibilidades e os limites da interferência das tradições religiosas na esfera pública, considerando que o Brasil é um país laico.", "o": "Crenças, filosofias de vida e esfera pública •Esferas Públicas e Privadas; •Sociedade Plural; •Sociedade, Estado e religião; •Estados teocráticos e Estados Laicos; •Liberdade de pensamento, consciência e religião; •Pespectivas não-religiosas: materialismo, agnosticismo, ateísmo, ceticismo, dentre outros."}, {"a": "8", "t": "3", "c": "EF08ER06", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar práticas, projetos e políticas públicas que contribuem para a promoção da liberdade de pensamento, crenças e convicções.", "o": "Crenças, filosofias de vida e esfera pública •A democracia e a diversidade de crenças, filosofias de vida e religião."}, {"a": "8", "t": "3", "c": "EF08ER07", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar as formas de uso das mídias e tecnologias pelas diferentes denominações religiosas.", "o": "Tradições religiosas, mídias e tecnologias •Comunicação e mídia; •Religião e artes; •Comunicação digital; •Ciber-religião."}, {"a": "9", "t": "1", "c": "EF09ER01", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar princípios e orientações para o cuidado da vida e nas diversas tradições religiosas, filosofias de vida e na ciência.", "o": "Imanência e transcendência. Religião e valorização da vida •Religião e ecologia; •Religião e sustentabilidade; •Respeito à vida e à dignidade humana; •Respeito à vida não-humana; •Religião e Bioética."}, {"a": "9", "t": "1", "c": "EF09ER02", "e": "Crenças religiosas e filosofias de vida", "h": "Discutir as diferentes expressões de valorização e de desrespeito à vida, por meio da análise de matérias nas diferentes mídias (problematizar assuntos contemporâneos como aborto, células tronco, eutanásia etc.).", "o": "Imanência e transcendência. Religião e valorização da vida •Religião e ecologia; •Religião e sustentabilidade; •Respeito à vida e à dignidade humana; •Respeito à vida não-humana; •Religião e Bioética."}, {"a": "9", "t": "2", "c": "EF09ER03", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar sentidos do viver e do morrer em diferentes tradições religiosas, através do estudo de mitos fundantes.", "o": "Vida e morte •Mitos de origem da vida das mais diversas religiões; •Mitos de origem da morte das mais diversas religiões; •Concepções de além-morte: Reencarnação, ressurreição, transmigração, mortalidade ou imortalidade da alma, evolução do espírito e outros conceitos; •Ritos fúnebres religiosos e seculares; •Atitudes religiosas e seculares diante da morte."}, {"a": "9", "t": "2", "c": "EF09ER04", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar concepções de vida e morte em diferentes tradições religiosas e filosofias de vida, por meio da análise de diferentes ritos fúnebres.", "o": "Vida e morte •Mitos de origem da vida das mais diversas religiões; •Mitos de origem da morte das mais diversas religiões; •Concepções de além-morte: Reencarnação, ressurreição, transmigração, mortalidade ou imortalidade da alma, evolução do espírito e outros conceitos; •Ritos fúnebres religiosos e seculares; •Atitudes religiosas e seculares diante da morte."}, {"a": "9", "t": "2", "c": "EF09ER05", "e": "Crenças religiosas e filosofias de vida", "h": "Analisar as diferentes ideias de imortalidade elaboradas pelas tradições religiosas (ancestralidade, reencarnação, transmigração e ressurreição).", "o": "Vida e morte •Mitos de origem da vida das mais diversas religiões; •Mitos de origem da morte das mais diversas religiões; •Concepções de além-morte: Reencarnação, ressurreição, transmigração, mortalidade ou imortalidade da alma, evolução do espírito e outros conceitos; •Ritos fúnebres religiosos e seculares; •Atitudes religiosas e seculares diante da morte."}, {"a": "9", "t": "3", "c": "EF09ER06", "e": "Crenças religiosas e filosofias de vida", "h": "Reconhecer a coexistência como uma atitude ética de respeito à vida e à dignidade humana.", "o": "Princípios e valores éticos •Valores éticos e sociedade; •Religião e convivência; •Respeitar é preciso; •Projetos sociais laicos e de iniciativa religiosa."}, {"a": "9", "t": "3", "c": "EF09ER07", "e": "Crenças religiosas e filosofias de vida", "h": "Identificar princípios éticos (familiares, religiosos e culturais) que possam alicerçar a construção de projetos de vida e a influência da religião na constituição dos valores sociais.", "o": "Princípios e valores éticos •Valores éticos e sociedade; •Religião e convivência; •Respeitar é preciso; •Projetos sociais laicos e de iniciativa religiosa."}, {"a": "9", "t": "3", "c": "EF09ER08", "e": "Crenças religiosas e filosofias de vida", "h": "Construir projetos de vida assentados em princípios e valores éticos.", "o": "Princípios e valores éticos •Valores éticos e sociedade; •Religião e convivência; •Respeitar é preciso; •Projetos sociais laicos e de iniciativa religiosa."}], "Geografia": [{"a": "6", "t": "1", "c": "EF06GE01/ES", "e": "O sujeito e seu lugar no mundo", "h": "Comparar modificações das paisagens nos lugares de vivência (bairro, cidade, estado) e os usos desses lugares em diferentes tempos, aprofundando os conceitos de paisagem e lugar, problematizando a produção e considerando os aspectos econômico, social, cultural e natural. Destacando suas singularidades e o que o diferencia e aproxima de outros lugares.", "o": "Identidade Sociocultural. Espaço e Tempo: espaço geográfico, lugar e paisagem."}, {"a": "6", "t": "1", "c": "EF06GE02/ES", "e": "O sujeito e seu lugar no mundo", "h": "Analisar modificações de paisagens por diferentes tipos de sociedade, com destaque para os povos originários, apresentando situações geográficas que caracterizam as diferenças produzidas e percebidas pelo homem em diferentes lugares: cidades, zona rural, lavouras, áreas de natureza intocada, lugares turísticos, reservas indígenas, bacias hidrográficas e outros.", "o": "Identidade Sociocultural. Espaço e Tempo: espaço geográfico, lugar e paisagem."}, {"a": "6", "t": "1", "c": "EF06GE03/ES", "e": "Conexões e escalas", "h": "Descrever os movimentos do planeta e sua relação com a circulação geral da atmosfera, o tempo atmosférico e os padrões climáticos especificando e caracterizando cada um dos movimentos e destacando as consequências de cada um deles para: as estações do ano, formação dos dias e noites, regulamentação dos diferentes fusos horários, distribuição energética no planeta, diferenciação entre tempo e clima, considerando a escala local para global.", "o": "Relações entre os componentes físico-naturais. O movimento de rotação. Fuso Horário. O movimento de translação. A atmosfera e suas camadas. Circulação geral da atmosfera. Tempo e clima."}, {"a": "6", "t": "1", "c": "EF06GE04/ES", "e": "Conexões e escalas", "h": "Descrever o ciclo da água, comparando o escoamento superficial no ambiente urbano e rural, reconhecendo os principais componentes da morfologia das bacias e das redes hidrográficas e a sua localização no modelado da superfície terrestre e da cobertura vegetal, destacando a distribuição das águas no território brasileiro e espírito-santense, a localização das águas superficiais e subterrâneas, a influência da energia solar no ciclo hidrológico, os diferentes caminhos da água precipitada e a importância da água para a economia.", "o": "Relações entre os componentes físico-naturais. Tempo e clima. O ciclo da água. Hidrografia. Relevo. Solo. Vegetação."}, {"a": "6", "t": "1", "c": "EF06GE05/ES", "e": "Conexões e escalas", "h": "Relacionar padrões climáticos, tipos de solo, relevo e formações vegetais, considerando a influência da latitude aos diversos padrões climáticos brasileiros e espírito-santenses.", "o": "Relações entre os componentes físico-naturais. Tempo e clima. O ciclo da água. Hidrografia. Relevo. Solo. Vegetação."}, {"a": "6", "t": "2", "c": "EF06GE06/ES", "e": "Mundo do Trabalho", "h": "Identificar as características das paisagens transformadas pelo trabalho humano a partir do desenvolvimento da agropecuária e do processo de industrialização, relacionando trabalho humano à dinamização do processo de exploração dos recursos naturais nos contextos das revoluções industriais (surgimento de novas máquinas e equipamentos agrícolas, exploração da matéria-prima da natureza e o aumento do consumo).", "o": "Transformação das paisagens naturais e antrópicas. Transformações sociais e impactos ambientais causados pelas revoluções industriais e pela expansão agrícola. A sociedade de consumo e o desperdício. A mudança no papel das cidades."}, {"a": "6", "t": "2", "c": "EF06GE07/ES", "e": "Mundo do Trabalho", "h": "Explicar as mudanças na interação humana com a natureza a partir do surgimento das cidades, avaliando como elas eram na antiguidade, quais foram as primeiras cidades, quando surgiram as primeiras civilizações e como se organizaram, bem como seu quantitativo populacional.", "o": "Transformação das paisagens naturais e antrópicas. Transformações sociais e impactos ambientais causados pelas revoluções industriais e pela expansão agrícola. A sociedade de consumo e o desperdício. A mudança no papel das cidades."}, {"a": "6", "t": "2", "c": "EF06GE08A/ES", "e": "Formas de Representação e Pensamento Espacial", "h": "Reconhecer a importância da orientação e localização para desenvolver o pensamento geográfico.", "o": "Fenômenos naturais e sociais representados de diferentes maneiras. Orientação. Coordenadas geográficas."}, {"a": "6", "t": "2", "c": "EF06GE08B/ES", "e": "Formas de Representação e Pensamento Espacial", "h": "Medir distâncias na superfície pelas escalas gráficas e numéricas dos mapas, identificando as possibilidades de representação dos diversos temas em mapas de diferentes tamanhos, em escala local para a global, considerando o grau de detalhamento que se deseja da informação representada.", "o": "Fenômenos naturais e sociais representados de diferentes maneiras. Representação do espaço por meio de mapas. A linguagem cartográfica."}, {"a": "6", "t": "2", "c": "EF06GE09/ES", "e": "Formas de Representação e Pensamento Espacial", "h": "Elaborar modelos tridimensionais, blocos-diagramas e perfis topográficos e de vegetação, visando à representação de elementos e estruturas da superfície terrestre, considerando a escala local para a global e os aspectos físicos e geológicos do estado do Espírito Santo e do Brasil.", "o": "Fenômenos naturais e sociais representados de diferentes maneiras. A linguagem cartográfica."}, {"a": "6", "t": "3", "c": "EF06GE10/ES", "e": "Natureza, ambientes e qualidade de vida", "h": "Explicar as diferentes formas de uso do solo (rotação de terras, terraceamento, aterros etc.) e de apropriação dos recursos hídricos (sistema de irrigação, tratamento e redes de distribuição), bem como suas vantagens e desvantagens em diferentes épocas e lugares, analisando essas características.", "o": "Biodiversidade e ciclo hidrológico Solo: noções básicas, formação, perfil, classificação e formas de uso. Sistemas de plantios. Impactos ambientais causados pelo uso inadequado do solo. Biomas: impactos ambientais. Água: impacto ambiental. Uso e ocupação do solo do Espírito Santo."}, {"a": "6", "t": "3", "c": "EF06GE11/ES", "e": "Natureza, ambientes e qualidade de vida", "h": "Analisar distintas interações das sociedades com a natureza, com base na distribuição dos componentes físico-naturais, incluindo as transformações da biodiversidade local e do mundo, fazendo uma reflexão sobre como a sociedade se apropriou da natureza na ocupação das áreas, considerando a escala local para a global.", "o": "Biodiversidade e ciclo hidrológico. Biomas: impactos ambientais."}, {"a": "6", "t": "3", "c": "EF06GE12/ES", "e": "Natureza, ambientes e qualidade de vida", "h": "Localizar as principais bacias hidrográficas do Brasil e Identificar o consumo dos recursos hídricos e o uso das principais bacias hidrográficas no Brasil e no mundo, enfatizando as transformações nos ambientes urbanos.", "o": "Biodiversidade e ciclo hidrológico. Hidrografia do Brasil. Água: impacto ambiental."}, {"a": "6", "t": "3", "c": "EF06GE13/ES", "e": "Natureza, ambientes e qualidade de vida", "h": "Analisar consequências, vantagens e desvantagens das práticas humanas na dinâmica climática (ilha de calor etc.).", "o": "Atividades humanas e dinâmicas climáticas"}, {"a": "7", "t": "1", "c": "EF07GE01/ES", "e": "O sujeito e seu lugar no mundo", "h": "Avaliar, por meio de exemplos extraídos dos meios de comunicação, ideias e estereótipos acerca das paisagens e da formação territorial do Brasil, dando destaque para as questões histórico-geográficas.", "o": "Ideias e concepções sobre a formação territorial do Brasil. Expansão territorial no Brasil Colônia: Tratado de Tordesilhas e Tratado de Madri. Expansão das fronteiras no Império e na república. A atual configuração do território brasileiro. Posição geográfica e localização do Brasil. As fronteiras do território brasileiro. Os nativos. Os europeus. Os africanos."}, {"a": "7", "t": "1", "c": "EF07GE02/ES", "e": "Conexões e escala", "h": "Analisar a influência dos fluxos econômicos e populacionais na formação socioeconômica e territorial do Brasil, compreendendo os conflitos e as tensões históricas e contemporâneas.", "o": "Formação territorial do Brasil: Conceitos: povo, nação, estado, país, território, sociedade e cidadania. A Importância dos ciclos econômicos na expansão territorial. Os movimentos migratórios e suas motivações."}, {"a": "7", "t": "1", "c": "EF07GE03/ES", "e": "Conexões e escala", "h": "Selecionar argumentos que reconheçam as territorialidades dos povos indígenas originários, das comunidades remanescentes de quilombos, de povos das florestas e do cerrado, de ribeirinhos e caiçaras, entre outros grupos sociais do campo e da cidade, como direitos legais dessas comunidades, compreendendo as características sócio espaciais e identitárias desses povos e demais grupos sociais do campo e da cidade que possuem territorialidades distintas.", "o": "Formação territorial do Brasil. A situação e os espaços indígenas e quilombolas no século XX e início do século XXI."}, {"a": "7", "t": "1", "c": "EF07GE03A/ES", "e": "Conexões e escala", "h": "Conceituar região e seu uso no controle territorial.", "o": "Processo brasileiro de regionalização. Região e sua territorialidade administrativa. As regiões brasileiras e suas características socioespaciais."}, {"a": "7", "t": "1", "c": "EF07GE03B/ES", "e": "Conexões e escala", "h": "Compreender os diferentes processos de regionalização do território brasileiro, considerando os critérios de delimitação das regiões.", "o": "Processo brasileiro de regionalização. Distintas regionalizações do Brasil. Regiões do Espírito Santo."}, {"a": "7", "t": "2", "c": "EF07GE04/ES", "e": "Conexões e escala", "h": "Analisar a distribuição territorial da população brasileira, considerando a diversidade étnico-cultural (indígena, africana, europeia e asiática), assim como aspectos de renda, sexo, idade e processo de ocupação territorial, nas regiões brasileiras e dentro do Espírito Santo.", "o": "Características da população brasileira: Os habitantes das terras que viria ser o Brasil. Os espaços dos indígenas. O contato entre europeus e indígenas. Os povos africanos escravizados. A transformação demográfica, a distribuição espacial e os indicadores estatísticos da população."}, {"a": "7", "t": "2", "c": "EF07GE05/ES", "e": "Mundo do trabalho", "h": "Analisar fatos e situações representativas das alterações ocorridas entre o período mercantilista e o advento do capitalismo, identificando o funcionamento do capitalismo e considerando as especificidades que marcam cada uma das fases: comercial, industrial, financeiro ou monopolista.", "o": "Produção, circulação e consumo de mercadorias: As fases do capitalismo."}, {"a": "7", "t": "2", "c": "EF07GE06/ES", "e": "Mundo do trabalho", "h": "Discutir em que medida a produção, a circulação e o consumo de mercadorias provocam impactos ambientais, assim como influem na distribuição de riquezas e construção do espaço geográfico em diferentes lugares.", "o": "Produção, circulação e consumo de mercadorias: A influência do capitalismo na construção do espaço geográfico."}, {"a": "7", "t": "2", "c": "EF07GE07/ES", "e": "Mundo do trabalho", "h": "Analisar a influência e o papel das redes de transporte e comunicação na configuração do território brasileiro, considerando que os meios de transporte e comunicação no Brasil são um dos principais elementos para garantir a infraestrutura, ou seja, o suporte material para o crescimento e expansão das redes. Analisar, também, as especificidades relativas à configuração do espaço geográfico do Espírito Santo.", "o": "Desigualdade social e o trabalho: Os transportes e as telecomunicações no Brasil."}, {"a": "7", "t": "2", "c": "EF07GE08/ES", "e": "Mundo do trabalho", "h": "Estabelecer relações entre os processos de industrialização e inovação tecnológica com as transformações socioeconômicas do território brasileiro e do Espírito Santo, identificando e problematizando as mudanças socioeconômicas ocorridas após o advento da industrialização e o do desenvolvimento tecnológico.", "o": "Desigualdade social e o trabalho: Brasil: país de industrialização tardia ou retardatária. Distribuição espacial da indústria no Brasil. Espírito Santo: aspectos econômicos. A concentração e desconcentração industrial."}, {"a": "7", "t": "3", "c": "EF07GE09", "e": "Formas de representação e pensamento espacial", "h": "Interpretar e elaborar mapas temáticos e históricos, inclusive utilizando tecnologias digitais, com informações demográficas e econômicas do Brasil e do Estado do Espírito Santo (cartogramas), identificando padrões espaciais, regionalizações e analogias espaciais.", "o": "Mapas temáticos do Brasil. Linguagem Cartográfica."}, {"a": "7", "t": "3", "c": "EF07GE10", "e": "Formas de representação e pensamento espacial", "h": "Elaborar e interpretar gráficos de barras, gráficos de setores e histogramas, com base em dados socioeconômicos das regiões brasileiras.", "o": "Mapas temáticos do Brasil. Linguagem Cartográfica."}, {"a": "7", "t": "3", "c": "EF07GE11/ES", "e": "Natureza, ambiente e qualidade de vida", "h": "Caracterizar dinâmicas dos componentes físico-naturais no território nacional, bem como sua distribuição e biodiversidade (florestas tropicais, cerrados, caatingas, campos sulinos e matas de araucária). Destacando as características físico-naturais do estado do Espírito Santo.", "o": "Biodiversidade brasileira: domínios morfoclimáticos."}, {"a": "7", "t": "3", "c": "EF07GE12/ES", "e": "Natureza, ambiente e qualidade de vida", "h": "Comparar unidades de conservação existentes no Município de residência e em outras localidades brasileiras, com base na organização do Sistema Nacional de Unidades de Conservação (SNUC).", "o": "Biodiversidade brasileira: domínios morfoclimáticos."}, {"a": "8", "t": "1", "c": "EF08GE01", "e": "O sujeito e seu lugar no mundo", "h": "Descrever as rotas de dispersão da população humana pelo planeta e os principais fluxos migratórios em diferentes períodos da história, discutindo os fatores históricos e condicionantes físico-naturais associados à distribuição da população humana pelos continentes.", "o": "Distribuição da população mundial e deslocamentos populacionais."}, {"a": "8", "t": "1", "c": "EF08GE02", "e": "O sujeito e seu lugar no mundo", "h": "Relacionar fatos e situações representativas da história das famílias do Município em que se localiza a escola, considerando a diversidade e os fluxos migratórios da população mundial.", "o": "Diversidade e dinâmica da população mundial e local (Espírito Santo)."}, {"a": "8", "t": "1", "c": "EF08GE03/ES", "e": "O sujeito e seu lugar no mundo", "h": "Analisar aspectos representativos da dinâmica demográfica, considerando características da população (perfil etário, crescimento vegetativo e mobilidade espacial) e, posteriormente, comparar os dados de um lugar com outro para conhecer o comportamento populacional do estado, região ou país.", "o": "Diversidade e dinâmica da população mundial e local (Espírito Santo)."}, {"a": "8", "t": "1", "c": "EF08GE04/ES", "e": "O sujeito e seu lugar no mundo", "h": "Compreender os fluxos de migração na América Latina (movimentos voluntários e forçados, assim como fatores e áreas de expulsão e atração) e as principais políticas migratórias da região, compreendendo e utilizando os conceitos de estado, nação, território, governo, e país na compreensão de conflitos contemporâneos.", "o": "Diversidade e dinâmica da população mundial e local (Espírito Santo)."}, {"a": "8", "t": "1", "c": "EF08GE05", "e": "Conexões e escala", "h": "Aplicar os conceitos de Estado, nação, território, governo e país para o entendimento de conflitos e tensões na contemporaneidade, com destaque para as situações geopolíticas na América e na África e suas múltiplas regionalizações a partir do pós-guerra.", "o": "Corporações e organismos internacionais e do Brasil na ordem econômica e mundial: ONU, OMC, OTAN, FMI, OIT, OCDE, OEA, BANCO MUNDIAL, OEI, Comunidade Andina, Nafta, Unasul, Alba, Aladi dentre outros. O continente americano. O continente africano."}, {"a": "8", "t": "1", "c": "EF08GE06/ES", "e": "Conexões e escala", "h": "Analisar a atuação das organizações mundiais nos processos de integração cultural e econômica nos contextos americano e africano, reconhecendo, em seus lugares de vivência, marcas desses processos, identificando e avaliando criticamente o papel das organizações internacionais em relação às realidades da América e da África.", "o": "Corporações e organismos internacionais e do Brasil na ordem econômica e mundial: ONU, OMC, OTAN, FMI, OIT, OCDE, OEA, BANCO MUNDIAL, OEI, Comunidade Andina, Nafta, Unasul, Alba, Aladi dentre outros. O continente americano. O continente africano."}, {"a": "8", "t": "1", "c": "EF08GE07", "e": "Conexões e escala", "h": "Analisar os impactos geoeconômicos, geoestratégicos e geopolíticos da ascensão dos Estados Unidos da América no cenário internacional em sua posição de liderança global e na relação com a China e o Brasil.", "o": "Corporações e organismos internacionais e do Brasil na ordem econômica e mundial. A Economia estadunidense e sua influência planetária. As potencialidades e as vulnerabilidades dos Estados Unidos."}, {"a": "8", "t": "1", "c": "EF08GE08/ES", "e": "Conexões e escala", "h": "Analisar a situação do Brasil e de outros países da América Latina e da África, assim como da potência estadunidense na ordem mundial do pós-guerra, avaliando criticamente os países da América Latina e África frente à nova ordem mundial (Globalização).", "o": "Corporações e organismos internacionais e do Brasil na ordem econômica e mundial. O continente americano. O continente africano."}, {"a": "8", "t": "2", "c": "EF08GE09", "e": "Conexões e escala", "h": "Analisar os padrões econômicos mundiais de produção, distribuição e intercâmbio dos produtos agrícolas e industrializados, tendo como referência os Estados Unidos da América e os países denominados de Brics (Brasil, Rússia, Índia, China e África do Sul).", "o": "Corporações e organismos internacionais e do Brasil na ordem econômica e mundial. Brics. Blocos econômicos."}, {"a": "8", "t": "2", "c": "EF08GE10/ES", "e": "Conexões e escala", "h": "Distinguir e analisar conflitos e ações dos movimentos sociais brasileiros, no campo e na cidade, comparando com outros movimentos sociais existentes nos países latino-americanos, conhecendo as ações dos movimentos sociais no Brasil e na América Latina e analisando as pautas das reinvindicações por melhores condições de moradia e de trabalho no campo e na cidade.", "o": "Corporações e organismos internacionais e do Brasil na ordem econômica e mundial. Brics. Blocos econômicos."}, {"a": "8", "t": "2", "c": "EF08GE11/ES", "e": "Conexões e escala", "h": "Analisar áreas de conflito e tensões nas regiões de fronteira do continente latino-americano e o papel de organismos internacionais e regionais de cooperação nesses cenários, considerando as migrações latino-americanas, os refugiados de países em conflitos ou problemas decorrentes da falta de emprego, oportunidades de vida com dignidade e a assistência das organizações internacionais nessas regiões.", "o": "Corporações e organismos internacionais e do Brasil na ordem econômica e mundial. Brics. Blocos econômicos."}, {"a": "8", "t": "2", "c": "EF08GE12", "e": "Conexões e escala", "h": "Compreender os objetivos e analisar a importância dos organismos de integração do território americano (Mercosul, OEA, OEI, Nafta, Unasul, Alba, Comunidade Andina, Aladi, entre outros).", "o": "Corporações e organismos internacionais e do Brasil na ordem econômica e mundial. Brics. Blocos econômicos."}, {"a": "8", "t": "2", "c": "EF08GE13/ES", "e": "Mundo do trabalho", "h": "Analisar a influência do desenvolvimento científico e tecnológico na caracterização dos tipos de trabalho e na economia dos espaços urbanos e rurais da América e da África, reconhecendo as mudanças ocorridas no mundo do trabalho, no campo e na cidade a partir do desenvolvimento científico e tecnológico.", "o": "Os diferentes contextos e os meios técnicos e tecnológicos na produção."}, {"a": "8", "t": "2", "c": "EF08GE14/ES", "e": "Mundo do trabalho", "h": "Analisar os processos de desconcentração, descentralização e recentralização das atividades econômicas a partir do capital estadunidense e chinês em diferentes regiões no mundo, com destaque para o Brasil, considerando que a desconcentração industrial atual é resultante da industrialização de vastas regiões do mundo, como o Sudeste Asiático e América Latina.", "o": "Os diferentes contextos e os meios técnicos e tecnológicos na produção."}, {"a": "8", "t": "2", "c": "EF08GE15/ES", "e": "Mundo do trabalho", "h": "Analisar a importância dos principais recursos hídricos da América Latina (Aquífero Guarani, Bacias do rio da Prata, do Amazonas e do Orinoco, sistemas de nuvens na Amazônia e nos Andes, entre outros) e discutir os desafios relacionados à gestão e comercialização da água, identificando os principais usuários da água na região, como indústrias, residências, atividades agrícolas e os principais problemas relativos ao abastecimento da água.", "o": "Transformações do espaço na sociedade urbano-industrial na América Latina."}, {"a": "8", "t": "2", "c": "EF08GE16", "e": "Mundo do trabalho", "h": "Analisar as principais problemáticas comuns às grandes cidades latino-americanas, particularmente aquelas relacionadas à distribuição, estrutura e dinâmica da população e às condições de vida e trabalho.", "o": "Transformações do espaço na sociedade urbano-industrial na América Latina."}, {"a": "8", "t": "2", "c": "EF08GE17/ES", "e": "Mundo do trabalho", "h": "Analisar a segregação socioespacial em ambientes urbanos da América Latina, com atenção especial ao estudo de favelas, alagados e zona de riscos compreendendo os motivos que levam a esse tipo de segregação que resulta na configuração dos diferentes tipos de espaços de moradias.", "o": "Transformações do espaço na sociedade urbano-industrial na América Latina."}, {"a": "8", "t": "3", "c": "EF08GE18/ES", "e": "Formas de representação e pensamento espacial", "h": "Elaborar mapas ou outras formas de representação cartográfica para analisar as redes e as dinâmicas urbanas e rurais, ordenamento territorial, contextos culturais, modo de vida e usos e ocupação de solos da África e América, por meio da linguagem cartográfica como base para obtenção de informações e, ainda, como meio de expressão das investigações sobre os temas propostos de ordenamento territorial.", "o": "Cartografia: anamorfose, croquis e mapas temáticos da América e da África."}, {"a": "8", "t": "3", "c": "EF08GE19", "e": "Formas de representação e pensamento espacial", "h": "Interpretar cartogramas, mapas esquemáticos (croquis) e anamorfoses geográficas com informações geográficas acerca da África e da América.", "o": "Cartografia: anamorfose, croquis e mapas temáticos da América e da África."}, {"a": "8", "t": "3", "c": "EF08GE20", "e": "Natureza, ambiente e qualidade de vida", "h": "Analisar características de países e grupos de países da América e da África no que se refere aos aspectos populacionais, urbanos, políticos e econômicos, e discutir as desigualdades sociais e econômicas e as pressões sobre a natureza e suas riquezas (sua apropriação e valoração na produção e circulação), o que resulta na espoliação desses povos.", "o": "Identidades e interculturalidades regionais: Estados Unidos da América, América espanhola, América Portuguesa e Continente Africano."}, {"a": "8", "t": "3", "c": "EF08GE21/ES", "e": "Natureza, ambiente e qualidade de vida", "h": "Analisar o papel ambiental e territorial da Antártica no contexto geopolítico, sua relevância para os países da América do Sul e seu valor como área destinada à pesquisa, compreensão do ambiente global e como uma grande reserva de água doce, além de fundamental para a vida de espécies que habitam os oceanos.", "o": "Identidades e interculturalidades regionais: Estados Unidos da América, América espanhola, América Portuguesa e Continente Africano."}, {"a": "8", "t": "3", "c": "EF08GE22", "e": "Natureza, ambiente e qualidade de vida", "h": "Identificar os principais recursos naturais dos países da América Latina, analisando o seu uso para a produção de matéria-prima e energia e sua relevância para a cooperação entre os países do Mercosul.", "o": "Diversidade ambiental e as transformações nas paisagens na América."}, {"a": "8", "t": "3", "c": "EF08GE23", "e": "Natureza, ambiente e qualidade de vida", "h": "Identificar paisagens da América Latina e associá-las, por meio da cartografia, aos diferentes povos da região, com base em aspectos da geomorfologia, da biogeografia e da climatologia.", "o": "Diversidade ambiental e as transformações nas paisagens na América."}, {"a": "8", "t": "3", "c": "EF08GE24", "e": "Natureza, ambiente e qualidade de vida", "h": "Analisar as principais características produtivas dos países latino-americanos (como exploração mineral na Venezuela; agricultura de alta especialização e exploração mineira no Chile; circuito da carne nos pampas argentinos e no Brasil; circuito da cana-de-açúcar em Cuba; polígono industrial do sudeste brasileiro e plantações de soja no centro-oeste; maquiladoras mexicanas, entre outros).", "o": "Diversidade ambiental e as transformações nas paisagens na América."}, {"a": "9", "t": "1", "c": "EF09GE01/ES", "e": "O sujeito e seu lugar no mundo", "h": "Analisar criticamente de que forma a hegemonia europeia foi exercida em várias regiões do planeta, notadamente em situações de conflito, intervenções militares e/ou influência cultural em diferentes tempos e lugares reconhecendo o percurso do continente europeu diante de conflitos, guerras e disputas e a sua influência cultural, assim como o seu papel preponderante no mundo contemporâneo.", "o": "A hegemonia europeia na economia, na política e na cultura."}, {"a": "9", "t": "1", "c": "EF09GE02/ES", "e": "O sujeito e seu lugar no mundo", "h": "Analisar a atuação das corporações internacionais e das organizações econômicas mundiais na vida da população em relação ao consumo, à cultura e à mobilidade compreendendo que as organizações internacionais surgiram, em sua maioria, na segunda metade do século XX, e se consolidaram como importantes atores no cenário internacional de integração geoeconômica global com a missão de estabelecer um ordenamento das relações intranacionais de poder e influência política.", "o": "Corporações e organismos internacionais."}, {"a": "9", "t": "1", "c": "EF09GE03", "e": "O sujeito e seu lugar no mundo", "h": "Identificar diferentes manifestações culturais de minorias étnicas como forma de compreender a multiplicidade cultural na escala mundial, defendendo o princípio do respeito às diferenças.", "o": "As manifestações culturais na formação populacional."}, {"a": "9", "t": "1", "c": "EF09GE04", "e": "O sujeito e seu lugar no mundo", "h": "Relacionar diferenças de paisagens aos modos de viver de diferentes povos na Europa, Ásia e Oceania, valorizando identidades e interculturalidades regionais.", "o": "As manifestações culturais na formação populacional."}, {"a": "9", "t": "1", "c": "EF09GE05/ES", "e": "Conexões e escalas", "h": "Analisar fatos e situações para compreender a integração mundial (econômica, política e cultural), comparando as diferentes interpretações: globalização e mundialização avaliando os aspectos da Nova Ordem Mundial e suas consequências no mundo.", "o": "Integração mundial e suas interpretações: globalização e mundialização."}, {"a": "9", "t": "2", "c": "EF09GE06", "e": "Conexões e escalas", "h": "Associar o critério de divisão do mundo em Ocidente e Oriente com o sistema colonial implantado pelas potências europeias.", "o": "A divisão do mundo em Ocidente e Oriente."}, {"a": "9", "t": "2", "c": "EF09GE07", "e": "Conexões e escalas", "h": "Analisar os componentes físico-naturais da Eurásia e os determinantes histórico-geográficos de sua divisão em Europa e Ásia.", "o": "Intercâmbios históricos e culturais entre Europa, Ásia e Oceania."}, {"a": "9", "t": "2", "c": "EF09GE08", "e": "Conexões e escalas", "h": "Analisar transformações territoriais, considerando o movimento de fronteiras, tensões, conflitos e múltiplas regionalidades na Europa, na Ásia e na Oceania.", "o": "Intercâmbios históricos e culturais entre Europa, Ásia e Oceania."}, {"a": "9", "t": "2", "c": "EF09GE09", "e": "Conexões e escalas", "h": "Analisar características de países e grupos de países europeus, asiáticos e da Oceania em seus aspectos populacionais, urbanos, políticos e econômicos, e discutir as suas desigualdades sociais e econômicas e pressões sobre os seus ambientes físico-naturais.", "o": "Intercâmbios históricos e culturais entre Europa, Ásia e Oceania."}, {"a": "9", "t": "2", "c": "EF09GE10/ES", "e": "Mundo do trabalho", "h": "Analisar os impactos do processo de industrialização na produção e circulação de produtos e culturas na Europa, na Ásia e na Oceania compreendendo que as transformações ocorridas com o advento da indústria em um primeiro momento na Europa e depois nos demais continentes, gerou o aumento da exploração de recursos naturais, com o aumento cada vez maior das tecnologias.", "o": "Transformações do espaço na sociedade urbano-industrial."}, {"a": "9", "t": "2", "c": "EF09GE11/ES", "e": "Mundo do trabalho", "h": "Relacionar as mudanças técnicas e científicas decorrentes do processo de industrialização com as transformações no trabalho em diferentes regiões do mundo e suas consequências no Brasil, fazendo uma reflexão sobre as relações de trabalho na sociedade capitalista.", "o": "Transformações do espaço na sociedade urbano-industrial."}, {"a": "9", "t": "3", "c": "EF09GE12", "e": "Mundo do trabalho", "h": "Relacionar o processo de urbanização às transformações da produção agropecuária, à expansão do desemprego estrutural e ao papel crescente do capital financeiro em diferentes países, com destaque para o Brasil.", "o": "Cadeias industriais e inovação no uso dos recursos naturais e matérias-primas."}, {"a": "9", "t": "3", "c": "EF09GE13/ES", "e": "Mundo do trabalho", "h": "Analisar a importância da produção agropecuária na sociedade urbano-industrial ante o problema da desigualdade mundial de acesso aos recursos alimentares e à matéria-prima, destacando a concentração de renda como uma das causas do aumento da pobreza estrutural e da falta de condições dignas de vida e de moradia para a população em geral.", "o": "Cadeias industriais e inovação no uso dos recursos naturais e matérias-primas."}, {"a": "9", "t": "3", "c": "EF09GE14", "e": "Formas de representação e pensamento espacial", "h": "Elaborar e interpretar gráficos de barras e de setores, mapas temáticos e esquemáticos (croquis) e anamorfoses geográficas para analisar, sintetizar e apresentar dados e informações sobre diversidade, diferenças e desigualdades sociopolíticas e geopolíticas mundiais.", "o": "Leitura e elaboração de mapas temáticos, croquis e outras formas de representação para analisar informações geográficas."}, {"a": "9", "t": "3", "c": "EF09GE15", "e": "Formas de representação e pensamento espacial", "h": "Comparar e classificar diferentes regiões do mundo com base em informações populacionais, econômicas e socioambientais representadas em mapas temáticos e com diferentes projeções cartográficas.", "o": "Leitura e elaboração de mapas temáticos, croquis e outras formas de representação para analisar informações geográficas."}, {"a": "9", "t": "3", "c": "EF09GE16/ES", "e": "Natureza, ambiente e qualidade de vida", "h": "Identificar e comparar diferentes domínios morfoclimáticos da Europa, da Ásia e da Oceania, reconhecendo e listando as diferenças e semelhanças entre os biomas dos três continentes, considerando o uso de mapas físicos para espacialização das áreas de ocorrência desses domínios.", "o": "Diversidade ambiental e as transformações nas paisagens na Europa, na Ásia e na Oceania."}, {"a": "9", "t": "3", "c": "EF09GE17", "e": "Natureza, ambiente e qualidade de vida", "h": "Explicar as características físico-naturais e a forma de ocupação e usos da terra em diferentes regiões da Europa, da Ásia e da Oceania.", "o": "Diversidade ambiental e as transformações nas paisagens na Europa, na Ásia e na Oceania."}, {"a": "9", "t": "3", "c": "EF09GE18", "e": "Natureza, ambiente e qualidade de vida", "h": "Identificar e analisar as cadeias industriais e de inovação e as consequências dos usos de recursos naturais e das diferentes fontes de energia (tais como termoelétrica, hidrelétrica, eólica e nuclear) em diferentes países.", "o": "Diversidade ambiental e as transformações nas paisagens na Europa, na Ásia e na Oceania."}], "História": [{"a": "6", "t": "1", "c": "EF06HI01/ES", "e": "História: tempo, espaço e formas e registros", "h": "Identificar diferentes formas de compreensão da noção de tempo e de periodização dos processos históricos (continuidades e rupturas), pensando o papel do historiador e refletindo sobre o papel da história enquanto ciência que estuda a trajetória humana ao longo do tempo, construindo Linhas do tempo individuais e coletivas para tornar material o entendimento dessas mudanças e permanências, relacionando-as a um espaço e tempo específico.", "o": "A questão do tempo, sincronias e diacronias: reflexões sobre o sentido das cronologias."}, {"a": "6", "t": "1", "c": "EF06HI02/ES", "e": "História: tempo, espaço e formas e registros.", "h": "Identificar a gênese da produção do saber histórico e analisar o significado das fontes que originaram determinadas formas de registros em sociedades e épocas distintas. Compreendendo que as variadas fontes históricas assumem um papel fundamental para análises de comportamento e organização social em distintas temporalidades.", "o": "Formas de registro da história e da produção do conhecimento histórico."}, {"a": "6", "t": "1", "c": "EF06HI03/ES", "e": "História: tempo, espaço e formas e registros.", "h": "Identificar as hipóteses científicas sobre o surgimento da espécie humana e sua historicidade e analisar os significados dos mitos de fundação, lendas e celebrações de matrizes africanas e indígenas.", "o": "As origens da humanidade, seus deslocamentos e os processos de sedentarização."}, {"a": "6", "t": "1", "c": "EF06HI04/ES", "e": "Mundo pessoal: meu lugar no mundo", "h": "Conhecer as teorias sobre a origem do homem americano, percebendo que uma hipótese não anula as outras.", "o": "As origens da humanidade, seus deslocamentos e os processos de sedentarização."}, {"a": "6", "t": "1", "c": "EF06HI05/ES", "e": "Mundo pessoal: meu lugar no mundo", "h": "Descrever modificações da natureza e da paisagem realizadas por diferentes tipos de sociedade, com destaque para os povos indígenas originários e povos africanos, e discutir a natureza e a lógica das transformações ocorridas no Espírito Santo e na sua comunidade.", "o": "As origens da humanidade, seus deslocamentos e os processos de sedentarização."}, {"a": "6", "t": "1", "c": "EF06HI06/ES", "e": "Mundo pessoal: meu lugar no mundo", "h": "Identificar as rotas de povoamento no território americano, interpretando mapas e cartas náuticas que exemplificariam as diferentes versões da ocupação do território americano. Reconhecendo os interesses existentes na defesa de algumas destas versões e compreendendo algumas definições teóricas fundamentais: arqueologia, sítio arqueológico, fontes materiais e imateriais, fontes primárias e secundárias.", "o": "As origens da humanidade, seus deslocamentos e os processos de sedentarização."}, {"a": "6", "t": "2", "c": "EF06HI07/ES", "e": "A invenção do mundo clássico e o contraponto com outras sociedades", "h": "Identificar aspectos e formas de registro das sociedades antigas na África, no Oriente Médio e nas Américas, distinguindo alguns significados presentes na cultura material e na tradição oral dessas sociedades, conhecendo sítios arqueológicos no Espírito Santo e ressaltando a importância do estudo dos sambaquis e demais registros das sociedades e povos pré- colombianos.", "o": "A invenção do mundo clássico e o contraponto com outras sociedades."}, {"a": "6", "t": "2", "c": "EF06HI08/ES", "e": "A invenção do mundo clássico e o contraponto com outras sociedades", "h": "Identificar os espaços territoriais ocupados e os aportes culturais, científicos, sociais e econômicos dos astecas, maias e incas e dos povos indígenas de diversas regiões brasileiras e do Espírito Santo.", "o": "A invenção do mundo clássico e o contraponto com outras sociedades."}, {"a": "6", "t": "2", "c": "EF06HI09/ES", "e": "Lógicas de organização política", "h": "Discutir o conceito de Antiguidade Clássica, seu alcance e limite na tradição ocidental, assim como os impactos sobre outras sociedades e culturas.", "o": "O Ocidente Clássico: aspectos da cultura na Grécia e em Roma."}, {"a": "6", "t": "2", "c": "EF06HI10/ES", "e": "Lógicas de organização política", "h": "Explicar a formação da Grécia Antiga, com ênfase na formação da pólis e nas transformações políticas, sociais e culturais. Evidenciando as diversas formas de organização política criada e sistematizada nas diferentes cidades-estados, as semelhanças existentes entre os maias, civilização ameríndia, e os helenos, no que concerne a ideia de autonomia e independência política entre as cidades-estados (pólis), e, também, quanto às hipóteses de decadência dessas civilizações.", "o": "As noções de cidadania e política na Grécia e em Roma. Domínios e expansão das culturas grega e romana Significados do conceito de “império” e as lógicas de conquista, conflito e negociação dessa forma de organização política As diferentes formas de organização política na África: reinos, impérios, cidades- estados e sociedades ou aldeias."}, {"a": "6", "t": "2", "c": "EF06HI11/ES", "e": "Lógicas de organização política", "h": "Caracterizar o processo de formação da Roma Antiga e suas configurações sociais e políticas nos períodos monárquico e republicano.", "o": "As noções de cidadania e política na Grécia e em Roma Domínios e expansão das culturas grega e romana Significados do conceito de “império” e as lógicas de conquista, conflito e negociação dessa forma de organização política As diferentes formas de organização política na África: reinos, impérios, cidades- estados e sociedades ou aldeias."}, {"a": "6", "t": "2", "c": "EF06HI12/ES", "e": "Lógicas de organização política", "h": "Associar o conceito de cidadania a dinâmicas de inclusão e exclusão na Grécia e Roma antigas, compreendendo as diversas apropriações e significados ampliados do conceito de cidadania, república e democracia ao longo do tempo e nos dias atuais, problematizando as mudanças e permanências entre a democracia ateniense e a democracia no Brasil atual.", "o": "As noções de cidadania e política na Grécia e em Roma. Domínios e expansão das culturas grega e romana. Significados do conceito de “império” e as lógicas de conquista, conflito e negociação dessa forma de organização política. As diferentes formas de organização política na África: reinos, impérios, cidades-estados e sociedades ou aldeias."}, {"a": "6", "t": "3", "c": "EF06HI13/ES", "e": "Lógicas de organização política", "h": "Conceituar “império” no mundo antigo, com vistas à análise das diferentes formas de equilíbrio e desequilíbrio entre as partes envolvidas, identificando as causas da queda do Império Romano e a transição para o Feudalismo na Europa, percebendo a complexidade da crise do século III.", "o": "As noções de cidadania e política na Grécia e em Roma Domínios e expansão das culturas grega e romana Significados do conceito de “império” e as lógicas de conquista, conflito e negociação dessa forma de organização política As diferentes formas de organização política na África: reinos, impérios, cidades- estados e sociedades ou aldeias."}, {"a": "6", "t": "3", "c": "EF06HI14/ES", "e": "Lógicas de organização política", "h": "Identificar e analisar diferentes formas de contato, adaptação ou exclusão entre populações em diferentes tempos e espaços, compreendendo as diferentes formas de organização presentes na África, Ásia, América e Europa.", "o": "A passagem do mundo antigo para o mundo medieval. A fragmentação do poder político na Idade Média."}, {"a": "6", "t": "3", "c": "EF06HI15/ES", "e": "Lógicas de organização política", "h": "Descrever as dinâmicas de circulação de pessoas, produtos e culturas no Mediterrâneo e seu significado para o desenvolvimento de diversos reinos e impérios do continente africano e asiático, compreendendo a dinâmica comercial destes territórios com a Europa e as contribuições culturais dos povos africanos, semitas, orientais e indo-europeus.", "o": "O Mediterrâneo como espaço de interação entre as sociedades da Europa, da África e do Oriente Médio."}, {"a": "6", "t": "3", "c": "EF06HI16/ES", "e": "Trabalho e formas de organização social e cultural", "h": "Caracterizar e comparar as dinâmicas de abastecimento e as formas de organização do trabalho e da vida social em diferentes sociedades e períodos, com destaque para as relações entre senhores e servos, percebendo o papel da igreja na organização da sociedade europeia medieval e a atuação da inquisição.", "o": "Senhores e servos no mundo antigo e no medieval. Escravidão e trabalho livre em diferentes temporalidades e espaços (Roma Antiga, Europa medieval e África) Lógicas comerciais na Antiguidade romana e no mundo medieval."}, {"a": "6", "t": "3", "c": "EF06HI17/ES", "e": "Trabalho e formas de organização social e cultural", "h": "Diferenciar escravidão, servidão e trabalho livre no mundo antigo, medieval e no tempo presente.", "o": "Senhores e servos no mundo antigo e no medieval Escravidão e trabalho livre em diferentes temporalidades e espaços (Roma Antiga, Europa medieval e África). Lógicas comerciais na Antiguidade romana e no mundo medieval."}, {"a": "6", "t": "3", "c": "EF06HI18/ES", "e": "Trabalho e formas de organização social e cultural", "h": "Analisar o papel da religião cristã na cultura e nos modos de organização social no período medieval, verificando a expansão do islamismo pelo norte da África e Península Ibérica.", "o": "O papel da religião cristã, dos mosteiros, e da cultura na Idade Média."}, {"a": "6", "t": "3", "c": "EF06HI19/ES", "e": "Trabalho e formas de organização social e cultural.", "h": "Descrever e analisar os diferentes papéis sociais das mulheres no mundo antigo e nas sociedades medievais, evidenciando tanto as representações sociais que estabelecem padrões, ideias de comportamento ou de desvios das normas vigentes (como nas sociedades cristãs são símbolos de Eva, Maria, Maria Madalena), como a sua participação, em conflitos bélicos, desempenhando funções religiosas e intelectuais (a exemplo de Hildegarda de Bingen, Christine de Pisan). Problematizando o controle sobre o corpo, sexualidade e os saberes femininos e como os ideais de beleza, através do culto ao corpo físico e estético, são recodificados e organizados de acordo com a cultura, religião, etnia e tempo histórico.", "o": "O papel da mulher na Grécia e em Roma, e no período medieval."}, {"a": "7", "t": "1", "c": "EF07HI01/ES", "e": "O mundo moderno e a conexão entre sociedades africanas, americanas e europeias", "h": "Explicar o significado de “modernidade” e suas lógicas de inclusão e exclusão, com base em uma concepção europeia, identificando semelhanças e diferenças entre a modernidade europeia e as demais sociedades em outros territórios/espaços.", "o": "A construção da ideia de modernidade e seus impactos na concepção de História. A ideia de “Novo Mundo” ante o Mundo Antigo: permanências e rupturas de saberes e práticas na emergência do mundo moderno."}, {"a": "7", "t": "1", "c": "EF07HI02/ES", "e": "O mundo moderno e a conexão entre sociedades africanas, americanas e europeias", "h": "Identificar conexões e interações entre as sociedades do Novo Mundo, da Europa, da África e da Ásia no contexto das navegações e indicar a complexidade e as interações que ocorrem nos Oceanos Atlântico, Índico e Pacífico. Examinando a Diáspora Africana, os fluxos migratórios de pessoas, transposição de fauna, flora e cultura imaterial, trazidas para a América, o Brasil e o Espírito Santo a partir deste movimento histórico que se apresenta no início da modernidade europeia.", "o": "A construção da ideia de modernidade e seus impactos na concepção de História. A ideia de “Novo Mundo” ante o Mundo Antigo: permanências e rupturas de saberes e práticas na emergência do mundo moderno."}, {"a": "7", "t": "1", "c": "EF07HI03/ES", "e": "O mundo moderno e a conexão entre sociedades africanas, americanas e europeias", "h": "Identificar aspectos e processos específicos das sociedades africanas e americanas antes da chegada dos europeus, com destaque para as formas de organização social e o desenvolvimento de saberes e técnicas, dando evidência às diversas etnias indígenas que habitavam o Espírito Santo e percebendo que cada sociedade pode estar vivenciando um período distinto da história.", "o": "Saberes dos povos africanos e pré-colombianos expressos na cultura material e imaterial."}, {"a": "7", "t": "1", "c": "EF07HI04/ES", "e": "Humanismos, Renascimento, Reforma Protestante e o Novo Mundo", "h": "Identificar as principais características do Humanismo e do Renascimento e analisar seus significados.", "o": "Humanismos: uma nova visão de ser humano e de mundo Renascimentos artísticos e culturais. Renascimentos artísticos e culturais."}, {"a": "7", "t": "1", "c": "EF07HI05/ES", "e": "Humanismos, Renascimento, Reforma Protestante e o Novo Mundo", "h": "Identificar e relacionar as vinculações entre as reformas religiosas, os processos culturais e sociais do período moderno na Europa e na América, o papel político e a classe social protagonista dessas transformações nas ideias e maneira de pensar e se comportar na sociedade, percebendo as mudanças nas estruturas políticas, sociais e culturais, dando ênfase para as transformações ocorridas na Europa e, consequentemente, sentidas nas colônias da América, em especial, no Brasil e no Espírito Santo. Identificado esses discursos na literatura, arquitetura e organização política e etc.", "o": "Reformas religiosas: a cristandade fragmentada, o papel da igreja e da inquisição na organização social nas colônias."}, {"a": "7", "t": "2", "c": "EF07HI06/ES", "e": "Humanismos, Renascimento, Reforma Protestante e o Novo Mundo", "h": "Comparar as navegações no Atlântico, no Índico e no Pacífico entre os séculos XIV e XVI, analisando cartas náuticas e documentos da época que possam materializar os deslocamentos migratórios, mudanças na sociedade, na religião, no poder político e econômico que surgem a partir do domínio e estabelecimento de novas rotas comerciais nesses oceanos por nações europeias.", "o": "As descobertas científicas e a expansão marítima"}, {"a": "7", "t": "2", "c": "EF07HI07/ES", "e": "A organização do poder e as dinâmicas do mundo colonial americano", "h": "Descrever os processos de formação e consolidação das monarquias e suas principais características com vistas à compreensão das razões da centralização política e identificar os interesses sociais, culturais e religiosos que acarretaram a formação dos Estados Absolutistas.", "o": "A formação e o funcionamento das monarquias europeias: a lógica da centralização política e os conflitos na Europa."}, {"a": "7", "t": "2", "c": "EF07HI08/ES", "e": "A organização do poder e as dinâmicas do mundo colonial americano", "h": "Descrever as formas de organização das sociedades americanas no tempo da conquista com vistas à compreensão dos mecanismos de alianças, confrontos e resistências no Brasil e no Espírito Santo, ressaltando a Batalha do Cricaré, em 1558 e na República negra de Guarapari.", "o": "A conquista da América e as formas de organização política dos indígenas e europeus: conflitos, dominação e conciliação."}, {"a": "7", "t": "2", "c": "EF07HI09/ES", "e": "A organização do poder e as dinâmicas do mundo colonial americano", "h": "Analisar os diferentes impactos da conquista europeia da América para as populações ameríndias e africanas e identificar as diversas formas de resistência: guerra justa, fuga para o interior, suicídios, banzo, criação de quilombos, abortos, religião e sincretismos, danças, músicas e o resgate de histórias de personagens símbolos de resistência (como Tupac Amaro, Zacimba Gaba, Zumbi dos Palmares, entre outros).", "o": "A conquista da América e as formas de organização política dos indígenas e europeus: conflitos, dominação e conciliação."}, {"a": "7", "t": "2", "c": "EF07HI10/ES", "e": "A organização do poder e as dinâmicas do mundo colonial americano", "h": "Analisar, com base em documentos históricos, diferentes interpretações sobre as dinâmicas das sociedades americanas no período colonial, evidenciando o papel das mulheres, hierarquizado conforme sua origem étnica, no projeto colonizador.", "o": "A estruturação dos vice-reinos nas Américas Resistências indígenas, invasões e expansão na América portuguesa. As rebeliões e resistências coloniais (Mascates, Emboabas, Confederação dos Tamoios, Quilombo dos Palmares, Queimados, Sapê do Norte - ES) As invasões holandesa e francesa e a decadência da produção açucareira. As missões jesuíticas e a exploração das drogas de sertão. O processo de colonização do território capixaba. Economia canavieira, mineradora, tropismo, organização administrativa da colônia, sociedade, arte e cultura colonial."}, {"a": "7", "t": "2", "c": "EF07HI11/ES", "e": "A organização do poder e as dinâmicas do mundo colonial americano", "h": "Analisar a formação histórico-geográfica do território da América portuguesa, sobretudo, o território do Espírito Santo, por meio de mapas históricos.", "o": "A estruturação dos vice-reinos nas Américas Resistências indígenas, invasões e expansão na América portuguesa. As rebeliões e resistências coloniais (Mascates, Emboabas, Confederação dos Tamoios, Quilombo dos Palmares, Queimados, Sapê do Norte - ES) As invasões holandesa e francesa e a decadência da produção açucareira. As missões jesuíticas e a exploração das drogas de sertão. O processo de colonização do território capixaba. Economia canavieira, mineradora, tropismo, organização administrativa da colônia, sociedade, arte e cultura colonial."}, {"a": "7", "t": "3", "c": "EF07HI12/ES", "e": "A organização do poder e as dinâmicas do mundo colonial americano", "h": "Identificar a distribuição territorial da população brasileira em diferentes épocas, considerando a diversidade étnico-racial e étnico-cultural (indígena, africana, europeia e asiática).", "o": "A estruturação dos vice-reinos nas Américas Resistências indígenas, invasões e expansão na América portuguesa. As rebeliões e resistências coloniais (Mascates, Emboabas, Confederação dos Tamoios, Quilombo dos Palmares, Queimados, Sapê do Norte - ES) As invasões holandesa e francesa e a decadência da produção açucareira. As missões jesuíticas e a exploração das drogas de sertão. O processo de colonização do território capixaba. Economia canavieira, mineradora, tropismo, organização administrativa da colônia, sociedade, arte e cultura colonial."}, {"a": "7", "t": "3", "c": "EF07HI13/ES", "e": "Lógicas comerciais e mercantis da modernidade", "h": "Caracterizar a ação dos europeus e suas lógicas mercantis visando ao domínio no mundo atlântico.", "o": "As lógicas mercantis e o domínio europeu sobre os mares e o contraponto oriental."}, {"a": "7", "t": "3", "c": "EF07HI14/ES", "e": "Lógicas comerciais e mercantis da modernidade", "h": "Descrever as dinâmicas comerciais das sociedades americanas e africanas e analisar suas interações com outras sociedades do Ocidente e do Oriente.", "o": "As lógicas mercantis e o domínio europeu sobre os mares e o contraponto oriental."}, {"a": "7", "t": "3", "c": "EF07HI15/ES", "e": "Lógicas comerciais e mercantis da modernidade", "h": "Discutir o conceito de escravidão moderna e suas distinções em relação ao escravismo antigo e à servidão medieval, compreendendo no tempo presente que o trabalho forçado restringe a liberdade dos indivíduos, obrigando-os a prestarem serviço em situações precárias e insalubres, sem pagamento ou recebendo valor insuficiente para sua sobrevivência e dignidade humana.", "o": "As lógicas internas das sociedades africanas. As formas de organização das sociedades ameríndias A escravidão moderna e o tráfico de escravizados"}, {"a": "7", "t": "3", "c": "EF07HI16/ES", "e": "Lógicas comerciais e mercantis da modernidade", "h": "Analisar os mecanismos e as dinâmicas de comércio de escravizados em suas diferentes fases, identificando os agentes responsáveis pelo tráfico e as regiões, zonas africanas de procedência dos escravizados e as especificidades da escravidão envolvendo etnias africanas, anterior ao comercio transatlântico na África, e depois nas colônias.", "o": "As lógicas internas das sociedades africanas. As formas de organização das sociedades ameríndias. A escravidão moderna e o tráfico de escravizados."}, {"a": "7", "t": "3", "c": "EF07HI17/ES", "e": "Lógicas comerciais e mercantis da modernidade", "h": "Discutir as razões da passagem do mercantilismo para o capitalismo, evidenciando que tais revoluções transformaram estruturas sociais, mudaram formas de pensamento, ocasionando o fim das relações feudais. Identificando que a crise na estrutura da sociedade feudal ocorreu quando as relações de produção servis se tornaram um obstáculo para o desenvolvimento das forças produtivas, sobretudo, a partir do retorno do comércio, do desenvolvimento das manufaturas e surgimento das teorias liberais (que contestavam a participação do Estado na economia).", "o": "A emergência do capitalismo"}, {"a": "8", "t": "1", "c": "EF08HI01/ES", "e": "O mundo contemporâneo: o Antigo Regime em crise.", "h": "Identificar os principais aspectos conceituais do iluminismo e do liberalismo e discutir a relação entre eles e a organização do mundo contemporâneo. Compreendendo como a influência do Iluminismo foi importante para uma mudança nos hábitos políticos e culturais da Europa, evidenciando as mudanças trazidas: o aumento da leitura, a produção de manuais didáticos e enciclopédicos. Percebendo que esses instrumentos são de valiosa importância para a circulação do conhecimento laico e mudanças no comportamento cultural, social, político e econômico do século XVIII.", "o": "A questão do iluminismo e da ilustração"}, {"a": "8", "t": "1", "c": "EF08HI02/ES", "e": "O mundo contemporâneo: o Antigo Regime em crise.", "h": "Identificar as particularidades político-sociais da Inglaterra do século XVII e analisar os desdobramentos posteriores à Revolução Gloriosa.", "o": "As revoluções inglesas e os princípios do liberalismo"}, {"a": "8", "t": "1", "c": "EF08HI03/ES", "e": "O mundo contemporâneo: o Antigo Regime em crise.", "h": "Analisar os impactos da Revolução Industrial na produção e circulação de povos, produtos e culturas, identificando os impactos ocorridos no Brasil e na província do Espírito Santo com o advento das Revoluções Burguesas na Europa e, posteriormente, na América.", "o": "Revolução Industrial e seus impactos na produção e circulação de povos, produtos e culturas. O movimento operário, os socialismos, as transformações tecnológicas e sociais. Segunda Revolução Industrial, a emergência de novas potências no século XIX. A Revolução como processo histórico inacabado: tecnologias e relações de trabalho na atualidade."}, {"a": "8", "t": "1", "c": "EF08HI04/ES", "e": "OO mundo contemporâneo: oo Antigo Regime em crise.", "h": "Identificar e relacionar os processos da Revolução Francesa e seus desdobramentos na Europa e no mundo, considerando a importância da Revolução Francesa em diversos processos históricos ocorridos no Brasil e no Espírito Santo nesse período e posteriormente, guiados pelas ideias disseminadas durante esse acontecimento histórico.", "o": "Revolução Francesa e seus desdobramentos."}, {"a": "8", "t": "1", "c": "EF08HI05/ES", "e": "O mundo contemporâneo: o Antigo Regime em crise.", "h": "Explicar os movimentos e as rebeliões da América portuguesa, articulando as temáticas locais e suas interfaces com processos ocorridos na Europa e nas Américas, as consequências e impactos das mudanças ocorridas na Europa no Brasil aurífero, as revoltas e a transição da colônia para o Império.", "o": "Rebeliões na América portuguesa: as conjurações mineiras e baiana."}, {"a": "8", "t": "1", "c": "EF08HI06/ES", "e": "Os processos de independência nas Américas.", "h": "Aplicar os conceitos de Estado, nação, território, governo e país para o entendimento de conflitos e tensões.", "o": "Independência dos Estados Unidos da América independências na América espanhola. A revolução dos escravizados em São Domingo e seus múltiplos significados e desdobramentos: o caso do Haiti."}, {"a": "8", "t": "1", "c": "EF08HI07/ES", "e": "Os processos de independência nas Américas.", "h": "Identificar e contextualizar as especificidades dos diversos processos de independência nas Américas, seus aspectos populacionais e suas conformações territoriais.", "o": "Independência dos Estados Unidos da América independências na América espanhola. A revolução dos escravizados em São Domingo e seus múltiplos significados e desdobramentos: o caso do Haiti."}, {"a": "8", "t": "1", "c": "EF08HI08/ES", "e": "Os processos de independência nas Américas.", "h": "Conhecer o ideário dos líderes dos movimentos independentistas e seu papel nas revoluções que levaram à independência as colônias hispano- americanas.", "o": "Independência dos Estados Unidos da América independências na América espanhola A revolução dos escravizados em São Domingo e seus múltiplos significados e desdobramentos: o caso do Haiti."}, {"a": "8", "t": "1", "c": "EF08HI09/ES", "e": "Os processos de independência nas Américas.", "h": "Conhecer as características e os principais pensadores do Pan-americanismo.", "o": "Independência dos Estados Unidos da América independências na América espanhola A revolução dos escravizados em São Domingo e seus múltiplos significados e desdobramentos: o caso do Haiti."}, {"a": "8", "t": "2", "c": "EF08HI10/ES", "e": "Os processos de independência nas Américas.", "h": "Identificar a Revolução de São Domingos como evento singular devido o protagonismo afrodescendente e desdobramento da Revolução Francesa como fator de aceleramento do processo de independência e avaliar suas implicações na fundação da República Haitiana.", "o": "Independência dos Estados Unidos da América independências na América espanhola."}, {"a": "8", "t": "2", "c": "EF08HI11/ES", "e": "Os processos de independência nas Américas.", "h": "Identificar e explicar os protagonismos e a atuação de diferentes grupos sociais e étnicos nas lutas de independência nos Estados Unidos, no Brasil, na América espanhola e no Haiti, compreendendo o conceito de nação e Estado no passado e no tempo presente, como questões de terras, conflitos étnicos, culturais e religiosos, considerando o contexto latino-americano.", "o": "Os caminhos até a Independência do Brasil."}, {"a": "8", "t": "2", "c": "EF08HI12/ES", "e": "Os processos de independência nas Américas.", "h": "Caracterizar a organização política e social no Brasil desde a chegada da Corte portuguesa, em 1808, até 1822 e seus desdobramentos para a história política brasileira.", "o": "Os caminhos até a Independência do Brasil."}, {"a": "8", "t": "2", "c": "EF08HI13/ES", "e": "Os processos de independência nas Américas.", "h": "Analisar o processo de independência em diferentes países latino-americanos e comparar as formas de governo neles adotadas.", "o": "Os caminhos até a Independência do Brasil."}, {"a": "8", "t": "2", "c": "EF08HI14/ES", "e": "Os processos de independência nas Américas.", "h": "Discutir a noção da tutela dos grupos indígenas e a participação dos negros na sociedade brasileira do final do período colonial, identificando permanências na forma de preconceitos, estereótipos e violências sobre as populações indígenas e negras no Brasil, no Espírito Santo e seus municípios e nas Américas.", "o": "A tutela da população indígena, a escravidão dos negros e a tutela dos egressos da escravidão."}, {"a": "8", "t": "2", "c": "EF08HI15/ES", "e": "O Brasil no século XIX", "h": "Identificar e analisar o equilíbrio das forças e os sujeitos envolvidos nas disputas políticas durante o Primeiro e o Segundo Reinado.", "o": "Brasil do Primeiro Reinado. O Período Regencial e as contestações ao poder central. O Brasil do Segundo Reinado: política e economia. A Lei de Terras e seus desdobramentos na política do Segundo Reinado."}, {"a": "8", "t": "2", "c": "EF08HI16/ES", "e": "O Brasil no século XIX.", "h": "Identificar, comparar e analisar a diversidade política, social e regional nas rebeliões e nos movimentos contestatórios ao poder centralizado, evidenciando os movimentos separatistas e de contestação que ocorreram no Espírito Santo, em especial, a Insurreição de Queimado. Em relação à Lei de Terras, há elementos que indicam a interferência do Estado através da política de branqueamento e teorias raciais que justificam a desigualdade e a ausência do governo na assistência de minorias étnicas.", "o": "O Brasil do Primeiro Reinado. O Período Regencial e as contestações ao poder central. O Brasil do Segundo Reinado: política e economia. A Lei de Terras e seus desdobramentos na política do Segundo Reinado."}, {"a": "8", "t": "2", "c": "EF08HI17/ES", "e": "O Brasil no século XIX.", "h": "Relacionar as transformações territoriais, em razão de questões de fronteiras, com as tensões e conflitos durante o Império.", "o": "Territórios e fronteiras: a Guerra do Paraguai. A economia cafeeira e suas conexões com os países industrializados e o movimento republicano no Brasil."}, {"a": "8", "t": "2", "c": "EF08HI18/ES", "e": "O Brasil no século XIX.", "h": "Identificar as questões internas e externas sobre a atuação do Brasil na Guerra do Paraguai e discutir diferentes versões sobre o conflito, evidenciando a participação de negros escravizados compondo o exército brasileiro e sua relação com o movimento republicano.", "o": "Territórios e fronteiras: a Guerra do Paraguai. A economia cafeeira e suas conexões com os países industrializados e o movimento republicano no Brasil."}, {"a": "8", "t": "3", "c": "EF08HI19/ES", "e": "O Brasil no século XIX.", "h": "Formular questionamentos sobre o legado da escravidão nas Américas, com base na seleção e consulta de fontes de diferentes naturezas, identificando o protagonismo (cultural, alimentar, étnico, religioso etc.) da população afrodescendente no Espírito Santo, dando evidencia a formação em Ecoporanga do Patrimônio dos Pretos.", "o": "O escravismo no Brasil do século XIX: plantations e revoltas de escravizados, abolicionismo e políticas migratórias no Brasil Imperial."}, {"a": "8", "t": "3", "c": "EF08HI20/ES", "e": "O Brasil no século XIX", "h": "Identificar e relacionar aspectos das estruturas sociais da atualidade com os legados da escravidão no Brasil, no Espírito Santo, e, sobretudo, o papel do Porto de São Mateus como local de entrada e comércio de escravos e discutir a importância de ações afirmativas.", "o": "O escravismo no Brasil do século XIX: plantations e revoltas de escravizados, abolicionismo e políticas migratórias no Brasil Imperial."}, {"a": "8", "t": "3", "c": "EF08HI21/ES", "e": "O Brasil no século XIX.", "h": "Identificar e analisar as políticas oficiais com relação ao indígena durante o Império, evidenciando a condição das variadas etnias que habitavam o Espírito Santo neste contexto histórico.", "o": "Políticas de genocídio e extermínio do indígena durante o Império."}, {"a": "8", "t": "3", "c": "EF08HI22/ES", "e": "O Brasil no século XIX.", "h": "Discutir o papel das culturas letradas, não letradas e das artes na produção das identidades no Brasil do século XIX, identificando manifestações culturais letradas e não letradas específicas do território, utilizando como ferramenta a história oral.", "o": "Políticas de genocídio e extermínio do indígena durante o Império."}, {"a": "8", "t": "3", "c": "EF08HI23/ES", "e": "Configurações do mundo no século XIX.", "h": "Estabelecer relações causais entre as ideologias raciais e o determinismo no contexto do imperialismo europeu e seus impactos na África e na Ásia, verificando que no caso do Brasil e do Espírito Santo, conduziu ao projeto político/social de branqueamento da população. O darwinismo social, no contexto histórico do século XIX e início do século XX, legitimou o imperialismo/ neocolonialismo.", "o": "Nacionalismo, revoluções e as novas nações europeias."}, {"a": "8", "t": "3", "c": "EF08HI24/ES", "e": "Configurações do mundo no século XIX.", "h": "Reconhecer a origem dos principais produtos, utilizados pelos europeus, procedentes do continente africano e asiático durante o imperialismo e analisar os impactos do comércio transatlântico sobre as comunidades locais na forma de organização e exploração econômica, relacionando sua utilização e apropriação por parte da população capixaba, repensando o uso e valor cultural no presente.", "o": "Uma nova ordem econômica: as demandas do capitalismo industrial e o lugar das economias africanas e asiáticas nas dinâmicas globais."}, {"a": "8", "t": "3", "c": "EF08HI25/ES", "e": "Configurações do mundo no século XIX.", "h": "Caracterizar e contextualizar aspectos das relações entre os Estados Unidos da América e a América Latina no século XIX, identificando a atuação dos Estados Unidos na América, com a política de “América para os americanos”.", "o": "Os Estados Unidos da América e a América Latina no século XIX."}, {"a": "8", "t": "3", "c": "EF08HI26/ES", "e": "Configurações do mundo no século XIX.", "h": "Identificar e contextualizar o protagonismo das populações locais na resistência ao imperialismo na África e Ásia.", "o": "O imperialismo/neocolonialismo europeu e a partilha da África e da Ásia."}, {"a": "8", "t": "3", "c": "EF08HI27/ES", "e": "Configurações do mundo no século XIX.", "h": "Identificar as tensões e os significados dos discursos civilizatórios, avaliando seus impactos negativos para os povos indígenas originários e as populações negras nas Américas, reconhecendo o papel da igreja, do estado e das elites na ideologia presente nos discursos que justificavam a opressão diante dessas etnias, evidenciando formas de resistência, adaptações, permanências e os processos de rupturas que se apresentavam no fim do século XIX nos discursos contrários à escravidão, monarquia absoluta etc.", "o": "Pensamento e cultura no século XIX: darwinismo e racismo. O discurso civilizatório nas Américas, o silenciamento dos saberes indígenas e as formas de integração destruição de comunidades e povos indígenas. A resistência dos povos e comunidades indígenas diante da ofensiva civilizatória."}, {"a": "9", "t": "1", "c": "EF09HI01/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Descrever e contextualizar os principais aspectos sociais, culturais, econômicos e políticos da emergência da República no Brasil, identificando a construção da lógica republicana e ideia de progresso no discurso da elite do Espírito Santo.", "o": "Experiências republicanas e práticas autoritárias: as tensões e disputas do mundo contemporâneo. A proclamação da República e seus primeiros desdobramentos."}, {"a": "9", "t": "1", "c": "EF09HI02/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Caracterizar e compreender os ciclos da história republicana, identificando particularidades da história local e regional até 1954, problematizando as particularidades no processo de consolidação da República no Espírito Santo.", "o": "Experiências republicanas e práticas autoritárias: as tensões e disputas do mundo contemporâneo. A proclamação da República e seus primeiros desdobramentos."}, {"a": "9", "t": "1", "c": "EF09HI03/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Identificar os mecanismos de inserção dos negros na sociedade brasileira pós-abolição e avaliar os seus resultados na sociedade brasileira e capixaba pós- abolição e no tempo presente, percebendo os avanços e permanências nas lutas sociais e políticas públicas que envolvam os afrodescendentes.", "o": "A questão da inserção dos negros no período republicano do pós-abolição. Os movimentos sociais e a imprensa negra; A cultura afro-brasileira como elemento de resistência e superação das discriminações."}, {"a": "9", "t": "1", "c": "EF09HI04/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Discutir a importância da participação da população negra na formação econômica, política e social do Brasil, do Espírito Santo e regiões.", "o": "A questão da inserção dos negros no período republicano do pós-abolição. Os movimentos sociais e a imprensa negra; A cultura afro-brasileira como elemento de resistência e superação das discriminações."}, {"a": "9", "t": "1", "c": "EF09HI05/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Identificar os processos de urbanização e modernização da sociedade brasileira e avaliar suas contradições e impactos no país, no estado e na região/comunidade em que vive, evidenciando os impactos das ações dos dirigentes políticos nos centros urbanos centrados na ideia de progresso, higienização e desenvolvimento no Espírito Santo, percebendo protagonismos nas lutas e movimentos sociais.", "o": "Primeira República e suas características Contestações e dinâmicas da vida cultural no Brasil entre 1900 e 1930."}, {"a": "9", "t": "1", "c": "EF09HI06/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Identificar e discutir o papel do trabalhismo como força política, social e cultural no Brasil, em diferentes escalas (nacional, regional, cidade, comunidade), problematizando a manipulação de populações marginalizadas e suas expressões como símbolos da cultura nacional (negros, samba, futebol, carnaval).", "o": "O período varguista e suas contradições. A emergência da vida urbana e a segregação espacial. O trabalhismo e seu protagonismo político."}, {"a": "9", "t": "1", "c": "EF09HI07/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Identificar e explicar, em meio a lógicas de inclusão e exclusão, as pautas dos povos indígenas, no contexto republicano (até 1964), e das populações afrodescendentes, enfatizando e mapeando as etnias presentes no Espírito Santo, tribos, quilombos e movimentos sociais relacionados às demandas de inclusão social desses povos e comunidades tradicionais. Evidenciando o respeito à diversidade étnica, hibridismo cultural e sincretismo religioso.", "o": "A questão indígena e quilombola durante a República (até 1964)."}, {"a": "9", "t": "1", "c": "EF09HI08/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Identificar as transformações ocorridas no debate sobre as questões da diversidade no Brasil e no Espírito Santo durante o século XX e início do século XXI e compreender o significado das mudanças de abordagem em relação ao tema, através de lutas e mobilizações sociais, tais como o movimento feminista e as reinvindicações que se materializam em políticas públicas e marcos legal (combate a violência, acesso à educação, mercado de trabalho).", "o": "Anarquismo e protagonismo feminino: lutas e conquistas de gênero e pelo respeito à diversidade e minorias no Brasil e no Espírito Santo."}, {"a": "9", "t": "1", "c": "EF09HI09/ES", "e": "O nascimento da República no Brasil e os processos históricos até a metade do século XX.", "h": "Relacionar as conquistas de direitos políticos, sociais e civis à atuação de movimentos sociais, identificando os principais movimentos sociais presentes e atuantes no Espírito Santo e na sua comunidade, enfatizando suas demandas e conquistas.", "o": "Anarquismo e protagonismo feminino: lutas e conquistas de gênero e pelo respeito à diversidade e minorias no Brasil e No Espírito Santo."}, {"a": "9", "t": "1", "c": "EF09HI10/ES", "e": "Totalitarismos e conflitos mundiais.", "h": "Identificar e relacionar as dinâmicas do capitalismo e suas crises, os grandes conflitos mundiais e os conflitos vivenciados na Europa, verificando a participação do Brasil e do Espírito Santo no contexto histórico entre as duas Grandes Guerras.", "o": "O mundo em conflito: a Primeira Guerra Mundial A questão da Palestina. A Revolução Russa. A crise capitalista de 1929."}, {"a": "9", "t": "1", "c": "EF09HI11/ES", "e": "Totalitarismos e conflitos mundiais.", "h": "Identificar as especificidades e os desdobramentos mundiais da Revolução Russa e seu significado histórico.", "o": "O mundo em conflito: a Primeira Guerra Mundial A questão da Palestina. A Revolução Russa. A crise capitalista de 1929."}, {"a": "9", "t": "1", "c": "EF09HI12/ES", "e": "Totalitarismos e conflitos mundiais.", "h": "Analisar a crise capitalista de 1929 e seus desdobramentos em relação à economia global, nacional e do Espírito Santo.", "o": "O mundo em conflito: a Primeira Guerra Mundial A questão da Palestina. A Revolução Russa. A crise capitalista de 1929."}, {"a": "9", "t": "2", "c": "EF09HI13/ES", "e": "Totalitarismos e conflitos mundiais.", "h": "Descrever e contextualizar os processos da emergência do fascismo e do nazismo, a consolidação dos estados totalitários e as práticas de extermínio (como o holocausto) de judeus, ciganos, negros, mulheres e demais minorias, identificando traços totalitários e do integralismo no governo do presidente Getúlio Vargas e no interventor do Espírito Santo, no mesmo período, Punário Bley, fazendo aproximações com os governos totalitários da Europa.", "o": "A emergência do fascismo e do nazismo. A Segunda Guerra Mundial: Judeus e outras vítimas do holocausto."}, {"a": "9", "t": "2", "c": "EF09HI14/ES", "e": "Totalitarismos e conflitos mundiais.", "h": "Caracterizar e discutir as dinâmicas do colonialismo no continente africano e asiático e as lógicas de resistência e de conciliação das populações locais diante das questões internacionais, identificando protagonistas históricos (Nelson Mandela, Gandhi, entre outros) que resistiram ao imperialismo e percebendo, no tempo presente, a permanência de conflitos e as consequências políticas, econômicas, étnicas e culturais do neocolonialismo ou partilha da África e Ásia.", "o": "O colonialismo/ Partilha/ Neocolonialismo na África e Ásia. As guerras mundiais, a crise do colonialismo e o advento dos nacionalismos africanos e asiáticos."}, {"a": "9", "t": "2", "c": "EF09HI15/ES", "e": "Totalitarismos e conflitos mundiais.", "h": "Discutir as motivações que levaram à criação da Organização das Nações Unidas (ONU) no contexto do pós-guerra e os propósitos dessa organização, identificando o papel da ONU nos dias atuais em relação ao Brasil e ao mundo, sobretudo, no que concernem políticas públicas, economia internacional, relações de poder e de trabalho e conflitos bélicos. Compreendendo o posicionamento da instituição diante dos fluxos migratórios no pós-guerra e nos dias atuais, com enfoque nas questões humanitárias.", "o": "A Organização das Nações Unidas (ONU) e a questão dos Direitos Humanos."}, {"a": "9", "t": "2", "c": "EF09HI16/ES", "e": "Totalitarismos e conflitos mundiais.", "h": "Relacionar a Carta dos Direitos Humanos ao processo de afirmação dos direitos fundamentais e de defesa da dignidade humana, valorizando as instituições voltadas para a defesa desses direitos e para a identificação dos agentes responsáveis por sua violação. Compreendendo que os documentos e marcos legais garantem o direito à igualdade, liberdade, diversidade e pluralidade, direito à educação pública, eliminação de qualquer tipo de preconceito (institucional, ambiental, alimentar, entre outros), respeito à diversidade religiosa, ambiental, sexual.", "o": "A Organização das Nações Unidas (ONU) e a questão dos Direitos Humanos."}, {"a": "9", "t": "2", "c": "EF09HI17/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Identificar e analisar processos sociais, econômicos, culturais e políticos do Brasil, do Espírito Santo e da região do entorno escolar a partir de 1946 até o tempo presente. Analisando e produzindo linhas cronológicas que destaquem esses movimentos históricos, manuseando e utilizando fontes históricas diversas como memória coletiva, línguas, dialetos, marcos e conquistas políticas e práticas culturais.", "o": "O Brasil da era JK e o ideal de uma nação moderna: a urbanização e seus desdobramentos em um país em transformação."}, {"a": "9", "t": "2", "c": "EF09HI18/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Descrever e analisar as relações entre as transformações urbanas e seus impactos na cultura brasileira e capixaba entre 1946 e 1964 e na produção das desigualdades e bolsões de pobreza regionais e sociais, identificando fluxos migratórios e o êxodo rural no Brasil e no Espírito Santo, sobretudo, a partir da política de erradicação do café que ocasiona mudanças nas relações campo e cidade, impactos ambientais e gera condições de risco social às populações que sofrem deslocamentos.", "o": "O Brasil da era JK e o ideal de uma nação moderna: a urbanização e seus desdobramentos em um país em transformação."}, {"a": "9", "t": "2", "c": "EF09HI19/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Identificar e compreender o processo que resultou na ditadura civil-militar no Brasil e discutir a emergência de questões relacionadas à memória e à justiça sobre os casos de violação dos direitos humanos.", "o": "O Brasil da era JK e o ideal de uma nação moderna: a urbanização e seus desdobramentos em um país em transformação."}, {"a": "9", "t": "2", "c": "EF09HI20/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Discutir os processos de resistência e as propostas de reorganização da sociedade brasileira e capixaba durante a ditadura civil-militar. Identificando organizações da sociedade civil que continuam atuando na política, na mídia, na economia, nas variadas instituições e na memória e imaginário dos brasileiros.", "o": "Os anos 1960: revolução cultural? A ditadura civil-militar e os processos de resistência. As questões indígena e negra e a ditadura."}, {"a": "9", "t": "2", "c": "EF09HI21/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Identificar e relacionar as demandas indígenas e quilombolas como forma de contestação ao modelo desenvolvimentista da ditadura. Compreendendo que o projeto político da coalisão civil-militar de erradicação do café no Espírito Santo retirou o direito à terra, ocasionou miséria nas cidades e comunidades quilombolas, povos indígenas, seringueiros, castanheiros, quebradeiras de coco, desfiadeiras de siris, pescadores, ribeirinhos, dentre outros; e que a violência repressiva e o controle eram impostos sobre todos os setores da sociedade, além da ausência de liberdades civis e públicas.", "o": "Os anos 1960: revolução cultural? A ditadura civil-militar e os processos de resistência. As questões indígena e negra e a ditadura."}, {"a": "9", "t": "2", "c": "EF09HI22/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Discutir o papel da mobilização da sociedade brasileira do final do período ditatorial até a Constituição de 1988, analisando que apesar da forte resistência encontrada, a mobilização popular conseguiu persistir e imprimir muitas de suas reivindicações no texto constitucional. A Constituição Federal de 1988 institui a garantia dos direitos fundamentais à educação, saúde, trabalho e moradia, que se realizam no exercício da cidadania e da constante mobilização social.", "o": "O processo de redemocratização. A Constituição de 1988 e a emancipação das cidadanias (analfabetos, indígenas, negros, jovens etc.) A história recente do Brasil: transformações políticas, econômicas, sociais e culturais de 1989 aos dias atuais. Os protagonismos da sociedade civil e as alterações da sociedade brasileira. A questão da violência contra populações marginalizadas. O Brasil e suas relações internacionais na era da globalização."}, {"a": "9", "t": "2", "c": "EF09HI23/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Identificar direitos civis, políticos e sociais expressos na Constituição de 1988 e relacioná-los à noção de cidadania e ao pacto da sociedade brasileira de combate a diversas formas de preconceito, como o racismo. Considerando outros documentos e marcos legais posteriores que caminham na mesma direção, criando mecanismos (gráficos, tabelas e linhas temporais) que materializem os avanços, transformações, perspectivas de futuro e lutas no presente referente à superação do racismo e outras formas de preconceito (institucional, ambiental, étnico, religioso, sexual, alimentar, entre outros) e a eliminação de toda e qualquer forma de preconceito e discriminação.", "o": "O processo de redemocratização A Constituição de 1988 e a emancipação das cidadanias (analfabetos, indígenas, negros, jovens etc.) A história recente do Brasil: transformações políticas, econômicas, sociais e culturais de 1989 aos dias atuais. Os protagonismos da sociedade civil e as alterações da sociedade brasileira. A questão da violência contra populações marginalizadas. O Brasil e suas relações internacionais na era da globalização."}, {"a": "9", "t": "2", "c": "EF09HI24/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Analisar as transformações políticas, econômicas, sociais e culturais de 1989 aos dias atuais, identificando questões prioritárias para a promoção da cidadania e dos valores democráticos na comunidade em que está inserido.", "o": "O processo de redemocratização A Constituição de 1988 e a emancipação das cidadanias (analfabetos, indígenas, negros, jovens etc.) A história recente do Brasil: transformações políticas, econômicas, sociais e culturais de 1989 aos dias atuais. Os protagonismos da sociedade civil e as alterações da sociedade brasileira. A questão da violência contra populações marginalizadas. O Brasil e suas relações internacionais na era da globalização."}, {"a": "9", "t": "3", "c": "EF09HI25/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Relacionar as transformações da sociedade brasileira aos protagonismos da sociedade civil após 1989 aos dias atuais, evidenciando os avanços e conquistas e aproximando demandas sociais das necessidades da sua comunidade e escola.", "o": "O processo de redemocratização A Constituição de 1988 e a emancipação das cidadanias (analfabetos, indígenas, negros, jovens etc.) A história recente do Brasil: transformações políticas, econômicas, sociais e culturais de 1989 aos dias atuais. Os protagonismos da sociedade civil e as alterações da sociedade brasileira. A questão da violência contra populações marginalizadas. O Brasil e suas relações internacionais na era da globalização."}, {"a": "9", "t": "3", "c": "EF09HI26/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Discutir e analisar as causas da violência contra populações marginalizadas (negros, indígenas, mulheres, homossexuais, camponeses, pobres etc.) com vistas à tomada de consciência e à construção de uma cultura de paz, empatia e respeito às pessoas. Problematizando índices e dados da vitimização e mortalidade de minorias (afrodescendentes, mulheres, crianças e adolescentes, idosos, etc.) no sentido de buscar projetos de vida que contribuam para perspectivas que levam à cultura de paz e respeito à diversidade no Espírito Santo, na comunidade e na unidade escolar.", "o": "O processo de redemocratização A Constituição de 1988 e a emancipação das cidadanias (analfabetos, indígenas, negros, jovens etc.) A história recente do Brasil: transformações políticas, econômicas, sociais e culturais de 1989 aos dias atuais. Os protagonismos da sociedade civil e as alterações da sociedade brasileira. A questão da violência contra populações marginalizadas. O Brasil e suas relações internacionais na era da globalização."}, {"a": "9", "t": "3", "c": "EF09HI27/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Relacionar aspectos das mudanças econômicas, culturais e sociais ocorridas no Brasil a partir da década de 1990 ao papel do País e do Espírito Santo no cenário internacional na era da globalização, examinando os processos de urbanização, migrações de diferentes etnias e por variadas motivações, produções culturais, mudanças tecnológicas e espaciais na cidade e no campo, instalações e construções de empreendimentos, empresas e pactos comerciais estabelecidos no Estado, suas consequências e transformações para a sociedade, povos e comunidades tradicionais.", "o": "O processo de redemocratização A Constituição de 1988 e a emancipação das cidadanias (analfabetos, indígenas, negros, jovens etc.) A história recente do Brasil: transformações políticas, econômicas, sociais e culturais de 1989 aos dias atuais. Os protagonismos da sociedade civil e as alterações da sociedade brasileira. A questão da violência contra populações marginalizadas. O Brasil e suas relações internacionais na era da globalização."}, {"a": "9", "t": "3", "c": "EF09HI28/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Identificar e analisar aspectos da Guerra Fria, seus principais conflitos e as tensões geopolíticas no interior dos blocos liderados por soviéticos e estadunidenses. Compreendendo a emergência da Guerra Fria no contexto político mundial da segunda metade do século XX, os interesses e objetivos da OTAN e do Pacto de Varsóvia no âmbito das disputas estratégicas e conflitos indiretos liderados pelos Estados Unidos e pela União Soviética, e percebendo as permanências de mentalidades e imaginários que, nos dias atuais, dividem o mundo em extremos e aumentam processos de exclusão e posições de xenofobia e aversão ao outro.", "o": "O mundo pós-guerra Fria, suas mudanças e permanências. Redemocratização do Brasil, transformação e manutenção das estruturas sociais, políticas, econômicas e culturais dos anos 1990. Era digital: desafios das novas mídias e globalização e imediatismo. O Brasil contemporâneo e suas conexões com a história regional e do tempo presente. Habilidades da computação Não há."}, {"a": "9", "t": "3", "c": "EF09HI29/ES", "e": "Modernização, ditadura civil-militar e redemocratização: o Brasil após 1946.", "h": "Descrever e analisar as experiências ditatoriais na América Latina, seus procedimentos e vínculos com o poder, em nível nacional e internacional, e a atuação de movimentos de contestação às ditaduras.", "o": "O mundo pós-guerra Fria, suas mudanças e permanências. Redemocratização do Brasil, transformação e manutenção das estruturas sociais, políticas, econômicas e culturais dos anos 1990. Era digital: desafios das novas mídias e globalização e imediatismo. O Brasil contemporâneo e suas conexões com a história regional e do tempo presente."}, {"a": "9", "t": "3", "c": "EF09HI30/ES", "e": "A história recente", "h": "Comparar as características dos regimes ditatoriais latino-americanos, com especial atenção para a censura política, a opressão e o uso da força, bem como para as reformas econômicas e sociais e seus impactos.", "o": "As experiências ditatoriais na América Latina."}, {"a": "9", "t": "3", "c": "EF09HI31/ES", "e": "A história recente", "h": "Descrever e avaliar os processos de descolonização na África e na Ásia.", "o": "Os processos de descolonização na África e na Ásia."}, {"a": "9", "t": "3", "c": "EF09HI32/ES", "e": "A história recente", "h": "Analisar mudanças e permanências associadas ao processo de globalização, considerando os argumentos dos movimentos críticos às políticas globais, observando que as diferentes culturas e costumes interagem sem a necessidade de uma integração territorial e que esse processo não acontece de forma igualitária, também, levando em conta possibilidades dos costumes e valores locais de se inserir em elementos globais. Percebendo que, na era da globalização, povos e comunidades tradicionais conseguem, através das tecnologias, disseminar e divulgar para além de suas fronteiras as suas características, promovendo encontros culturais.", "o": "O fim da Guerra Fria e o processo de globalização. Políticas econômicas na América Latina."}, {"a": "9", "t": "3", "c": "EF09HI33/ES", "e": "A história recente", "h": "Analisar as transformações nas relações políticas locais e globais geradas pelo desenvolvimento das tecnologias digitais de informação e comunicação. Pensar formas de potencializar as ações que beneficiem a comunidade. Identificar jornais, grupos em redes sociais e rádios comunitárias que possam potencializar as ações em torno da comunidade e fortaleçam identidades locais.", "o": "O fim da Guerra Fria e o processo de globalização. Políticas econômicas na América Latina."}, {"a": "9", "t": "3", "c": "EF09HI34/ES", "e": "A história recente", "h": "Discutir as motivações da adoção de diferentes políticas econômicas na América Latina, assim como seus impactos sociais nos países da região, identificando que a área de livre comércio é um acordo que permite a adoção progressiva de tarifas alfandegárias comuns entre os países-membros, liberaliza o trânsito de mercadorias, pessoas, bens e capitais, percebendo os conflitos, encontros e interações entre globalização e regionalismo.", "o": "O fim da Guerra Fria e o processo de globalização. Políticas econômicas na América Latina."}, {"a": "9", "t": "3", "c": "EF09HI35/ES", "e": "A história recente", "h": "Analisar os aspectos relacionados ao fenômeno do terrorismo na contemporaneidade, considerando como acontecimentos e ações humanas que decorrem de causas políticas e sociais deflagradas por determinadas circunstâncias, incluindo os movimentos migratórios e os choques entre diferentes grupos e culturas, considerando os discursos e as práticas que marcam o atual processo de globalização econômica e suas implicações para a migração internacional e regional, considerando as políticas migratórias que respeitem e valorizem os aspectos culturais, étnicos, políticos e religiosos, (re) colocando e dando oportunidade e cidadania a esses imigrantes.", "o": "Os conflitos do século XXI e a questão do terrorismo Pluralidades e diversidades identitárias na atualidade As pautas dos povos indígenas no século XXI e suas formas de inserção no debate local, regional, nacional e internacional."}, {"a": "9", "t": "3", "c": "EF09HI36/ES", "e": "A história recente", "h": "Identificar e discutir as diversidades identitárias e seus significados históricos no início do século XXI, analisando as relações de poder, o crescimento das desigualdades e crises econômicas no contexto local, nacional e internacional e combatendo qualquer forma de preconceito e violência. Imigração, gênero, sexualidade, etnia, religião, língua, espaços/territórios são os principais fatores e temáticas que desencadeiam preconceito e devem resultar em mobilização e discussão sobre a diversidade. Percebendo que a sociedade deve buscar medidas para assegurar aos portadores de deficiência, igualdade de direitos no que se refere ao trabalho, transporte, educação e inserção social, reconhecendo o respeito à diversidade como construção histórica, social, cultural e política.", "o": "Os conflitos do século XXI e a questão do terrorismo Pluralidades e diversidades identitárias na atualidade As pautas dos povos indígenas no século XXI e suas formas de inserção no debate local, regional, nacional e internacional."}], "Língua Inglesa": [{"a": "6", "t": "1", "c": "EF06LI01/ES", "e": "Eixo Oralidade", "h": "Interagir em situações de intercâmbio oral, demonstrando iniciativa para utilizar a língua inglesa, em diferentes contextos e situações; cumprimentando, pedindo ajuda, apresentando a si mesmo e aos outros.", "o": "Práticas discursivas de interação social para a construção de laços afetivos e o convívio social"}, {"a": "6", "t": "1", "c": "EF06LI02/ES", "e": "Eixo Oralidade", "h": "Coletar informações do grupo, perguntando e respondendo sobre a família, os amigos, a escola e a comunidade, reconhecendo e valorizando o local de origem e história de vida de si próprio e dos outros.", "o": "Práticas discursivas de interação social para a construção de laços afetivos e o convívio social"}, {"a": "6", "t": "1", "c": "EF06LI07/ES", "e": "Eixo Leitura", "h": "Formular hipóteses sobre a finalidade de um texto em língua inglesa, com base em sua função, estrutura, organização textual e pistas gráficas, considerando os diversos gêneros textuais.", "o": "Hipóteses sobre a finalidade de um texto."}, {"a": "6", "t": "1", "c": "EF06LI08", "e": "Eixo Leitura", "h": "Identificar o assunto de um texto, reconhecendo sua organização textual e palavras cognatas.", "o": "Compreensão geral e específica: leitura rápida (skimming, scanning)."}, {"a": "6", "t": "1", "c": "EF06LI09", "e": "Eixo Leitura", "h": "Localizar informações específicas em texto.", "o": "Compreensão geral e específica: leitura rápida (skimming, scanning)."}, {"a": "6", "t": "1", "c": "EF06LI13", "e": "Eixo Escrita", "h": "Comparar modificações das paisagens nos lugares de vivência (bairro, cidade, estado) e os usos desses lugares em diferentes tempos, aprofundando os conceitos de paisagem e lugar, problematizando a produção e considerando os aspectos econômico, social, cultural e natural. Destacando suas singularidades e o que o diferencia e aproxima de outros lugares.", "o": "Planejamento de texto: brainstorming."}, {"a": "6", "t": "1", "c": "EF06LI14/ES", "e": "Eixo Escrita", "h": "Organizar ideias, selecionando‐as em função da estrutura e do objetivo do texto, considerando o gênero textual que será produzido.", "o": "Planejamento do texto: organização de ideias"}, {"a": "6", "t": "1", "c": "EF06LI15", "e": "Eixo Escrita", "h": "Produzir textos escritos em língua inglesa (histórias em quadrinhos, cartazes, chats, blogs, agendas, fotolegendas, entre outros), sobre si mesmo, sua família, seus amigos, gostos, preferências e rotinas, sua comunidade e seu contexto escolar.", "o": "Produção de textos escritos, em formatos diversos de baixa complexidade discursiva (cartazes, chats, blogs, agendas, fotolegendas) considerando a temática proposta para a construção do repertório lexical, com a mediação do professor."}, {"a": "6", "t": "1", "c": "EF06LI16", "e": "Eixo conhecimentos linguísticos", "h": "Construir repertório relativo às expressões usadas para o convívio social e o uso da língua inglesa em sala de aula.", "o": "Construção de repertório lexical"}, {"a": "6", "t": "1", "c": "EF06LI17/ES", "e": "Eixo conhecimentos linguísticos", "h": "Construir repertório lexical relativo a temas familiares (escola, família, rotina diária, atividades de lazer, esportes, comunidade e local de origem).", "o": "Construção de repertório lexical"}, {"a": "6", "t": "1", "c": "EF06LI18/ES", "e": "Eixo conhecimentos linguísticos", "h": "Reconhecer semelhanças e diferenças na pronúncia de palavras da língua inglesa e da língua materna e/ou outras línguas conhecidas pertinentes à sua realidade.", "o": "Pronúncia"}, {"a": "6", "t": "1", "c": "EF06LI24/ES", "e": "Eixo Dimensão Intercultural", "h": "Investigar o alcance da língua inglesa no mundo: como língua materna e/ou oficial (primeira ou segunda língua), comparando‐o com o da língua materna (considerando as línguas indígenas, quilombolas, pomerana, Libras, entre outras).", "o": "Países que têm a língua inglesa como língua materna e/ou oficial."}, {"a": "6", "t": "1", "c": "EF06LI25/ES", "e": "Eixo Dimensão Intercultural", "h": "Identificar a presença da língua inglesa na sociedade brasileira/comunidade (palavras, expressões, suportes e esferas de circulação e consumo) e seu significado, reconhecendo os diversos usos dentro da comunidade onde a escola está inserida.", "o": "Presença da língua inglesa no cotidiano."}, {"a": "6", "t": "1", "c": "EF06LI26/ES", "e": "Eixo Dimensão Intercultural", "h": "Avaliar, problematizando elementos/produtos culturais de países de língua inglesa absorvidos pela sociedade brasileira/comunidade comparando‐os com a produção local.", "o": "Processos de criação"}, {"a": "6", "t": "2", "c": "EF06LI03", "e": "Eixo Oralidade", "h": "Solicitar esclarecimentos em língua inglesa sobre o que não entendeu e o significado de palavras ou expressões desconhecidas.", "o": "Interações discursivas em sala de aula (Uso de comandos e solicitações pertinentes a sala de aula)."}, {"a": "6", "t": "2", "c": "EF06LI04/ES", "e": "Eixo Oralidade", "h": "Reconhecer em textos orais, com o apoio de palavras cognatas e pistas do contexto discursivo, o assunto e as informações principais em textos orais sobre temas como: família, comunidade, escola e amigos.", "o": "Práticas de Compreensão de textos orais: a partir do uso de palavras cognatas e pistas do contexto discursivo."}, {"a": "6", "t": "2", "c": "EF06LI10", "e": "Eixo Leitura", "h": "Conhecer a organização de um dicionário bilíngue (impresso e/ou on-line) para construir repertório lexical.", "o": "Construção de repertório lexical e autonomia leitora."}, {"a": "6", "t": "2", "c": "EF06LI11", "e": "Eixo Leitura", "h": "Explorar ambientes virtuais e/ou aplicativos para construir repertório lexical na língua inglesa.", "o": "Construção de repertório lexical e autonomia leitora."}, {"a": "6", "t": "2", "c": "EF06LI14/ES", "e": "Eixo Escrita", "h": "Organizar ideias, selecionando‐as em função da estrutura e do objetivo do texto, considerando o gênero textual que será produzido.", "o": "Planejamento do texto: organização de ideias"}, {"a": "6", "t": "2", "c": "EF06LI15", "e": "Eixo Escrita", "h": "Produzir textos escritos em língua inglesa (histórias em quadrinhos, cartazes, chats, blogs, agendas, fotolegendas, entre outros), sobre si mesmo, sua família, seus amigos, gostos, preferências e rotinas, sua comunidade e seu contexto escolar.", "o": "Produção de textos escritos, em formatos diversos de baixa complexidade discursiva (cartazes, chats, blogs, agendas, fotolegendas) considerando a temática proposta para a construção do repertório lexical, com a mediação do professor."}, {"a": "6", "t": "2", "c": "EF06LI19", "e": "Eixo conhecimentos linguísticos", "h": "Utilizar o presente do indicativo para identificar pessoas (verbo to be) e descrever rotinas diárias.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso do presente simples e contínuo em suas formas afirmativa, negativa e interrogativa."}, {"a": "6", "t": "2", "c": "EF06LI20", "e": "Eixo conhecimentos linguísticos", "h": "Utilizar o presente contínuo para descrever ações em progresso.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso do presente simples e contínuo em suas formas afirmativa, negativa e interrogativa."}, {"a": "6", "t": "2", "c": "EF06LI25/ES", "e": "Eixo Dimensão Intercultural", "h": "Identificar a presença da língua inglesa na sociedade brasileira/comunidade (palavras, expressões, suportes e esferas de circulação e consumo) e seu significado, reconhecendo os diversos usos dentro da comunidade onde a escola está inserida.", "o": "Presença da língua inglesa no cotidiano."}, {"a": "6", "t": "2", "c": "EF06LI26/ES", "e": "Eixo Dimensão Intercultural", "h": "Avaliar, problematizando elementos/produtos culturais de países de língua inglesa absorvidos pela sociedade brasileira/comunidade comparando‐os com a produção local.", "o": "Processos de criação"}, {"a": "6", "t": "3", "c": "EF06LI05/ES", "e": "Eixo Oralidade", "h": "Aplicar os conhecimentos da língua inglesa para falar de si e de outras pessoas, do seu local de origem e da sua comunidade, explicitando informações pessoais e características relacionadas a gostos, preferências e rotinas.", "o": "Produção de textos orais, com a mediação do professor"}, {"a": "6", "t": "3", "c": "EF06LI06/ES", "e": "Eixo Oralidade", "h": "Planejar apresentação sobre a família, a comunidade e a escola, compartilhando-a oralmente com o grupo, valorizando aspectos importantes sobre sua localidade, considerando características regionais.", "o": "Produção de textos orais, com a mediação do professor."}, {"a": "6", "t": "3", "c": "EF06LI12/ES", "e": "Eixo Leitura", "h": "Interessar-se pelo texto lido, compartilhando, de forma oral ou por meio de outras linguagens, suas ideias sobre o que o texto informa/comunica.", "o": "Partilha de leitura, com mediação do professor."}, {"a": "6", "t": "3", "c": "EF06LI14/ES", "e": "Eixo Escrita", "h": "Organizar ideias, selecionando‐as em função da estrutura e do objetivo do texto, considerando o gênero textual que será produzido.", "o": "Planejamento do texto: organização de ideias."}, {"a": "6", "t": "3", "c": "EF06LI15", "e": "Eixo Escrita", "h": "Produzir textos escritos em língua inglesa (histórias em quadrinhos, cartazes, chats, blogs, agendas, fotolegendas, entre outros), sobre si mesmo, sua família, seus amigos, gostos, preferências e rotinas, sua comunidade e seu contexto escolar.", "o": "Produção de textos escritos, em formatos diversos de baixa complexidade discursiva (cartazes, chats, blogs, agendas, fotolegendas) considerando a temática proposta para a construção do repertório lexical, com a mediação do professor"}, {"a": "6", "t": "3", "c": "EF06LI21/ES", "e": "Eixo conhecimentos linguísticos", "h": "Reconhecer o uso do imperativo em enunciados de atividades, comandos e instruções em diversos contextos e espaços.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso do imperativo."}, {"a": "6", "t": "3", "c": "EF06LI22", "e": "Eixo conhecimentos linguísticos", "h": "Descrever relações por meio do uso de apóstrofo (’) + s.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso do caso genitivo (‘s)"}, {"a": "6", "t": "3", "c": "EF06LI23", "e": "Eixo conhecimentos linguísticos", "h": "Empregar, de forma inteligível, os adjetivos possessivos.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso dos adjetivos possessivos."}, {"a": "6", "t": "3", "c": "EF06LI25/ES", "e": "Eixo Dimensão Intercultural", "h": "Identificar a presença da língua inglesa na sociedade brasileira/comunidade (palavras, expressões, suportes e esferas de circulação e consumo) e seu significado, reconhecendo os diversos usos dentro da comunidade onde a escola está inserida.", "o": "Presença da língua inglesa no cotidiano."}, {"a": "6", "t": "3", "c": "EF06LI26/ES", "e": "Eixo Dimensão Intercultural", "h": "Avaliar, problematizando elementos/produtos culturais de países de língua inglesa absorvidos pela sociedade brasileira/comunidade comparando‐os com a produção local.", "o": "Processos de criação"}, {"a": "7", "t": "1", "c": "EF07LI01/ES", "e": "Eixo Oralidade", "h": "Interagir em situações de intercâmbio oral para realizar as atividades em sala de aula, de forma respeitosa e colaborativa, trocando ideias e engajando‐ se em brincadeiras e jogos, considerando o outro, seu tempo e modo de fala, garantindo a todos a produção do “seu inglês”.", "o": "Práticas de compreensão e produção oral e escrita que promovam convivência e colaboração em sala de aula."}, {"a": "7", "t": "1", "c": "EF07LI02/ES", "e": "Eixo Oralidade", "h": "Entrevistar os colegas para conhecer suas histórias de vida, de modo a reconhecer a diversidade incutida no ambiente escolar.", "o": "Práticas discursivas investigativas orais com o tema: sobre o outro, seu local, sua família, a escola, a indústria cultural.."}, {"a": "7", "t": "1", "c": "EF07LI06", "e": "Eixo Leitura", "h": "Antecipar o sentido global de textos em língua inglesa por inferências, com base em leitura rápida, observando títulos, primeiras e últimas frases de parágrafos e palavras-chave repetidas.", "o": "Práticas de compreensão geral e específica: leitura rápida (skimming, scanning), a partir de textos que tenham como temas: pessoas e/ou fatos marcantes da comunidade e do mundo; histórias pessoais e coletiva; além de temas que façam referência ao que está proposto no eixo dimensão cultural."}, {"a": "7", "t": "1", "c": "EF07LI07", "e": "Eixo Leitura", "h": "Identificar a(s) informação(ões)-chave de partes de um texto em língua inglesa (parágrafos).", "o": "Práticas de compreensão geral e específica: leitura rápida (skimming, scanning), a partir de textos que tenham como temas: pessoas e/ou fatos marcantes da comunidade e do mundo; histórias pessoais e coletiva; além de temas que façam referência ao que está proposto no eixo dimensão cultural."}, {"a": "7", "t": "1", "c": "EF07LI08", "e": "Eixo Leitura", "h": "Relacionar as partes de um texto (parágrafos) para construir seu sentido global.", "o": "Construção do sentido global do texto."}, {"a": "7", "t": "1", "c": "EF07LI09", "e": "Eixo Leitura", "h": "Selecionar, em um texto, a informação desejada como objetivo de leitura.", "o": "Objetivos de leitura."}, {"a": "7", "t": "1", "c": "EF07LI12", "e": "Eixo Escrita", "h": "Planejar a escrita de textos em função do contexto (público, finalidade, layout e suporte).", "o": "Pré-escrita: planejamento de produção escrita, com mediação do professor, considerando as temáticas propostas no Eixo Oralidade."}, {"a": "7", "t": "1", "c": "EF07LI13/ES", "e": "Eixo Escrita", "h": "Organizar texto em unidades de sentido, dividindo‐o em parágrafos ou tópicos e subtópicos, explorando as possibilidades de organização gráfica, de suporte e de formato do texto, considerando o gênero textual a ser produzido e suas funcionalidades, o contexto de produção e o conhecimento prévio.", "o": "Escrita: organização em parágrafos ou tópicos, com mediação do professor."}, {"a": "7", "t": "1", "c": "EF07LI14/ES", "e": "Eixo Escrita", "h": "Produzir textos diversos sobre fatos, acontecimentos e personalidades do passado (linha do tempo/timelines, biografias, verbetes de enciclopédias, blogs, entre outros), valorizando fatos, as personalidades e os acontecimentos locais.", "o": "Produção de textos escritos, em formatos diversos, com a mediação do professor."}, {"a": "7", "t": "1", "c": "EF07LI15", "e": "Eixo conhecimentos linguísticos", "h": "Construir repertório lexical relativo a verbos regulares e irregulares (formas no passado), preposições de tempo (in, on, at) e conectores (and, but, because, then, so, before,after, entre outros).", "o": "Construção de repertório lexical a partir do uso da língua, tendo como base a compreensão e a produção oral e escrita."}, {"a": "7", "t": "1", "c": "EF07LI16", "e": "Eixo conhecimentos linguísticos", "h": "Reconhecer a pronúncia de verbos regulares no passado (-ed).", "o": "Percepção de diferentes formas de pronúncia, a partir da língua em uso."}, {"a": "7", "t": "1", "c": "EF07LI21/ES", "e": "Eixo Dimensão Intercultural", "h": "Analisar o alcance da língua inglesa e os seus contextos de uso no mundo globalizado, bem como os impactos no cotidiano da comunidade.", "o": "A língua inglesa como língua global na sociedade contemporânea."}, {"a": "7", "t": "1", "c": "EF07LI22/ES", "e": "Eixo Dimensão Intercultural", "h": "Explorar modos de falar em língua inglesa, refutando preconceitos, reconhecendo a variação linguística como fenômeno natural das línguas e a diversidade de falantes de língua inglesa em seus diversos contextos de uso.", "o": "A língua inglesa como língua global na sociedade contemporânea."}, {"a": "7", "t": "1", "c": "EF07LI23/ES", "e": "Eixo Dimensão Intercultural", "h": "Reconhecer a variação linguística como manifestação de formas de pensar e expressar o mundo comparando também a variação linguística regional e os diferentes sotaques em Língua Portuguesa.", "o": "Variação linguística."}, {"a": "7", "t": "2", "c": "EF07LI03", "e": "Eixo Oralidade", "h": "Mobilizar conhecimentos prévios para compreender texto oral.", "o": "Práticas de compreensão de textos orais: conhecimentos prévios, considerando o que se sabe de si mesmo, do outro e da língua."}, {"a": "7", "t": "2", "c": "EF07LI04/ES", "e": "Eixo Oralidade", "h": "Identificar o contexto, a finalidade, o assunto e os interlocutores em textos orais presentes no cinema, na internet, na televisão, na sala de aula, no ambiente escolar, na comunidade e nas produções culturais", "o": "Práticas de compreensão de textos orais de cunho descritivo ou narrativo sobre o outro, seu local, sua família, a escola, a indústria cultural."}, {"a": "7", "t": "2", "c": "EF07LI10", "e": "Eixo Leitura", "h": "Escolher, em ambientes virtuais, textos em língua inglesa, de fontes confiáveis, para estudos/pesquisas escolares.", "o": "Leitura de textos digitais para estudo, considerando as mesmas temáticas do Eixo oralidade."}, {"a": "7", "t": "2", "c": "EF07LI13/ES", "e": "Eixo Escrita", "h": "Organizar texto em unidades de sentido, dividindo‐o em parágrafos ou tópicos e subtópicos, explorando as possibilidades de organização gráfica, de suporte e de formato do texto, considerando o gênero textual a ser produzido e suas funcionalidades, o contexto de produção e o conhecimento prévio.", "o": "Escrita: organização em parágrafos ou tópicos, com mediação do professor."}, {"a": "7", "t": "2", "c": "EF07LI14/ES", "e": "Eixo Escrita", "h": "Produzir textos diversos sobre fatos, acontecimentos e personalidades do passado (linha do tempo/timelines, biografias, verbetes de enciclopédias, blogs, entre outros), valorizando fatos, as personalidades e os acontecimentos locais.", "o": "Produção de textos escritos, em formatos diversos, com a mediação do professor."}, {"a": "7", "t": "2", "c": "EF07LI17/ES", "e": "Eixo conhecimentos linguísticos", "h": "Explorar o caráter polissêmico de palavras a fim de aguçar a habilidade de inferir o significado a partir do contexto8.", "o": "Polissemia"}, {"a": "7", "t": "2", "c": "EF07LI18/ES", "e": "Eixo conhecimentos linguísticos", "h": "Utilizar o passado simples e o passado contínuo para produzir textos orais e escritos, mostrando relações de sequência dos fatos históricos locais, nos contextos familiares, mudanças culturais bem como as relações de causalidade, contrastando com as rotinas da contemporaneidade acerca de sua família, comunidade e escola.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso do passado simples e contínuo (formas afirmativa, negativa e interrogativa)."}, {"a": "7", "t": "2", "c": "EF07LI22/ES", "e": "Eixo Dimensão Intercultural", "h": "Explorar modos de falar em língua inglesa, refutando preconceitos, reconhecendo a variação linguística como fenômeno natural das línguas e a diversidade de falantes de língua inglesa em seus diversos contextos de uso.", "o": "A língua inglesa como língua global na sociedade contemporânea."}, {"a": "7", "t": "2", "c": "EF07LI23/ES", "e": "Eixo Dimensão Intercultural", "h": "Reconhecer a variação linguística como manifestação de formas de pensar e expressar o mundo comparando também a variação linguística regional e os diferentes sotaques em Língua Portuguesa.", "o": "Variação linguística"}, {"a": "7", "t": "3", "c": "EF07LI05/ES", "e": "Eixo Oralidade", "h": "Compor, em língua inglesa, narrativas orais sobre fatos, acontecimentos e personalidades marcantes do passado, sobre si mesmo, as personalidades locais, familiares e suas contribuições para a comunidade e para o mundo.", "o": "Produção de textos orais, com a mediação do professor, sobre o outro, seu local, sua família, a escola, a indústria cultural."}, {"a": "7", "t": "3", "c": "EF07LI11/ES", "e": "Eixo Leitura", "h": "Participar de troca de opiniões e informações sobre textos, lidos na sala de aula ou em outros ambientes, por meio de práticas discursivas orais, escritas ou de outra linguagem.", "o": "Partilha da leitura utilizando-se de práticas de compreensão escrita e produção oral, escrita ou de outra linguagem."}, {"a": "7", "t": "3", "c": "EF07LI13/ES", "e": "Eixo Escrita", "h": "Organizar texto em unidades de sentido, dividindo‐o em parágrafos ou tópicos e subtópicos, explorando as possibilidades de organização gráfica, de suporte e de formato do texto, considerando o gênero textual a ser produzido e suas funcionalidades, o contexto de produção e o conhecimento prévio.", "o": "Escrita: organização em parágrafos ou tópicos, com mediação do professor."}, {"a": "7", "t": "3", "c": "EF07LI14/ES", "e": "Eixo Escrita", "h": "Produzir textos diversos sobre fatos, acontecimentos e personalidades do passado (linha do tempo/timelines, biografias, verbetes de enciclopédias, blogs, entre outros), valorizando fatos, as personalidades e os acontecimentos locais.", "o": "Produção de textos escritos, em formatos diversos, com a mediação do professor."}, {"a": "7", "t": "3", "c": "EF07LI19/ES", "e": "Eixo conhecimentos linguísticos", "h": "Utilizar de forma contextualizada pronomes pessoais do caso reto e do caso oblíquo a fim de evitar repetições desnecessárias na fala e na escrita.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso de pronomes do caso reto e do caso oblíquo."}, {"a": "7", "t": "3", "c": "EF07LI20/ES", "e": "Eixo conhecimentos linguísticos", "h": "Empregar, de forma inteligível, o verbo modal can para descrever habilidades (no presente e no passado), a fim de retratar, inclusive, habilidades físicas de pessoas da família, da escola e da comunidade, de modo a perceber a mobilidade e acessibilidade de pessoas com deficiência.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso do verbo modal can (presente e passado)."}, {"a": "7", "t": "3", "c": "EF07LI22/ES", "e": "Eixo Dimensão Intercultural", "h": "Explorar modos de falar em língua inglesa, refutando preconceitos, reconhecendo a variação linguística como fenômeno natural das línguas e a diversidade de falantes de língua inglesa em seus diversos contextos de uso.", "o": "A língua inglesa como língua global na sociedade contemporânea."}, {"a": "7", "t": "3", "c": "EF07LI23/ES", "e": "Eixo Dimensão Intercultural", "h": "Reconhecer a variação linguística como manifestação de formas de pensar e expressar o mundo comparando também a variação linguística regional e os diferentes sotaques em Língua Portuguesa.", "o": "Variação linguística"}, {"a": "8", "t": "1", "c": "EF08LI01/ES", "e": "Eixo Oralidade", "h": "Fazer uso da língua inglesa para resolver mal entendidos no contexto escolar e para além dele, emitir opiniões e esclarecer informações por meio de paráfrases ou justificativas.", "o": "Elementos da linguagem."}, {"a": "8", "t": "1", "c": "EF08LI02", "e": "Eixo Oralidade", "h": "Explorar o uso de recursos linguísticos (frases incompletas, hesitações, entre outros) e paralinguísticos (gestos, expressões faciais, entre outros) em situações de interação oral.", "o": "Usos de recursos linguísticos e paralinguísticos no intercâmbio oral."}, {"a": "8", "t": "1", "c": "EF08LI05", "e": "Eixo Leitura", "h": "Inferir informações e relações que não aparecem de modo explícito no texto para construção de sentidos.", "o": "Práticas de compreensão e produção escrita que promovam a construção de sentidos por meio de inferências e reconhecimento de implícitos."}, {"a": "8", "t": "1", "c": "EF08LI06/ES", "e": "Eixo Leitura", "h": "Apreciar textos narrativos em língua inglesa (contos, romances, entre outros, em versão original ou simplificada), como forma de valorizar o patrimônio cultural produzido em língua inglesa, e comparar com contos/lendas regionais.", "o": "Práticas de compreensão e produção escrita que possibilitem a leitura de textos artístico‐literários, incluindo textos de formatos eletrônicos."}, {"a": "8", "t": "1", "c": "EF08LI09/ES", "e": "Eixo Escrita", "h": "Avaliar a própria produção escrita e a dos colegas, com base no contexto de comunicação (finalidade e adequação ao público, conteúdo a ser comunicado, organização textual, legibilidade, estrutura de frases), sendo empático ao apresentar os apontamentos sobre a produção dos demais.", "o": "Práticas de compreensão e produção escrita que promovam a revisão de textos com a mediação do professor."}, {"a": "8", "t": "1", "c": "EF08LI10/ES", "e": "Eixo Escrita", "h": "Reconstruir o texto, com cortes, acréscimos, reformulações e correções, para aprimoramento, edição e publicação final, considerando os apontamentos dos colegas e do professor estabelecendo uma escuta ativa sobre o que o outro propõe.", "o": "Práticas de compreensão e produção escrita que promovam a revisão de textos com a mediação do professor."}, {"a": "8", "t": "1", "c": "EF08LI11", "e": "Eixo Escrita", "h": "Produzir textos (comentários em fóruns, relatos pessoais, mensagens instantâneas, tweets, reportagens, histórias de ficção, blogs, entre outros), com o uso de estratégias de escrita (planejamento, produção de rascunho, revisão e edição final), apontando sonhos e projetos para o futuro (pessoal, da família, da comunidade ou do planeta).", "o": "Práticas de compreensão e produção escrita com a mediação do professor e colegas."}, {"a": "8", "t": "1", "c": "EF08LI12/ES", "e": "Eixo conhecimentos linguísticos", "h": "Construir repertório lexical relativo a planos, provisões e expectativas para o futuro de acordo com seu contexto pessoal, local e o mundial tomando como base diferentes perspectivas (própria, escola, família,", "o": "Construção de repertório lexical a partir do uso da língua, tendo como base a compreensão e a produção oral e escrita."}, {"a": "8", "t": "1", "c": "EF08LI13/ES", "e": "Eixo conhecimentos linguísticos", "h": "Reconhecer sufixos e prefixos comuns utilizados na formação de palavras em língua inglesa comparando com os presentes na língua portuguesa.", "o": "Práticas de compreensão e produção oral e escrita com formação de palavras: prefixos e sufixos no contexto de uso da língua inglesa e língua portuguesa."}, {"a": "8", "t": "1", "c": "EF08LI14", "e": "Eixo conhecimentos linguísticos", "h": "Utilizar formas verbais do futuro para descrever planos e expectativas e fazer previsões.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso de verbos para indicar futuro."}, {"a": "8", "t": "1", "c": "EF08LI18/ES", "e": "Eixo Dimensão Intercultural", "h": "Construir repertório cultural por meio do contato com manifestações artístico-culturais vinculadas à língua inglesa e agregá-las às manifestações locais (artes plásticas e visuais, literatura, música, cinema, dança, festividades, entre outros), valorizando a diversidade entre culturas;", "o": "Construção de significado artístico/cultural"}, {"a": "8", "t": "1", "c": "EF08LI19/ES", "e": "Eixo Dimensão Intercultural", "h": "Investigar de que forma expressões, gestos e comportamentos são interpretados em função de aspectos culturais.", "o": "Impactos de aspectos culturais na comunicação."}, {"a": "8", "t": "1", "c": "EF08LI20/ES", "e": "Eixo Dimensão Intercultural", "h": "Examinar fatores que podem impedir o entendimento entre pessoas de culturas diferentes que falam a língua inglesa partindo das dificuldades similares entre falantes da Língua Portuguesa10.", "o": "Impactos de aspectos culturais na comunicação."}, {"a": "8", "t": "2", "c": "EF08LI03/ES", "e": "Eixo Oralidade", "h": "Construir o sentido global de textos / produções orais, relacionando suas partes, o assunto principal e informações relevantes advindas de seu/sua professor(a), dos colegas ou de outros meios, incluindo o digital.", "o": "Práticas de compreensão de textos orais, multimodais (informativo/jornalístico) advindos do ambiente escolar ou de outros espaços, incluindo os digitais."}, {"a": "8", "t": "2", "c": "EF08LI07", "e": "Eixo Leitura", "h": "Explorar ambientes virtuais e/ou aplicativos para acessar e usufruir do patrimônio artístico literário em língua inglesa.", "o": "Práticas de compreensão e produção escrita que possibilitem a leitura de textos artístico-literários, incluindo textos de formatos eletrônicos."}, {"a": "8", "t": "2", "c": "EF08LI11", "e": "Eixo Escrita", "h": "Produzir textos (comentários em fóruns, relatos pessoais, mensagens instantâneas, tweets, reportagens, histórias de ficção, blogs, entre outros), com o uso de estratégias de escrita (planejamento, produção de rascunho, revisão e edição final), apontando sonhos e projetos para o futuro (pessoal, da família, da comunidade ou do planeta).", "o": "Práticas de compreensão e produção escrita com a mediação do professor e colegas."}, {"a": "8", "t": "2", "c": "EF08LI15/ES", "e": "Eixo conhecimentos linguísticos", "h": "Utilizar, de modo inteligível, as formas comparativas e superlativas de adjetivos para comparar qualidades e quantidades referentes a temas em geral sobretudo comparando as realidades do entorno no presente com previsões sobre a mesma no futuro.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso de comparativos e superlativos."}, {"a": "8", "t": "2", "c": "EF08LI16/ES", "e": "Eixo conhecimentos linguísticos", "h": "Utilizar, de modo inteligível, os quantificadores a partir de existências e possíveis características futuras da localidade segundo previsões/opiniões.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso dos quantificadores."}, {"a": "8", "t": "2", "c": "EF08LI19/ES", "e": "Eixo Dimensão Intercultural", "h": "Investigar de que forma expressões, gestos e comportamentos são interpretados em função de aspectos culturais.", "o": "Impactos de aspectos culturais na comunicação."}, {"a": "8", "t": "2", "c": "EF08LI20/ES", "e": "Eixo Dimensão Intercultural", "h": "Examinar fatores que podem impedir o entendimento entre pessoas de culturas diferentes que falam a língua inglesa partindo das dificuldades similares entre falantes da Língua Portuguesa10.", "o": "Impactos de aspectos culturais na comunicação."}, {"a": "8", "t": "3", "c": "EF08LI04/ES", "e": "Eixo Oralidade", "h": "Utilizar recursos e repertório linguísticos apropriados para informar/comunicar/falar do futuro: planos, previsões, possibilidades e probabilidades em geral e principalmente aspirações no âmbito profissional, família e demais concepções para formação de ser humano integral.", "o": "Práticas de produção oral com autonomia"}, {"a": "8", "t": "3", "c": "EF08LI08", "e": "Eixo Leitura", "h": "Analisar, criticamente, o conteúdo de textos, comparando diferentes perspectivas apresentadas sobre o mesmo assunto.", "o": "Práticas de compreensão e produção escrita que promovam a reflexão pós-leitura."}, {"a": "8", "t": "3", "c": "EF08LI11", "e": "Eixo Escrita", "h": "Produzir textos (comentários em fóruns, relatos pessoais, mensagens instantâneas, tweets, reportagens, histórias de ficção, blogs, entre outros), com o uso de estratégias de escrita (planejamento, produção de rascunho, revisão e edição final), apontando sonhos e projetos para o futuro (pessoal, da família, da comunidade ou do planeta).", "o": "Práticas de compreensão e produção escrita com a mediação do professor e colegas."}, {"a": "8", "t": "3", "c": "EF08LI17/ES", "e": "Eixo conhecimentos linguísticos", "h": "Empregar, de modo inteligível, os pronomes relativos para construir períodos compostos por subordinação especialmente sobre personalidades, patrimônios ou a própria localidade de modo a construir um texto informativo, turístico e cultural sobre a região.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso de pronomes relativos."}, {"a": "8", "t": "3", "c": "EF08LI19/ES", "e": "Eixo Dimensão Intercultural", "h": "Investigar de que forma expressões, gestos e comportamentos são interpretados em função de aspectos culturais.", "o": "Impactos de aspectos culturais na comunicação."}, {"a": "8", "t": "3", "c": "EF08LI20/ES", "e": "Eixo Dimensão Intercultural", "h": "Examinar fatores que podem impedir o entendimento entre pessoas de culturas diferentes que falam a língua inglesa partindo das dificuldades similares entre falantes da Língua Portuguesa10.", "o": "Impactos de aspectos culturais na comunicação."}, {"a": "9", "t": "1", "c": "EF09LI01/ES", "e": "Eixo Oralidade", "h": "Fazer uso da língua inglesa para expor pontos de vista, argumentos e contra‐argumentos, considerando o contexto e os recursos linguísticos voltados para a eficácia e a comunicação tendo como referência debates, frases provenientes da mídia ou demais frases de efeito de diversos grupos sociais e políticos.", "o": "Práticas de compreensão e produção oral e escrita que utilizem a persuasão como estratégia de comunicação."}, {"a": "9", "t": "1", "c": "EF09LI02", "e": "Eixo Oralidade", "h": "Compilar as ideias-chave de textos por meio de tomada de notas.", "o": "Práticas de compreensão de textos orais, multimodais advindos do ambiente escolar ou de outros espaços, incluindo os digitais."}, {"a": "9", "t": "1", "c": "EF09LI05", "e": "Eixo Leitura", "h": "Identificar no entorno (escola, bairro, comércios), televisão e internet os recursos de persuasão (escolha e jogos de palavra, uso de cores e imagens, tamanho de letras), a utilização deste recurso nos textos publicitários e de propaganda, como elementos de convencimento.", "o": "Práticas de compreensão e produção escrita que utilizem a persuasão como estratégia de comunicação."}, {"a": "9", "t": "1", "c": "EF09LI10/ES", "e": "Eixo escrita", "h": "Propor potenciais argumentos para expor e defender ponto de vista em texto escrito, refletindo sobre o tema proposto e pesquisando dados, evidências e exemplos no entorno sobre personalidades em geral para sustentar os argumentos, organizando-os em sequência lógica.", "o": "Práticas de compreensão e produção escrita que utilizem a argumentação como estratégia de comunicação."}, {"a": "9", "t": "1", "c": "EF09LI11", "e": "Eixo Escrita", "h": "Utilizar recursos verbais e não verbais para construção da persuasão em textos da esfera publicitária, de forma adequada ao contexto de circulação (produção e compreensão).", "o": "Práticas de compreensão e produção escrita que utilizem a persuasão como estratégia de comunicação."}, {"a": "9", "t": "1", "c": "EF09LI12", "e": "Eixo Escrita", "h": "Produzir textos (infográficos, fóruns de discussão on‐line, fotorreportagens, campanhas publicitárias, memes, entre outros) sobre temas de interesse coletivo local ou global, que revelem posicionamento crítico.", "o": "Práticas de compreensão e produção escrita com a mediação do professor e colegas."}, {"a": "9", "t": "1", "c": "EF09LI13/ES", "e": "Eixo Conhecimento Linguístico", "h": "Reconhecer, novos gêneros digitais (blogs, mensagens instantâneas, tweets, entre outros), novas formas de escrita (abreviação de palavras, palavras com combinação de letras e números pictogramas, símbolos gráficos, entre outros) na constituição das mensagens analisando os contextos adequados para sua utilização no contexto escolar e no cotidiano.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso da linguagem em meio digital “Internetês”."}, {"a": "9", "t": "1", "c": "EF09LI14", "e": "Eixo Conhecimento Linguístico", "h": "Utilizar conectores indicadores de adição, condição, oposição, contraste, conclusão e síntese como auxiliares na construção da argumentação e intencionalidade discursiva.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso de conectores (linking words)."}, {"a": "9", "t": "1", "c": "EF09LI16/ES", "e": "Eixo Dimensão Intercultural", "h": "Empregar, de modo inteligível, os verbos should, must, have to, may e might para indicar recomendação, necessidade ou obrigação e probabilidade.", "o": "Práticas de compreensão e produção oral e escrita que utilizem verbos modais: should, must, have to, may e might."}, {"a": "9", "t": "2", "c": "EF09LI03/ES", "e": "Eixo Oralidade", "h": "Analisar posicionamentos defendidos e refutados em textos orais reproduzidos em materiais sonoros ou pronunciados pelo professor ou pelos colegas sobre temas de interesse social e coletivo.", "o": "Práticas de compreensão de textos orais, multimodais advindos do ambiente escolar ou de outros espaços, incluindo os digitais."}, {"a": "9", "t": "2", "c": "EF09LI06/ES", "e": "Eixo Leitura", "h": "Distinguir fatos de opiniões em textos argumentativos da esfera jornalística em fóruns ou blogs sobre temas contemporâneos locais ou mundiais.", "o": "Práticas de compreensão e produção escrita que utilizem a argumentação como estratégia de comunicação."}, {"a": "9", "t": "2", "c": "EF09LI07/ES", "e": "Eixo Leitura", "h": "Identificar argumentos principais e as evidências/ exemplos que os sustentam, em charges, anúncios publicitários, notas jornalísticas ou informativas produzidas em inglês e em língua portuguesa.", "o": "Práticas de compreensão e produção escrita que utilizem a argumentação como estratégia de comunicação."}, {"a": "9", "t": "2", "c": "EF09LI12", "e": "Eixo Escrita", "h": "Produzir textos (infográficos, fóruns de discussão on‐line, fotorreportagens, campanhas publicitárias, memes, entre outros) sobre temas de interesse coletivo local ou global, que revelem posicionamento crítico.", "o": "Práticas de compreensão e produção escrita com a mediação do professor e colegas."}, {"a": "9", "t": "2", "c": "EF09LI14", "e": "Eixo Conhecimento Linguístico", "h": "Utilizar conectores indicadores de adição, condição, oposição, contraste, conclusão e síntese como auxiliares na construção da argumentação e intencionalidade discursiva.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso de conectores (linking words)."}, {"a": "9", "t": "2", "c": "EF09LI15/ES", "e": "Eixo Conhecimento Linguístico", "h": "Empregar, de modo inteligível, as formas Verbais em orações condicionais dos tipos 1 e 2 (If-clauses) a partir de temas propostos, sobretudo ações e consequências de se obter informações em fontes não-confiáveis.", "o": "Práticas de compreensão e produção oral e escrita que utilizem as orações condicionadas (tipos 1 e 2)."}, {"a": "9", "t": "2", "c": "EF09LI17/ES", "e": "Eixo Dimensão Intercultural", "h": "Debater sobre a expansão da língua inglesa pelo mundo, em função do processo de colonização nas Américas, África, Ásia e Oceania e seu impacto principalmente no nosso país ou mesmo na própria região.", "o": "Contexto histórico da expansão da língua inglesa"}, {"a": "9", "t": "3", "c": "EF09LI04/ES", "e": "Eixo Oralidade", "h": "Expor resultados de pesquisa ou estudo sobre temas de interesse pessoal ou coletivo com o apoio de recursos, tais como notas, gráficos, tabelas, entre outros, adequando as estratégias de construção do texto oral aos objetivos de comunicação e ao contexto.", "o": "Práticas de compreensão e produção de textos orais com autonomia."}, {"a": "9", "t": "3", "c": "EF09LI08/ES", "e": "Eixo Leitura", "h": "Explorar ambientes virtuais de informação e socialização, analisando a qualidade e a validade das informações veiculadas analisando se as mesmas violam os direitos humanos.", "o": "Práticas de compreensão e produção oral e escrita que utilizem informações provenientes de ambientes virtuais."}, {"a": "9", "t": "3", "c": "EF09LI09/ES", "e": "Eixo Leitura", "h": "Compartilhar, com os colegas, a leitura dos textos escritos pelo grupo, valorizando os diferentes pontos de vista defendidos, como ética e respeito além de valores e atitudes que reforçam a garantia dos diretos humanos.", "o": "Reflexão pós-leitura"}, {"a": "9", "t": "3", "c": "EF09LI12", "e": "Eixo Escrita", "h": "Produzir textos (infográficos, fóruns de discussão on‐line, fotorreportagens, campanhas publicitárias, memes, entre outros) sobre temas de interesse coletivo local ou global, que revelem posicionamento crítico.", "o": "Práticas de compreensão e produção escrita com a mediação do professor e colegas."}, {"a": "9", "t": "3", "c": "EF09LI14", "e": "Eixo Conhecimento Linguístico", "h": "Utilizar conectores indicadores de adição, condição, oposição, contraste, conclusão e síntese como auxiliares na construção da argumentação e intencionalidade discursiva.", "o": "Práticas de compreensão e produção oral e escrita que promovam o uso de conectores (linking words)."}, {"a": "9", "t": "3", "c": "EF09LI15/ES", "e": "Eixo Conhecimento Linguístico", "h": "Empregar, de modo inteligível, as formas Verbais em orações condicionais dos tipos 1 e 2 (If-clauses) a partir de temas propostos, sobretudo ações e consequências de se obter informações em fontes não-confiáveis.", "o": "Práticas de compreensão e produção oral e escrita que utilizem as orações condicionadas (tipos 1 e 2)."}, {"a": "9", "t": "3", "c": "EF09LI18/ES", "e": "Eixo Dimensão Intercultural", "h": "Analisar a importância da língua inglesa para o desenvolvimento das ciências (produção, divulgação e discussão de novos conhecimentos), da economia e da política, sua exigência no mundo do trabalho na região/localidade e no cenário mundial.", "o": "O papel da língua inglesa nas esferas científicas, políticas e econômicas."}, {"a": "9", "t": "3", "c": "EF09LI19/ES", "e": "Eixo Dimensão Intercultural", "h": "Discutir a comunicação intercultural por meio da língua inglesa como mecanismo de valorização pessoal e de construção de identidades no mundo globalizado considerando as realidades pessoais por meio de relatos de amigos ou familiares que vivenciaram a experiência em outro país.", "o": "Construção de identidades do mundo globalizado."}], "Matemática": [{"a": "6", "t": "1", "c": "EF06MA01", "e": "", "h": "Comparar, ordenar, ler e escrever números naturais e números racionais cuja representação decimal é finita, fazendo uso da reta numérica.", "o": "Sistema de numeração decimal: características, leitura, escrita e comparação de números naturais e de números racionais representados na forma decimal."}, {"a": "6", "t": "1", "c": "EF06MA02/ES", "e": "", "h": "Reconhecer o sistema de numeração decimal, como o que prevaleceu no mundo ocidental, e destacar semelhanças e diferenças com outros sistemas, de modo a sistematizar suas principais características (base, valor posicional e função do zero), utilizando, inclusive, a composição e decomposição de números naturais e números racionais em sua representação decimal por meio de cédulas, moedas e/ou operações de sistemas financeiros.", "o": "História dos números. Sistema de numeração decimal: características, leitura, escrita e comparação de números naturais."}, {"a": "6", "t": "1", "c": "EF06MA03", "e": "", "h": "Resolver e elaborar problemas que envolvam cálculos (mentais ou escritos, exatos ou aproximados) com números naturais, por meio de estratégias variadas, com compreensão dos processos neles envolvidos com e sem uso de calculadora.", "o": "Operações (adição, subtração e multiplicação) com números naturais. Operação de divisão com números naturais. Divisão euclidiana. Operações (potenciação e raiz quadrada) com números naturais."}, {"a": "6", "t": "1", "c": "EF06MA04", "e": "", "h": "Construir algoritmo em linguagem natural e representá- lo por fluxograma que indique a resolução de um problema simples (por exemplo, se um número natural qualquer é par).", "o": "Fluxograma para determinar a paridade de um número natural. Programação: Linguagem de programação."}, {"a": "6", "t": "1", "c": "EF06MA05", "e": "", "h": "Classificar números naturais em primos e compostos, estabelecer relações entre números, expressas pelos termos “é múltiplo de”, “é divisor de”, “é fator de”, e estabelecer, por meio de investigações, critérios de divisibilidade por 2, 3, 4, 5, 6, 8, 9, 10, 100 e 1000.", "o": "Múltiplos e divisores de um número natural. Números primos e compostos. Estratégias de solução de problemas: Generalização."}, {"a": "6", "t": "1", "c": "EF06MA06/ES", "e": "", "h": "Resolver e elaborar problemas que envolvam as ideias de múltiplo e de divisor, incluindo a noção de máximo divisor comum ou mínimo múltiplo comum.", "o": "Múltiplos e divisores de um número natural. Números primos e compostos. Mínimo Múltiplo Comum. Máximo Divisor Comum."}, {"a": "6", "t": "1", "c": "EF06MA08", "e": "", "h": "Reconhecer que os números racionais positivos podem ser expressos nas formas fracionária e decimal, estabelecer relações entre essas representações, passando de uma representação para outra, e relacioná-los a pontos na reta numérica.", "o": "Números racionais: frações [adição e subtração]. Frações: significados [parte/ todo/quociente], equivalência, comparação, adição e subtração; cálculo da fração de um número natural; adição e subtração de frações."}, {"a": "6", "t": "1", "c": "EF06MA09", "e": "", "h": "Resolver e elaborar problemas que envolvam o cálculo da fração de uma quantidade e cujo resultado seja um número natural, com e sem uso de calculadora.", "o": "Números racionais na representação fracionária e na decimal: usos, ordenação e associação com pontos da reta numérica e operações."}, {"a": "6", "t": "1", "c": "EF06MA12", "e": "", "h": "Fazer estimativas de quantidades e aproximar números para múltiplos da potência de 10 mais próxima.", "o": "Aproximação de números para múltiplos de potências de 10."}, {"a": "6", "t": "1", "c": "EF06MA14", "e": "", "h": "Reconhecer que a relação de igualdade matemática não se altera ao adicionar, subtrair, multiplicar ou dividir os seus dois membros por um mesmo número e utilizar essa noção para determinar valores desconhecidos na resolução de problemas.", "o": "Propriedades da igualdade."}, {"a": "6", "t": "1", "c": "EF06MA35/ES", "e": "", "h": "Resolver situações problemas de contagem, que envolvam o princípio multiplicativo, por meio de estratégias variadas, como a construção de diagramas, tabelas e esquemas sem aplicação de fórmulas.", "o": "Princípio fundamental da contagem. Programação: Linguagem de programação. Estratégias de solução de problemas: decomposição."}, {"a": "6", "t": "2", "c": "EF06MA07", "e": "", "h": "Compreender, comparar e ordenar frações associadas às ideias de partes de inteiros e resultado de divisão, identificando frações equivalentes.", "o": "Números Racionais: frações Frações: significados (parte/todo, quociente), equivalência, comparação."}, {"a": "6", "t": "2", "c": "EF06MA10/ES", "e": "", "h": "Resolver e elaborar problemas que envolvam adição e/ou subtração com números racionais positivos na representação fracionária.", "o": "Adição e subtração de frações."}, {"a": "6", "t": "2", "c": "EF06MA11", "e": "", "h": "Resolver e elaborar problemas com números racionais positivos na representação decimal, envolvendo as quatro operações fundamentais e a potenciação, por meio de estratégias diversas, utilizando estimativas e arredondamentos para verificar a razoabilidade de respostas, com e sem uso de calculadora.", "o": "Operações (adição, subtração, multiplicação, divisão e potenciação) com números racionais."}, {"a": "6", "t": "2", "c": "EF06MA13", "e": "", "h": "Resolver e elaborar problemas que envolvam porcentagens, com base na ideia de proporcionalidade, sem fazer uso da “regra de três”, utilizando estratégias pessoais, cálculo mental e calculadora, em contextos de educação financeira, entre outros.", "o": "Porcentagem. Cálculo de porcentagens por meio de estratégias diversas, sem fazer uso da “regra de três”."}, {"a": "6", "t": "2", "c": "EF06MA17", "e": "", "h": "Quantificar e estabelecer relações entre o número de vértices, faces e arestas de prismas e pirâmides, em função do seu polígono da base, para resolver problemas e desenvolver a percepção espacial.", "o": "Geometria Espacial. Prismas e pirâmides: planificações e relações entre seus elementos (vértices, faces e arestas)."}, {"a": "6", "t": "2", "c": "EF06MA18", "e": "", "h": "Reconhecer, nomear e comparar polígonos, considerando lados, vértices e ângulos, e classificá- los em regulares e não regulares, tanto em suas representações no plano como em faces de poliedros.", "o": "Polígonos: classificações quanto ao número de vértices, às medidas de lados e ângulos e ao paralelismo e perpendicularismo dos lados."}, {"a": "6", "t": "2", "c": "EF06MA19", "e": "", "h": "Identificar características dos triângulos e classificá-los em relação às medidas dos lados e dos ângulos.", "o": "Polígonos (triângulos): classificações quanto às medidas de lados e ângulos."}, {"a": "6", "t": "2", "c": "EF06MA20", "e": "", "h": "Identificar características dos quadriláteros, classificá- los em relação a lados e a ângulos e reconhecer a inclusão e a intersecção de classes entre eles.", "o": "Polígonos (quadriláteros): classificações quanto às medidas de lados e ângulos e ao paralelismo e perpendicularismo dos lados."}, {"a": "6", "t": "2", "c": "EF06MA25", "e": "", "h": "Reconhecer a abertura do ângulo como grandeza associada às figuras geométricas.", "o": "Ângulos: noção, usos e medida."}, {"a": "6", "t": "2", "c": "EF06MA26", "e": "", "h": "Resolver problemas que envolvam a noção de ângulo em diferentes contextos e em situações reais, como ângulo de visão.", "o": "Ângulos: noção, usos e medida."}, {"a": "6", "t": "2", "c": "EF06MA27", "e": "", "h": "Determinar medidas da abertura de ângulos, por meio de transferidor e/ou tecnologias digitais.", "o": "Ângulos: noção, usos e medida."}, {"a": "6", "t": "3", "c": "EF06MA15", "e": "", "h": "Resolver e elaborar problemas que envolvam a partilha de uma quantidade em duas partes desiguais, envolvendo relações aditivas e multiplicativas, bem como a razão entre as partes e entre uma das partes e o todo.", "o": "Problemas que tratam da partição de um todo em duas partes desiguais, envolvendo razões entre as partes e entre uma das partes e o todo."}, {"a": "6", "t": "3", "c": "EF06MA16/ES", "e": "", "h": "Associar pares ordenados de números a pontos do plano cartesiano do 1º quadrante, em situações como a localização dos vértices de um polígono no plano, utilizando ou não jogos (batalha naval e outros), malhas quadriculadas e planilhas eletrônicas, mapas e aplicativos (GPS).", "o": "Plano cartesiano: associação dos vértices de um polígono a pares ordenados. Estratégias de solução de problemas: Generalização."}, {"a": "6", "t": "3", "c": "EF06MA21", "e": "", "h": "Construir figuras planas semelhantes em situações de ampliação e de redução, com o uso de malhas quadriculadas, plano cartesiano ou tecnologias digitais.", "o": "Construção de figuras semelhantes: ampliação e redução de figuras planas em malhas quadriculadas."}, {"a": "6", "t": "3", "c": "EF06MA22", "e": "", "h": "Utilizar instrumentos, como réguas, esquadros ou softwares, para representações de retas paralelas e perpendiculares e construção de quadriláteros, entre outros.", "o": "Construção de retas paralelas e perpendiculares, fazendo uso de réguas, esquadros e softwares."}, {"a": "6", "t": "3", "c": "EF06MA23", "e": "", "h": "Construir algoritmo para resolver situações passo a passo (como na construção de dobraduras ou na indicação de deslocamento de um objeto no plano segundo pontos de referência e distâncias fornecidas etc.).", "o": "Construção de retas paralelas e perpendiculares, fazendo uso de réguas, esquadros e softwares."}, {"a": "6", "t": "3", "c": "EF06MA24", "e": "", "h": "Resolver e elaborar problemas que envolvam as grandezas como comprimento, massa, tempo, temperatura, área (triângulos e retângulos), capacidade e volume (sólidos formados por blocos retangulares), sem uso de fórmulas, inseridos, sempre que possível, em contextos oriundos de situações reais e/ou relacionadas às outras áreas do conhecimento.", "o": "Problemas sobre medidas envolvendo grandezas como comprimento, massa, tempo, temperatura, área, capacidade e volume. Armazenamento e Transmissão de dados: gestão de dados."}, {"a": "6", "t": "3", "c": "EF06MA28", "e": "", "h": "Interpretar, descrever e desenhar plantas baixas simples de residências e vistas aéreas.", "o": "Plantas baixas e vistas aéreas."}, {"a": "6", "t": "3", "c": "EF06MA29", "e": "", "h": "Analisar e descrever mudanças que ocorrem no perímetro e na área de um quadrado ao se ampliarem ou reduzirem, igualmente, as medidas de seus lados, para compreender que o perímetro é proporcional à medida do lado, o que não ocorre com a área.", "o": "Perímetro de um quadrado como grandeza proporcional à medida do lado."}, {"a": "6", "t": "3", "c": "EF06MA30", "e": "", "h": "Calcular a probabilidade de um evento aleatório, expressando-a por número racional (forma fracionária, decimal e percentual) e comparar esse número com a probabilidade obtida por meio de experimentos sucessivos.", "o": "Cálculo de probabilidade como a razão entre o número de resultados favoráveis e o total de resultados possíveis em um espaço amostral equiprovável. Cálculo de probabilidade por meio de muitas repetições de um experimento (frequências de ocorrências e probabilidade frequentista)."}, {"a": "6", "t": "3", "c": "EF06MA31", "e": "", "h": "Identificar as variáveis e suas frequências e os elementos constitutivos (título, eixos, legendas, fontes e datas) em diferentes tipos de gráfico.", "o": "Leitura e interpretação de tabelas e gráficos (de colunas ou barras simples ou múltiplas) referentes a variáveis categóricas e variáveis numéricas."}, {"a": "6", "t": "3", "c": "EF06MA32", "e": "", "h": "Interpretar e resolver situações que envolvam dados de pesquisas sobre contextos ambientais, sustentabilidade, trânsito, consumo responsável, entre outros, apresentadas pela mídia em tabelas e em diferentes tipos de gráficos e redigir textos escritos com o objetivo de sintetizar conclusões.", "o": "Leitura e interpretação de tabelas e gráficos (de colunas ou barras simples ou múltiplas) referentes a variáveis categóricas e variáveis numéricas. Uso de tecnologias Computacionais: Tecnologia digital e sustentabilidade."}, {"a": "7", "t": "1", "c": "EF07MA03", "e": "", "h": "Comparar e ordenar números inteiros em diferentes contextos, incluindo o histórico, associá-los a pontos da reta numérica e utilizá-los em situações que envolvam adição e subtração.", "o": "Números Inteiros. Números inteiros: usos, história, ordenação, associação com pontos da reta numérica e operações."}, {"a": "7", "t": "1", "c": "EF07MA04/ES", "e": "", "h": "Resolver e elaborar problemas que envolvam operações com números inteiros, incluindo módulos, números opostos e/ou simétricos.", "o": "Números inteiros: usos, história, ordenação, associação com pontos da reta numérica e operações."}, {"a": "7", "t": "1", "c": "EF07MA05/ES", "e": "", "h": "Resolver um mesmo problema utilizando diferentes algoritmos e materiais manipuláveis.", "o": "Números racionais na representação fracionária e na decimal: usos, ordenação e associação com pontos da reta numérica e operações."}, {"a": "7", "t": "1", "c": "EF07MA06", "e": "", "h": "Reconhecer que as resoluções de um grupo de problemas que têm a mesma estrutura podem ser obtidas utilizando os mesmos procedimentos.", "o": "Números racionais na representação fracionária e na decimal: usos, ordenação e associação com pontos da reta numérica e operações."}, {"a": "7", "t": "1", "c": "EF07MA07", "e": "", "h": "Representar por meio de um fluxograma os passos utilizados para resolver um grupo de problemas.", "o": "Números racionais na representação fracionária e na decimal: usos, ordenação e associação com pontos da reta numérica e operações."}, {"a": "7", "t": "1", "c": "EF07MA08", "e": "", "h": "Comparar e ordenar frações associadas a ideias de partes de inteiros, resultado da divisão, razão e operador.", "o": "Números racionais."}, {"a": "7", "t": "1", "c": "EF07MA09", "e": "", "h": "Utilizar, na resolução de problemas, a associação entre razão e fração, como a fração 2/3 para expressar a razão de duas partes de uma grandeza para três partes da mesma ou três partes de outra grandeza.", "o": "Fração e seus significados: como parte de inteiros, resultados da divisão, razão e operador."}, {"a": "7", "t": "1", "c": "EF07MA10", "e": "", "h": "Comparar e ordenar números racionais em diferentes contextos e associá-los a pontos da reta numérica.", "o": "Números racionais na representação fracionária e na decimal: usos, ordenação e associação com pontos da reta numérica e operações."}, {"a": "7", "t": "1", "c": "EF07MA11/ES", "e": "", "h": "Compreender e utilizar a multiplicação e a divisão de números racionais, a relação entre elas e suas propriedades operatórias, incluindo a potenciação.", "o": "Números racionais na representação fracionária e na decimal: usos, ordenação e associação com pontos da reta numérica e operações."}, {"a": "7", "t": "1", "c": "EF07MA12/ES", "e": "", "h": "Resolver e elaborar problemas que envolvam as operações com números racionais.", "o": "Números racionais na representação fracionária e na decimal: usos, ordenação e associação com pontos da reta numérica e operações."}, {"a": "7", "t": "2", "c": "EF07MA02", "e": "", "h": "Resolver e elaborar problemas que envolvam porcentagens, como os que lidam com acréscimos e decréscimos simples, utilizando estratégias pessoais, cálculo mental e calculadora, no contexto de educação financeira, entre outros.", "o": "Cálculo de porcentagens e de acréscimos e decréscimos simples."}, {"a": "7", "t": "2", "c": "EF07MA13", "e": "", "h": "Compreender a ideia de variável, representada por letra ou símbolo, para expressar relação entre duas grandezas, diferenciando-a da ideia de incógnita.", "o": "Linguagem algébrica: variável e incógnita."}, {"a": "7", "t": "2", "c": "EF07MA14", "e": "", "h": "Classificar sequências em recursivas e não-recursivas, reconhecendo que o conceito de recursão está presente não apenas na Matemática, mas também nas artes e na literatura.", "o": "Sequências."}, {"a": "7", "t": "2", "c": "EF07MA15", "e": "", "h": "Utilizar a simbologia algébrica para expressar regularidades encontradas em sequências numéricas.", "o": "Linguagem algébrica: variável e incógnita."}, {"a": "7", "t": "2", "c": "EF07MA16", "e": "", "h": "Reconhecer se duas expressões algébricas obtidas para descrever a regularidade de uma mesma sequência numérica são ou não equivalentes.", "o": "Equivalência de expressões algébricas: identificação da regularidade de uma sequência numérica."}, {"a": "7", "t": "2", "c": "EF07MA17", "e": "", "h": "Resolver e elaborar problemas que envolvam variação de proporcionalidade direta e de proporcionalidade inversa entre duas grandezas, utilizando sentença algébrica para expressar a relação entre elas.", "o": "Proporcionalidade. Problemas envolvendo grandezas diretamente proporcionais e grandezas inversamente proporcionais. Regra de três simples."}, {"a": "7", "t": "2", "c": "EF07MA18", "e": "", "h": "Resolver e elaborar problemas que possam ser representados por equações polinomiais de 1º grau, redutíveis à forma ax + b = c, fazendo uso das propriedades da igualdade.", "o": "Equações polinomiais do 1º grau."}, {"a": "7", "t": "2", "c": "EF07MA34", "e": "", "h": "Planejar e realizar experimentos aleatórios ou simulações que envolvem cálculo de probabilidades ou estimativas por meio de frequência de ocorrências.", "o": "Probabilidade. Experimentos aleatórios: espaço amostral e estimativa de probabilidade por meio de frequência de ocorrências."}, {"a": "7", "t": "2", "c": "EF07MA35", "e": "", "h": "Compreender, em contextos significativos, o significado de média estatística como indicador da tendência de uma pesquisa, calcular seu valor e relacioná-lo, intuitivamente, com a amplitude do conjunto de dados.", "o": "Estatística. Estatística: média e amplitude de um conjunto de dados."}, {"a": "7", "t": "2", "c": "EF07MA36", "e": "", "h": "Planejar e realizar pesquisa envolvendo tema da realidade social, identificando a necessidade de ser censitária ou de usar amostra, e interpretar os dados para comunicá-los por meio de relatório escrito, tabelas e gráficos, com o apoio de planilhas eletrônicas.", "o": "Estatística. Pesquisa amostral e pesquisa censitária. Planejamento de pesquisa, coleta e organização dos dados, construção de tabelas e gráficos e intepretação das informações. Programação: análise de programas. Uso de tecnologias computacionais: produção Digital."}, {"a": "7", "t": "2", "c": "EF07MA37", "e": "", "h": "Interpretar e analisar dados apresentados em gráfico de setores divulgados pela mídia e compreender quando é possível ou conveniente sua utilização.", "o": "Estatística. Gráfico de setores: interpretação, pertinência e construção para representar conjuntos de dados."}, {"a": "7", "t": "3", "c": "EF07MA22", "e": "", "h": "Construir circunferências, utilizando compasso, reconhecê-las como lugar geométrico e utilizá-las para fazer composições artísticas e resolver problemas que envolvam objetos equidistantes.", "o": "A circunferência como lugar geométrico."}, {"a": "7", "t": "3", "c": "EF07MA23", "e": "", "h": "Verificar relações entre os ângulos formados por retas paralelas cortadas por uma transversal, com e sem uso de softwares de geometria dinâmica.", "o": "Relações entre os ângulos formados por retas paralelas intersectadas por uma transversal."}, {"a": "7", "t": "3", "c": "EF07MA24", "e": "", "h": "Construir triângulos, usando régua e compasso, reconhecer a condição de existência do triângulo quanto à medida dos lados e verificar que a soma das medidas dos ângulos internos de um triângulo é 180°.", "o": "Triângulos: construção, condição de existência e soma das medidas dos ângulos internos."}, {"a": "7", "t": "3", "c": "EF07MA25", "e": "", "h": "Reconhecer a rigidez geométrica dos triângulos e suas aplicações, como na construção de estruturas arquitetônicas (telhados, estruturas metálicas e outras) ou nas artes plásticas.", "o": "Triângulos: construção, condição de existência e soma das medidas dos ângulos internos."}, {"a": "7", "t": "3", "c": "EF07MA26", "e": "", "h": "Descrever, por escrito e por meio de um fluxograma, um algoritmo para a construção de um triângulo qualquer, conhecidas as medidas dos três lados.", "o": "Triângulos: construção, condição de existência e soma das medidas dos ângulos internos."}, {"a": "7", "t": "3", "c": "EF07MA27", "e": "", "h": "Calcular medidas de ângulos internos de polígonos regulares, sem o uso de fórmulas, e estabelecer relações entre ângulos internos e externos de polígonos, preferencialmente vinculadas à construção de mosaicos e de ladrilhamentos.", "o": "Polígonos regulares: quadrado e triângulo equilátero. Soma dos ângulos internos e externos de polígonos."}, {"a": "7", "t": "3", "c": "EF07MA28", "e": "", "h": "Descrever, por escrito e por meio de um fluxograma, um algoritmo para a construção de um polígono regular (como quadrado e triângulo equilátero), conhecida a medida de seu lado.", "o": "Polígonos regulares: quadrado e triângulo equilátero."}, {"a": "7", "t": "3", "c": "EF07MA29/ES", "e": "", "h": "Resolver e elaborar problemas que envolvam medidas de grandezas inseridas em contextos oriundos de situações cotidianas ou de outras áreas do conhecimento, reconhecendo que toda medida empírica é aproximada, oportunizando o trabalho contextualizado com temas relacionados à arquitetura, urbanismo, engenharia e etc.", "o": "Problemas sobre medidas envolvendo grandezas como comprimento, massa, tempo, temperatura, área, capacidade e volume. Problemas envolvendo medições."}, {"a": "7", "t": "3", "c": "EF07MA30", "e": "", "h": "Resolver e elaborar problemas de cálculo de medida do volume de blocos retangulares, envolvendo as unidades usuais (metro cúbico, decímetro cúbico e centímetro cúbico).", "o": "Volumes dos principais sólidos. Cálculo de volume de blocos retangulares, utilizando unidades de medida convencionais mais usuais."}, {"a": "7", "t": "3", "c": "EF07MA31", "e": "", "h": "Estabelecer expressões de cálculo de área de triângulos e de quadriláteros.", "o": "Área de figuras planas."}, {"a": "7", "t": "3", "c": "EF07MA32", "e": "", "h": "Resolver e elaborar problemas de cálculo de medida de área de figuras planas que podem ser decompostas por quadrados, retângulos e/ou triângulos, utilizando a equivalência entre áreas.", "o": "Equivalência de área de figuras planas: cálculo de áreas de figuras que podem ser decompostas por outras, cujas áreas podem ser facilmente determinadas como triângulos e quadriláteros."}, {"a": "7", "t": "3", "c": "EF07MA33", "e": "", "h": "Estabelecer o número π como a razão entre a medida de uma circunferência e seu diâmetro, para compreender e resolver problemas, inclusive os de natureza histórica.", "o": "Diâmetro e raio de uma circunferência e a relação com número π. Medida do comprimento da circunferência."}, {"a": "8", "t": "1", "c": "EF08MA01", "e": "", "h": "Efetuar cálculos com potências de expoentes inteiros e aplicar esse conhecimento na representação de números em notação científica.", "o": "Potenciação"}, {"a": "8", "t": "1", "c": "EF08MA02", "e": "", "h": "Resolver e elaborar problemas usando a relação entre potenciação e radiciação, para representar uma raiz como potência de expoente fracionário.", "o": "Potenciação e radiciação"}, {"a": "8", "t": "1", "c": "EF08MA06/ES", "e": "", "h": "Resolver e elaborar problemas que envolvam cálculo do valor numérico de expressões algébricas, utilizando as propriedades das operações e noções de fatoração e produtos notáveis.", "o": "Valor numérico de expressões algébricas."}, {"a": "8", "t": "1", "c": "EF08MA10", "e": "", "h": "Identificar a regularidade de uma sequência numérica ou figural não recursiva e construir um algoritmo por meio de um fluxograma que permita indicar os números ou as figuras seguintes.", "o": "Sequências não recursivas."}, {"a": "8", "t": "1", "c": "EF08MA11/ES", "e": "", "h": "Identificar a regularidade de uma sequência numérica recursiva (ou recorrentes) e construir um algoritmo por meio de um fluxograma que permita indicar os números seguintes.", "o": "Sequências recursivas. Programação: programação com listas e recursão."}, {"a": "8", "t": "2", "c": "EF08MA03", "e": "", "h": "Resolver e elaborar problemas de contagem cuja resolução envolve a aplicação do princípio multiplicativo.", "o": "O princípio multiplicativo da contagem."}, {"a": "8", "t": "2", "c": "EF08MA04/ES", "e": "", "h": "Resolver e elaborar problemas, envolvendo cálculo de porcentagens, incluindo o uso de tecnologias digitais e enfatizando suas aplicações no cotidiano.", "o": "Porcentagens. Uso de ferramentas digitais para cálculos (calculadora, app para cálculos etc.)."}, {"a": "8", "t": "2", "c": "EF08MA07", "e": "", "h": "Associar uma equação linear de 1º grau com duas incógnitas a uma reta no plano cartesiano.", "o": "Associação de uma equação linear de 1º grau a uma reta no plano cartesiano."}, {"a": "8", "t": "2", "c": "EF08MA08", "e": "", "h": "Resolver e elaborar problemas relacionados ao seu contexto próximo, que possam ser representados por sistemas de equações de 1º grau com duas incógnitas e interpretá-los, utilizando, inclusive, o plano cartesiano como recurso.", "o": "Sistema de equações polinomiais de 1º grau: resolução algébrica e representação no plano cartesiano."}, {"a": "8", "t": "2", "c": "EF08MA12/ES", "e": "", "h": "Identificar a natureza da variação de duas grandezas, diretamente, inversamente proporcionais ou não proporcionais, expressando a relação existente por meio de sentença algébrica e representá-la no plano cartesiano.", "o": "Proporcionalidade. Variação de grandezas: diretamente proporcionais, inversamente proporcionais ou não proporcionais."}, {"a": "8", "t": "2", "c": "EF08MA13/ES", "e": "", "h": "Resolver e elaborar problemas que envolvam duas ou mais grandezas diretamente ou inversamente proporcionais, por meio de estratégias variadas.", "o": "Variação de grandezas: diretamente proporcionais, inversamente proporcionais ou não proporcionais. Regra de três simples e composta."}, {"a": "8", "t": "2", "c": "EF08MA22", "e": "", "h": "Calcular a probabilidade de eventos, com base na construção do espaço amostral, utilizando o princípio multiplicativo, e reconhecer que a soma das probabilidades de todos os elementos do espaço amostral é igual a 1.", "o": "Princípio multiplicativo da contagem. Probabilidade. Soma das probabilidades de todos os elementos de um espaço amostral."}, {"a": "8", "t": "2", "c": "EF08MA23", "e": "", "h": "Avaliar a adequação de diferentes tipos de gráficos para representar um conjunto de dados de uma pesquisa.", "o": "Gráficos de barras, colunas, linhas ou setores e seus elementos constitutivos e adequação para determinado conjunto de dados."}, {"a": "8", "t": "2", "c": "EF08MA24", "e": "", "h": "Classificar as frequências de uma variável contínua de uma pesquisa em classes, de modo que resumem os dados de maneira adequada para a tomada de decisões.", "o": "Organização dos dados de uma variável contínua em classes."}, {"a": "8", "t": "2", "c": "EF08MA25", "e": "", "h": "Obter os valores de medidas de tendência central de uma pesquisa estatística (média, moda e mediana) com a compreensão de seus significados e relacioná- los com a dispersão de dados, indicada pela amplitude.", "o": "Medidas de tendência central e de dispersão."}, {"a": "8", "t": "3", "c": "EF08MA09", "e": "", "h": "Resolver e elaborar, com e sem uso de tecnologias, problemas que possam ser representados por equações polinomiais de 2º grau do tipo ax² = b.", "o": "Equações. Equação polinomial de 2º grau do tipo ax² = b."}, {"a": "8", "t": "3", "c": "EF08MA14", "e": "", "h": "Demonstrar propriedades de quadriláteros por meio da identificação da congruência de triângulos.", "o": "Congruência de triângulos e demonstrações de propriedades de quadriláteros."}, {"a": "8", "t": "3", "c": "EF08MA15", "e": "", "h": "Construir, utilizando instrumentos de desenho ou softwares de geometria dinâmica, mediatriz, bissetriz, ângulos de 90°, 60°, 45° e 30° e polígonos regulares.", "o": "Construções geométricas: ângulos de 90°, 60°, 45° e 30° e polígonos regulares."}, {"a": "8", "t": "3", "c": "EF08MA17/ES", "e": "", "h": "Aplicar os conceitos de mediatriz e bissetriz como lugares geométricos na resolução de problemas, utilizando ou não desenhos geométricos.", "o": "Mediatriz e bissetriz como lugares geométricos: construção e problemas"}, {"a": "8", "t": "3", "c": "EF08MA19", "e": "", "h": "Resolver e elaborar problemas que envolvam medidas de área de figuras geométricas, utilizando expressões de cálculo de área (quadriláteros, triângulos e círculos), em situações como determinar medida de terrenos.", "o": "Área de figuras planas. Área do círculo e comprimento de sua circunferência."}, {"a": "8", "t": "3", "c": "EF08MA20", "e": "", "h": "Reconhecer a relação entre um litro e um decímetro cúbico e a relação entre litro e metro cúbico, para resolver problemas de cálculo de capacidade de recipientes.", "o": "Volume dos principais sólidos. Medidas de capacidade."}, {"a": "8", "t": "3", "c": "EF08MA21", "e": "", "h": "Resolver e elaborar problemas que envolvam o cálculo do volume de recipiente cujo formato é o de um bloco retangular.", "o": "Volume dos principais sólidos."}, {"a": "9", "t": "1", "c": "EF09MA03/ES", "e": "", "h": "Efetuar cálculos com números reais, inclusive potências com expoentes fracionários e decimais (radiciação).", "o": "Potências com expoentes negativos, decimais e fracionários. Radiciação e suas Propriedades."}, {"a": "9", "t": "1", "c": "EF09MA04", "e": "", "h": "Resolver e elaborar problemas com números reais, inclusive em notação científica, envolvendo diferentes operações.", "o": "Números reais: problemas."}, {"a": "9", "t": "1", "c": "EF09MA05/ES", "e": "", "h": "Resolver e elaborar problemas que envolvam porcentagens, com a ideia de aplicação de percentuais sucessivos e a determinação das taxas percentuais, preferencialmente com o uso de tecnologias digitais, no contexto da educação financeira, fiscal e tributária.", "o": "Porcentagens: problemas que envolvem cálculo de percentuais sucessivos. Uso de ferramentas digitais para cálculos (calculadora, aplicativos móveis para cálculos, planilha eletrônica etc.)"}, {"a": "9", "t": "1", "c": "EF09MA07", "e": "", "h": "Resolver problemas que envolvam a razão entre duas grandezas de espécies diferentes, como velocidade e densidade demográfica.", "o": "Razão entre grandezas de espécies diferentes."}, {"a": "9", "t": "1", "c": "EF09MA08", "e": "", "h": "Resolver e elaborar problemas que envolvam relações de proporcionalidade direta e inversa entre duas ou mais grandezas, inclusive escalas, divisão em partes proporcionais e taxa de variação, em contextos socioculturais, ambientais e de outras áreas.", "o": "Grandezas diretamente proporcionais e grandezas Inversamente proporcionais."}, {"a": "9", "t": "1", "c": "EF09MA10", "e": "", "h": "Demonstrar relações simples entre os ângulos formados por retas paralelas cortadas por uma transversal.", "o": "Demonstrações de relações entre os ângulos formados por retas paralelas intersectadas por uma transversal."}, {"a": "9", "t": "1", "c": "EF09MA14/ES", "e": "", "h": "Resolver e elaborar problemas de aplicação do teorema de Pitágoras ou das relações de proporcionalidade envolvendo retas paralelas cortadas por secantes/ transversal (Teorema de Tales).", "o": "Demonstrações de relações entre os ângulos formados por retas paralelas intersectadas por uma transversal."}, {"a": "9", "t": "2", "c": "EF09MA09", "e": "", "h": "Compreender os processos de fatoração de expressões algébricas, com base em suas relações com os produtos notáveis, para resolver e elaborar problemas que possam ser representados por equações polinomiais do 2º grau.", "o": "Expressões algébricas: fatoração, produtos notáveis."}, {"a": "9", "t": "2", "c": "EF09MA12", "e": "", "h": "Reconhecer as condições necessárias e suficientes para que dois triângulos sejam semelhantes.", "o": "Semelhança de triângulos."}, {"a": "9", "t": "2", "c": "EF09MA13", "e": "", "h": "Demonstrar relações métricas do triângulo retângulo, entre elas o teorema de Pitágoras, utilizando, inclusive, a semelhança de triângulos.", "o": "Relações métricas no triângulo retângulo. Teorema de Pitágoras: verificações experimentais e Demonstração."}, {"a": "9", "t": "2", "c": "EF09MA20", "e": "", "h": "Reconhecer, em experimentos aleatórios, eventos independentes e dependentes e calcular a probabilidade de sua ocorrência, nos dois casos.", "o": "Probabilidade Análise de probabilidade de eventos aleatórios: eventos dependentes e independentes. Sistemas distribuídos e internet: segurança cibernética."}, {"a": "9", "t": "2", "c": "EF09MA22", "e": "", "h": "Escolher e construir o gráfico mais adequado (colunas, setores, linhas), com ou sem uso de planilhas eletrônicas, para apresentar um determinado conjunto de dados, destacando aspectos como as medidas de tendência central.", "o": "Leitura, interpretação e representação de dados de pesquisa expressos em tabelas de dupla entrada, gráficos de colunas simples e agrupadas, gráficos de barras e de setores e gráficos pictóricos."}, {"a": "9", "t": "2", "c": "EF09MA23", "e": "", "h": "Planejar e executar pesquisa amostral envolvendo tema da realidade social e comunicar os resultados por meio de relatório contendo avaliação de medidas de tendência central e da amplitude, tabelas e gráficos adequados, construídos com o apoio de planilhas eletrônicas.", "o": "Estatística. Planejamento e execução de pesquisa amostral e apresentação de relatório. Segurança e responsabilidade no uso da tecnologia: Tecnologia digital e sociedade."}, {"a": "9", "t": "2", "c": "EF09MA26/ES", "e": "", "h": "Resolver e elaborar, com e sem uso de tecnologias, problemas que possam ser representados por equações polinomiais de 2º grau do tipo ax² + bx + c=0.", "o": "Resolução de equações polinomiais do 2º grau por meio de fatorações. Equação polinomial de 2º grau do tipo ax² + bx + c=0."}, {"a": "9", "t": "3", "c": "EF09MA01", "e": "", "h": "Reconhecer que, uma vez fixada uma unidade de comprimento, existem segmentos de reta cujo comprimento não é expresso por número racional (como as medidas de diagonais de um polígono e alturas de um triângulo, quando se toma a medida de cada lado como unidade).", "o": "Números reais. Necessidade dos números reais para medir qualquer segmento de reta. Números irracionais: reconhecimento e localização de alguns na reta numérica."}, {"a": "9", "t": "3", "c": "EF09MA02", "e": "", "h": "Reconhecer um número irracional como um número real cuja representação decimal é infinita e não periódica, e estimar a localização de alguns deles na reta numérica.", "o": "Números reais. Necessidade dos números reais para medir qualquer segmento de reta. Números irracionais: reconhecimento e localização de alguns na reta numérica."}, {"a": "9", "t": "3", "c": "EF09MA06", "e": "", "h": "Compreender as funções como relações de dependência unívoca entre duas variáveis e suas representações numérica, algébrica e gráfica e utilizar esse conceito para analisar situações que envolvam relações funcionais entre duas variáveis.", "o": "Funções: representações numérica, algébrica e gráfica. Função afim. Função quadrática."}, {"a": "9", "t": "3", "c": "EF09MA11", "e": "", "h": "Resolver problemas por meio do estabelecimento de relações entre arcos, ângulos centrais e ângulos inscritos na circunferência, fazendo uso, inclusive, de softwares de geometria dinâmica.", "o": "Relações entre arcos e ângulos na circunferência de um círculo. Uso de softwares de geometria."}, {"a": "9", "t": "3", "c": "EF09MA17", "e": "", "h": "Reconhecer vistas ortogonais de figuras espaciais e aplicar esse conhecimento para desenhar objetos em perspectiva.", "o": "Vistas ortogonais de figuras espaciais."}, {"a": "9", "t": "3", "c": "EF09MA19", "e": "", "h": "Resolver e elaborar problemas que envolvam medidas de volumes de prismas e de cilindros retos, inclusive com uso de expressões de cálculo, em situações cotidianas.", "o": "Volume de prismas e cilindros."}], "Língua Portuguesa": [{"a": "6", "t": "1", "c": "EF06LP01/ES", "e": "", "h": "Reconhecer a impossibilidade de uma neutralidade absoluta no relato de fatos e identificar diferentes graus de parcialidade/ imparcialidade dados pelo recorte feito e pelos efeitos de sentido advindos de escolhas feitas pelo autor, de forma a poder desenvolver uma atitude crítica frente aos textos jornalísticos e tornar-se consciente das escolhas feitas enquanto produtor de textos.", "o": "Reconstrução do contexto de produção, circulação e recepção de textos. Caracterização do campo jornalístico e relação entre os gêneros em circulação, mídias e práticas da cultura digital."}, {"a": "6", "t": "1", "c": "EF06LP03/ES", "e": "", "h": "Analisar diferenças de sentido entre palavras de uma série sinonímica, associado à análise comparativa e à reflexão com base em inventários que apresentam palavras em textos.", "o": "Léxico/morfologia"}, {"a": "6", "t": "1", "c": "EF69LP05", "e": "", "h": "Inferir e justificar, em textos multissemióticos – tirinhas, charges, memes, gifs etc. –, o efeito de humor, ironia e/ou crítica pelo uso ambíguo de palavras, expressões ou imagens ambíguas, de clichês, de recursos iconográficos, de pontuação etc.", "o": "Morfologia."}, {"a": "6", "t": "1", "c": "EF67LP06", "e": "", "h": "Identificar os efeitos de sentido provocados pela seleção lexical, topicalização de elementos e seleção e hierarquização de informações, uso de 3ª pessoa, etc.", "o": "Efeitos de sentido. Exploração da multissemiose"}, {"a": "6", "t": "1", "c": "EF67LP07/ES", "e": "", "h": "Identificar o uso de recursos persuasivos em textos argumentativos diversos (comentários, crônicas, artigos de opinião, charges, propagandas etc.) como a elaboração do título, escolhas lexicais, construções metafóricas, a explicitação ou a ocultação de fontes de informação e perceber seus efeitos de sentido, observando a complexidade da seleção dos textos argumentativos e a variedade dos gêneros propostos.", "o": "Efeitos de sentido. Exploração da multissemiose."}, {"a": "6", "t": "1", "c": "EF67LP22", "e": "", "h": "Produzir resumos - a partir das notas e/ou esquemas feitos, com o uso adequado de paráfrases e citações.", "o": "Estratégias de escrita: textualização, revisão e edição."}, {"a": "6", "t": "1", "c": "EF67LP30", "e": "", "h": "Criar narrativas ficcionais, tais como contos populares, contos de suspense, mistério, terror, humor, narrativas de enigma, crônicas, histórias em quadrinhos, dentre outros, que utilizem cenários e personagens realistas ou de fantasia, observando os elementos da estrutura narrativa próprios ao gênero pretendido, tais como enredo, personagens, tempo, espaço e narrador, utilizando tempos verbais adequados narração de fatos passados, empregando conhecimentos sobre diferentes modos de se iniciar uma história e de inserir os discursos direto e indireto.", "o": "Construção da textualidade. Relação entre textos. Morfossintaxe."}, {"a": "6", "t": "1", "c": "EF67LP34", "e": "", "h": "Formar antônimos com acréscimo de prefixos que expressam noção de negação", "o": "Léxico/morfologia"}, {"a": "6", "t": "1", "c": "EF69LP34", "e": "", "h": "Grifar as partes essenciais do texto, tendo em vista os objetivos de leitura, produzir marginálias (ou tomar notas em outro suporte), sínteses organizadas em itens, quadro sinóptico, quadro comparativo, esquema, resumo ou resenha do texto lido (com ou sem comentário/análise), mapa conceitual, dependendo do que for mais adequado, como forma de possibilitar uma maior compreensão do texto, a sistematização de conteúdos e informações e um posicionamento frente aos textos, se esse for o caso.", "o": "Estratégias e procedimentos de leitura. Relação do verbal com outras semioses. Procedimentos e gêneros de apoio à compreensão."}, {"a": "6", "t": "1", "c": "EF69LP55", "e": "", "h": "Reconhecer as variedades da língua falada, o conceito de norma-padrão e o de preconceito linguístico.", "o": "Variação linguística"}, {"a": "6", "t": "2", "c": "EF06LP02", "e": "", "h": "Estabelecer relação entre os diferentes gêneros jornalísticos, compreendendo a centralidade da notícia.", "o": "Reconstrução do contexto de produção, circulação e recepção de textos. Caracterização do campo jornalístico e relação entre os gêneros em circulação, mídias e práticas da cultura digital"}, {"a": "6", "t": "2", "c": "EF67LP02", "e": "", "h": "Explorar o espaço reservado ao leitor nos jornais, revistas, impressos e on-line, sites noticiosos etc., destacando notícias, fotorreportagens, entrevistas, charges, assuntos, temas, debates em foco, posicionando-se de maneira ética e respeitosa frente a esses textos e opiniões a eles relacionadas, e publicar notícias, notas jornalísticas, fotorreportagem de", "o": "Apreciação e réplica."}, {"a": "6", "t": "2", "c": "EF67LP03/ES", "e": "", "h": "Comparar informações sobre um mesmo fato divulgadas em diferentes veículos e mídias, analisando e avaliando a confiabilidade refletindo sobre parcialidade/imparcialidade em textos dessa esfera.", "o": "Relação entre textos."}, {"a": "6", "t": "2", "c": "EF06LP04/ES", "e": "", "h": "Analisar a função e as flexões de substantivos e adjetivos e de verbos nos modos Indicativo, Subjuntivo e Imperativo: afirmativo e negativo, realizando a análise dos tópicos mencionados em textos de todos os campos de atuação.", "o": "Morfossintaxe."}, {"a": "6", "t": "2", "c": "EF67LP04", "e": "", "h": "Distinguir, em segmentos descontínuos de textos, fato da opinião enunciada em relação a esse mesmo fato.", "o": "Estratégias de leitura Distinção de fato e opinião."}, {"a": "6", "t": "2", "c": "EF67LP05", "e": "", "h": "Identificar e avaliar teses, opiniões, posicionamentos explícitos e argumentos em textos argumentativos (carta de leitor, comentário, artigo de opinião, resenha crítica etc.), manifestando concordância ou discordância.", "o": "Estratégia de leitura: apreender os sentidos globais do texto. Apreciação e réplica."}, {"a": "6", "t": "2", "c": "EF06LP10/ES", "e": "", "h": "Identificar sintagmas nominais e verbais como constituintes imediatos da oração, associando essas análises à leitura e à produção de textos, com foco nos efeitos de sentido.", "o": "Sintaxe."}, {"a": "6", "t": "2", "c": "EF67LP28", "e": "", "h": "Ler, de forma autônoma, e compreender – selecionando procedimentos e estratégias de leitura adequados a diferentes objetivos e levando em conta características dos gêneros e suportes –, romances infanto-juvenis, contos populares, contos de terror, lendas brasileiras, indígenas e africanas, narrativas de aventuras, narrativas de enigma, mitos, crônicas, autobiografias, histórias em quadrinhos, mangás, poemas de forma livre e fixa (como sonetos e cordéis), vídeo-poemas, poemas visuais, dentre outros, expressando valiação sobre o texto lido e estabelecendo preferências por gêneros, temas, autores.", "o": "Estratégias de leitura. Apreciação e réplica."}, {"a": "6", "t": "2", "c": "EF67LP31", "e": "", "h": "Criar poemas compostos por versos livres e de forma fixa (como quadras e sonetos), utilizando recursos visuais, semânticos e sonoros, tais como cadências, ritmos e rimas, e poemas visuais e vídeo-poemas, explorando as relações entre imagem e texto verbal, a distribuição da mancha gráfica (poema visual) e outros recursos visuais e sonoros.", "o": "Construção da textualidade. Relação entre textos."}, {"a": "6", "t": "2", "c": "EF67LP38/ES", "e": "", "h": "Analisar os efeitos de sentido do uso de figuras de linguagem, como comparação, metáfora, metonímia, personificação, hipérbole, em textos literários ou de divulgação de conhecimento.", "o": "Figuras de Linguagem"}, {"a": "6", "t": "2", "c": "EF69LP47", "e": "", "h": "Analisar, em textos narrativos ficcionais, as diferentes formas de composição próprias de cada gênero, os recursos coesivos que constroem a passagem do tempo e articulam suas partes, a escolha lexical típica de cada gênero para a caracterização dos cenários e dos personagens e os efeitos de sentido decorrentes dos tempos verbais, dos tipos de discurso, dos verbos de enunciação e das variedades linguísticas (no discurso direto, se houver) empregados, identificando o enredo e o foco narrativo e percebendo como se estrutura a narrativa nos diferentes gêneros e os efeitos de sentido decorrentes do foco narrativo típico de cada gênero, da caracterização dos espaços físico e psicológico e dos tempos cronológico e psicológico, das diferentes vozes no texto (do narrador, de personagens em discurso direto e indireto), do uso de pontuação expressiva, palavras e expressões conotativas e processos figurativos e do uso de recursos linguístico-gramaticais próprios a cada gênero narrativo.", "o": "Reconstrução das condições de produção, circulação e recepção. Apreciação e réplica."}, {"a": "6", "t": "2", "c": "EF69LP48", "e": "", "h": "Interpretar, em poemas, efeitos produzidos pelo uso de recursos expressivos sonoros (estrofação, rimas, aliterações etc.), semânticos (figuras de linguagem, por exemplo), gráfico-espacial (distribuição da mancha gráfica no papel), imagens e sua relação com o texto verbal.", "o": "Reconstrução da textualidade e compreensão dos efeitos de sentidos provocados pelos usos de recursos linguísticos e multissemióticos."}, {"a": "6", "t": "3", "c": "EF69LP03", "e": "", "h": "Identificar, em notícias, o fato central, suas principais circunstâncias e eventuais decorrências; em reportagens e fotorreportagens o fato ou a temática retratada e a perspectiva de abordagem, em entrevistas os principais temas/subtemas abordados, explicações dadas ou teses defendidas em relação a esses subtemas; em tirinhas, memes, charge, a crítica, ironia ou humor presente.", "o": "Estratégia de leitura: apreender os sentidos globais do texto."}, {"a": "6", "t": "3", "c": "EF06LP06/ES", "e": "", "h": "Empregar adequadamente, em contextos de uso, as regras de concordância nominal (relações entre os substantivos e seus determinantes) e as regras de concordância verbal (relações entre o verbo e o sujeito simples e composto).", "o": "Morfossintaxe."}, {"a": "6", "t": "3", "c": "EF06LP07", "e": "", "h": "Identificar, em textos, períodos compostos por orações separadas por vírgula sem a utilização de conectivos, nomeando-os como períodos compostos por coordenação.", "o": "Morfossintaxe"}, {"a": "6", "t": "3", "c": "EF06LP08", "e": "", "h": "Identificar, em texto ou sequência textual, orações como unidades constituídas em torno de um núcleo verbal e períodos como conjunto de orações conectadas.", "o": "Morfossintaxe."}, {"a": "6", "t": "3", "c": "EF06LP09/ES", "e": "", "h": "Classificar, em texto ou sequência textual, os períodos simples e compostos.", "o": "Morfossintaxe"}, {"a": "6", "t": "3", "c": "EF67LP10/ES", "e": "", "h": "Produzir notícia impressa tendo em vista características do gênero – título ou manchete com verbo no tempo presente, linha fina (opcional), lide, progressão dada pela ordem decrescente de importância dos fatos, uso de 3ª pessoa, de palavras que indicam precisão –, e o estabelecimento adequado de coesão e produzir notícia para TV, rádio e internet, tendo em vista, além das características do gênero, os recursos de mídias disponíveis e o manejo de recursos de captação e edição de áudio e imagem.", "o": "Textualização, tendo em vista suas condições de produção, as características do gênero em questão, o estabelecimento de coesão, adequação à norma-padrão e o uso adequado de ferramentas de edição."}, {"a": "6", "t": "3", "c": "EF06LP12", "e": "", "h": "Utilizar, ao produzir texto, recursos de coesão referencial (nome e pronomes), recursos semânticos de sinonímia, antonímia e homonímia e mecanismos de representação de diferentes vozes (discurso direto e indireto).", "o": "Semântica Coesão"}, {"a": "6", "t": "3", "c": "EF69LP14", "e": "", "h": "Formular perguntas e decompor, com a ajuda dos colegas e dos professores, tema/questão polêmica, explicações e ou argumentos relativos ao objeto de discussão para análise mais minuciosa e buscar em fontes diversas informações ou dados que permitam analisar partes da questão e compartilhá-los com a turma.", "o": "Participação em discussões orais de temas controversos de interesse da turma e/ou de relevância social"}, {"a": "6", "t": "3", "c": "EF67LP14/ES", "e": "", "h": "Definir o contexto de produção da entrevista (objetivos, o que se pretende conseguir, porque aquele entrevistado etc.), levantar informações sobre o entrevistado e sobre o acontecimento ou tema em questão, preparar o roteiro de perguntar e realizar entrevista oral com envolvidos ou especialistas relacionados com o fato noticiado ou com o tema em pauta, usando roteiro previamente elaborado e formulando outras perguntas a partir das respostas dadas e, quando for o caso, selecionar partes, transcrever e proceder a uma edição escrita do texto, adequando-o a seu contexto de publicação, à construção composicional do gênero e garantindo a relevância das informações mantidas e a continuidade temática.", "o": "Planejamento e produção de entrevistas orais."}, {"a": "6", "t": "3", "c": "EF67LP27/ES", "e": "", "h": "Analisar, entre os textos literários e entre estes e outras manifestações artísticas (como cinema, teatro, música, artes visuais e midiáticas), referências explícitas ou implícitas a outros textos, quanto aos temas, personagens e recursos literários e semióticos.", "o": "Relação entre textos."}, {"a": "6", "t": "3", "c": "EF67LP29/ES", "e": "", "h": "Identificar, em texto dramático (de autores diversos, com ênfase em autores regionais), personagem, ato, cena, fala e indicações cênicas e a organização do texto: enredo, conflitos, ideias principais, pontos de vista, universos de referência.", "o": "Reconstrução da textualidade. Efeitos de sentido provocados pelos usos de recursos linguísticos e multissemióticos"}, {"a": "6", "t": "3", "c": "EF69LP39", "e": "", "h": "Definir o recorte temático da entrevista e o entrevistado, levantar informações sobre o entrevistado e sobre o tema da entrevista, elaborar roteiro de perguntas, realizar entrevista, a partir do roteiro, abrindo possibilidades para fazer perguntas a partir da resposta, se o contexto permitir, tomar nota, gravar ou salvar a entrevista e usar adequadamente as informações obtidas, de acordo com os objetivos estabelecidos.", "o": "Estratégias de produção"}, {"a": "6", "t": "3", "c": "EF69LP42", "e": "", "h": "Analisar a construção composicional dos textos pertencentes a gêneros relacionados à divulgação de conhecimentos: título, (olho), introdução, divisão do texto em subtítulos, imagens ilustrativas de conceitos, relações, ou resultados complexos (fotos, ilustrações, esquemas, gráficos, infográficos, diagramas, figuras, tabelas, mapas) etc., exposição, contendo definições, descrições, comparações, enumerações, exemplificações e remissões a conceitos e relações por meio de notas de rodapé, boxes ou links; ou título, contextualização do campo, ordenação temporal ou temática por tema ou subtema, intercalação de trechos verbais com fotos, ilustrações, áudios, vídeos etc. e reconhecer traços da linguagem dos textos de divulgação científica, fazendo uso consciente das estratégias de impessoalização da linguagem (ou de pessoalização, se o tipo de publicação e objetivos assim o demandarem, como em alguns podcasts e vídeos de divulgação científica), 3ª pessoa, presente atemporal, recurso à citação, uso de vocabulário técnico/especializado etc., como forma de ampliar suas capacidades de compreensão e produção de textos nesses gêneros.", "o": "Construção composicional e estilo."}, {"a": "7", "t": "1", "c": "EF07LP01", "e": "", "h": "Distinguir diferentes propostas editoriais – sensacionalismo, jornalismo investigativo etc. –, de forma a identificar os recursos utilizados para impactar/chocar o leitor que podem comprometer uma análise crítica da notícia e do fato noticiado. ✓ Notícia (manchete/título)", "o": "Reconstrução do contexto de produção, circulação e recepção de textos"}, {"a": "7", "t": "1", "c": "EF07LP02", "e": "", "h": "Comparar notícias e reportagens, sobre um mesmo fato divulgadas em diferentes mídias, analisando as especificidades das mídias, os processos de (re)elaboração dos textos e a convergência das mídias em notícias ou reportagens multissemióticas. ✓ Notícia (lead)", "o": "Caracterização do campo jornalístico e relação entre os gêneros em circulação, mídias e práticas da cultura digital."}, {"a": "7", "t": "1", "c": "EF07LP03/ES", "e": "", "h": "Formar, com base em palavras primitivas, palavras derivadas com os prefixos e sufixos mais produtivos no português.", "o": "Léxico/morfologia"}, {"a": "7", "t": "1", "c": "EF67LP03", "e": "", "h": "Comparar informações sobre um mesmo fato divulgadas em diferentes veículos e mídias, analisando e avaliando a confiabilidade refletindo sobre parcialidade/imparcialidade em textos dessa esfera. ✓ Notícia (corpo da notícia)", "o": "Relação entre textos."}, {"a": "7", "t": "1", "c": "EF07LP04", "e": "", "h": "Reconhecer, em textos, o verbo como o núcleo das orações à luz das práticas de leitura e produção de texto, com foco na construção do sentido. • Núcleo do verbo (foco na manchete)", "o": "Morfossintaxe"}, {"a": "7", "t": "1", "c": "EF07LP05/ES", "e": "", "h": "Identificar, em orações de textos lidos ou de produção própria, verbos de predicação completa e incompleta: intransitivos e transitivos, à luz das práticas de leitura e produção de texto, com foco na construção do sentido. ✓ Transitividade verbal (foco no subtítulo/olho da notícia/ lead) - Verbos de ligação e Intransitivo", "o": "Morfossintaxe."}, {"a": "7", "t": "1", "c": "EF67LP06", "e": "", "h": "Identificar os efeitos de sentido provocados pela seleção lexical, topicalização de elementos e seleção e hierarquização de informações, uso de 3ª pessoa etc.", "o": "Efeitos de sentido."}, {"a": "7", "t": "1", "c": "EF07LP06", "e": "", "h": "Empregar as regras básicas de concordância nominal e verbal em situações comunicativas e na produção de textos. ✓ Concordância Verbal e Nominal (foco no corpo da notícia)", "o": "Morfossintaxe."}, {"a": "7", "t": "1", "c": "EF67LP08", "e": "", "h": "Identificar os efeitos de sentido devidos à escolha de imagens estáticas, sequenciação ou sobreposição de imagens, definição de figura/fundo, ângulo, profundidade e foco, cores/tonalidades, relação com o escrito (relações de reiteração, complementação ou oposição), etc. em notícias, reportagens, fotorreportagens, foto-denúncias, memes, gifs, anúncios publicitários e propagandas publicados em jornais, revistas, sites na internet etc. ✓ Notícia (manchete/título)", "o": "Efeitos de sentido Exploração da multissemiose"}, {"a": "7", "t": "1", "c": "EF07LP10", "e": "", "h": "Utilizar, ao produzir texto, conhecimentos linguísticos e gramaticais: modos e tempos verbais, concordância nominal e verbal, pontuação etc., evitando a perspectiva do “erro gramatical”, em favor de uma abordagem baseada na adequação do uso.", "o": "Morfossintaxe."}, {"a": "7", "t": "1", "c": "EF67LP25", "e": "", "h": "Reconhecer e utilizar os critérios de organização tópica (do geral para o específico, do específico para o geral etc.), as marcas linguísticas dessa organização (marcadores de ordenação e enumeração, de explicação, definição e exemplificação, por exemplo) e os mecanismos de paráfrase, de maneira a organizar mais adequadamente a coesão e a", "o": "Textualização. Progressão temática."}, {"a": "7", "t": "1", "c": "EF69LP29", "e": "", "h": "Refletir sobre a relação entre os contextos de produção dos gêneros de divulgação científica – texto didático, artigo de divulgação científica, reportagem de divulgação científica, verbete de enciclopédia (impressa e digital), esquema, infográfico (estático e animado), relatório, relato multimidiático de campo, podcasts e vídeos variados de divulgação científica etc. – e os aspectos relativos à construção composicional e às marcas linguísticas características desses gêneros, de forma a ampliar suas possibilidades de compreensão (e produção) de textos pertencentes a esses gêneros.", "o": "Reconstrução das condições de produção e recepção dos textos e adequação do texto à construção composicional e ao estilo de gênero"}, {"a": "7", "t": "1", "c": "EF67LP35/ES", "e": "", "h": "Distinguir palavras derivadas por acréscimo de afixos e palavras compostas à luz das práticas de leitura, produção ou oralidade.", "o": "Léxico/morfologia."}, {"a": "7", "t": "1", "c": "EF67LP35", "e": "", "h": "Distinguir palavras derivadas por acréscimo de afixos e palavras compostas à luz das práticas de leitura, produção ou oralidade.", "o": "Léxico/morfologia"}, {"a": "7", "t": "1", "c": "EF69LP36", "e": "", "h": "Produzir, revisar e editar textos voltados para a divulgação do conhecimento e de dados e resultados de pesquisas, tais como artigos de divulgação científica, verbete de enciclopédia, infográfico, infográfico animado, podcast ou vlog científico, relato de experimento, relatório, relatório multimidiático de campo, dentre outros, considerando o contexto de produção e as regularidades dos gêneros em termos de suas construções composicionais e estilos.", "o": "Estratégias de escrita: textualização, revisão e edição."}, {"a": "7", "t": "2", "c": "EF07LP07", "e": "", "h": "Identificar, em textos lidos ou de produção própria, a estrutura básica da oração: sujeito, predicado, complemento (objetos direto e indireto) com foco nos efeitos de sentido, contribuindo para uma compreensão global, do papel da sintaxe no funcionamento da língua.", "o": "Morfossintaxe."}, {"a": "7", "t": "2", "c": "EF07LP12/ES", "e": "", "h": "Reconhecer recursos de coesão referencial: substituições lexicais (de substantivos por sinônimos, hiperônimos, elipse) ou pronominais (uso de pronomes anafóricos – pessoais, possessivos, demonstrativos), considerando a legibilidade do texto, as intenções de significação e as possibilidades de compreensão do interlocutor.", "o": "Semântica Coesão"}, {"a": "7", "t": "2", "c": "EF07LP13", "e": "", "h": "Estabelecer relações entre partes do texto, identificando substituições lexicais (de substantivos por sinônimos) ou pronominais (uso de pronomes anafóricos – pessoais, possessivos, demonstrativos), que contribuem para a continuidade do texto.", "o": "Semântica Coesão"}, {"a": "7", "t": "2", "c": "EF67LP28", "e": "", "h": "Ler, de forma autônoma, e compreender – selecionando procedimentos e estratégias de leitura adequados a diferentes objetivos e levando em conta características dos gêneros e suportes –, romances infanto-juvenis, contos populares, contos de terror, lendas brasileiras, indígenas e africanas, narrativas de aventuras, narrativas de enigma, mitos, crônicas, autobiografias, histórias em quadrinhos, mangás, poemas de forma livre e fixa (como sonetos e cordéis), vídeo-poemas, poemas visuais, dentre outros, expressando avaliação sobre o texto lido e estabelecendo preferências por gêneros, temas, autores.", "o": "Estratégias de leitura. Apreciação e réplica"}, {"a": "7", "t": "2", "c": "EF67LP36", "e": "", "h": "Utilizar, ao produzir texto, recursos de coesão referencial (léxica e pronominal) e sequencial e outros recursos expressivos adequados ao gênero textual.", "o": "Semântica Coesão"}, {"a": "7", "t": "2", "c": "EF69LP54", "e": "", "h": "Analisar os efeitos de sentido decorrentes da interação entre os elementos linguísticos e os recursos paralinguísticos e cinésicos, como as variações no ritmo, as modulações no tom de voz, as pausas, as manipulações do estrato sonoro da linguagem, obtidos por meio da estrofação, das rimas e de figuras de linguagem como as aliterações, as assonâncias, as onomatopeias, dentre outras, a postura corporal e a gestualidade, na declamação de poemas, apresentações musicais e teatrais, tanto em gêneros em prosa quanto nos gêneros poéticos, os efeitos de sentido decorrentes do emprego de figuras de linguagem, tais como comparação, metáfora, personificação, metonímia, hipérbole, eufemismo, ironia, paradoxo e antítese e os efeitos de sentido decorrentes do emprego de palavras e expressões denotativas e conotativas (adjetivos, locuções adjetivas, orações subordinadas adjetivas etc.), que funcionam como modificadores, percebendo sua função na caracterização dos espaços, tempos, personagens e ações próprios de cada gênero narrativo.", "o": "Recursos linguísticos e semióticos que operam nos textos pertencentes aos gêneros literários."}, {"a": "7", "t": "3", "c": "EF67LP04", "e": "", "h": "Distinguir, em segmentos descontínuos de textos, fato da opinião enunciada em relação a esse mesmo fato.", "o": "Estratégias de leitura Distinção de fato e opinião"}, {"a": "7", "t": "3", "c": "EF67LP05", "e": "", "h": "Identificar e avaliar teses, opiniões, posicionamentos explícitos e argumentos em textos argumentativos (carta de leitor, comentário, artigo de opinião, resenha crítica etc.), manifestando concordância ou discordância.", "o": "Estratégias de leitura: identificação de teses e argumentos Apreciação e réplica"}, {"a": "7", "t": "3", "c": "EF07LP08/ES", "e": "", "h": "Identificar, em textos lidos ou de produção própria, adjetivos que ampliam o sentido do substantivo sujeito ou complemento verbal com foco nos efeitos de sentido que podem se associar às estruturas sintáticas em estudo.", "o": "Morfossintaxe."}, {"a": "7", "t": "3", "c": "EF07LP09/ES", "e": "", "h": "Identificar, em textos lidos ou de produção própria, advérbios e locuções adverbiais que ampliam o sentido do verbo núcleo da oração com foco nos efeitos de sentido que podem se associar às estruturas sintáticas em estudo.", "o": "Morfossintaxe."}, {"a": "7", "t": "3", "c": "EF67LP15", "e": "", "h": "Identificar a proibição imposta ou o direito garantido, bem como as circunstâncias de sua aplicação, em artigos relativos a normas, regimentos escolares, regimentos e estatutos da sociedade civil, regulamentações para o mercado publicitário, Código de Defesa do Consumidor, Código Nacional de Trânsito, ECA, Constituição, dentre outros.", "o": "Estratégias e procedimentos de leitura em textos legais e normativos"}, {"a": "7", "t": "3", "c": "EF67LP16", "e": "", "h": "Explorar e analisar espaços de reclamação de direitos e de envio de solicitações (tais como ouvidorias, SAC, canais ligados a órgãos públicos, plataformas do consumidor, plataformas de reclamação), bem como de textos pertencentes a gêneros que circulam nesses espaços, reclamação ou carta de reclamação, solicitação ou carta de solicitação, como forma de ampliar as possibilidades de produção desses textos em casos que remetam a reivindicações que envolvam a escola, a comunidade ou algum de seus membros como forma de se engajar na busca de solução de problemas pessoais, dos outros e coletivos.", "o": "Contexto de produção, circulação e recepção de textos e práticas relacionadas à defesa de direitos e à participação social."}, {"a": "7", "t": "3", "c": "EF67LP17", "e": "", "h": "Analisar, a partir do contexto de produção, a forma de organização das cartas de solicitação e de reclamação (datação, forma de início, apresentação contextualizada do pedido ou da reclamação, em geral, acompanhada de explicações, argumentos e/ou relatos do problema, fórmula de finalização mais ou menos cordata, dependendo do tipo", "o": "Relação entre contexto de produção e características composicionais e estilísticas dos gêneros (carta de solicitação, carta de reclamação, petição on-line, carta aberta, abaixoassinado, proposta etc.) Apreciação e réplica"}, {"a": "7", "t": "3", "c": "EF67LP18/ES", "e": "", "h": "Identificar o objeto da reclamação e/ou da solicitação e sua sustentação, explicação ou justificativa, de forma a poder analisar a pertinência da solicitação ou justificação, prevendo o levantamento e a discussão de questões polêmicas locais.", "o": "Estratégias, procedimentos de leitura em textos reivindicatórios ou propositivos."}, {"a": "7", "t": "3", "c": "EF69LP20", "e": "", "h": "Identificar, tendo em vista o contexto de produção, a forma de organização dos textos normativos e legais, a lógica de hierarquização de seus itens e subitens e suas partes: parte inicial (título – nome e data – e ementa), blocos de artigos (parte, livro, capítulo, seção, subseção), artigos (caput e parágrafos e incisos) e parte final (disposições pertinentes à sua implementação) e analisar efeitos de sentido causados pelo uso de vocabulário técnico, pelo uso do imperativo, de palavras e expressões que indicam circunstâncias, como advérbios e locuções adverbiais, de palavras que indicam generalidade, como alguns pronomes indefinidos, de forma a poder compreender o caráter imperativo, coercitivo e generalista das leis e de outras formas de regulamentação.", "o": "Reconstrução das condições de produção e circulação e adequação do texto à construção composicional e ao estilo de gênero (Lei, código, estatuto, código, regimento etc.)"}, {"a": "7", "t": "3", "c": "EF69LP22", "e": "", "h": "Produzir, revisar e editar textos reivindicatórios ou propositivos sobre problemas que afetam a vida escolar ou da comunidade, justificando pontos de vista, reivindicações e detalhando propostas (justificativa, objetivos, ações previstas etc.), levando em conta seu contexto de produção e as características dos gêneros em questão.", "o": "Textualização, revisão e edição"}, {"a": "7", "t": "3", "c": "EF69LP24", "e": "", "h": "Discutir casos, reais ou simulações, submetidos a juízo, que envolvam (supostos) desrespeitos a artigos, do ECA, do Código de Defesa do Consumidor, do Código Nacional de Trânsito, de regulamentações do mercado publicitário etc., como forma de criar familiaridade com textos legais – seu vocabulário, formas de organização, marcas de estilo etc. -, de maneira a facilitar a compreensão de leis, fortalecer a defesa de direitos, fomentar a escrita de textos normativos (se e quando isso for necessário) e possibilitar a compreensão do caráter interpretativo das leis e as várias perspectivas que podem estar em jogo.", "o": "Discussão oral."}, {"a": "7", "t": "3", "c": "EF69LP25", "e": "", "h": "Posicionar-se de forma consistente e sustentada em uma discussão, assembleia, reuniões de colegiados da escola, de agremiações e outras situações de apresentação de propostas e defesas de opiniões, respeitando as opiniões contrárias e propostas alternativas e fundamentando seus posicionamentos, no tempo de fala previsto, valendo-se de sínteses e propostas claras e justificadas.", "o": "Discussão oral"}, {"a": "7", "t": "3", "c": "EF69LP27", "e": "", "h": "Analisar a forma composicional de textos pertencentes a gêneros normativos/ jurídicos e a gêneros da esfera política, tais como propostas, programas políticos (posicionamento quanto a diferentes ações a serem propostas, objetivos, ações previstas etc.), propaganda política (propostas e sua sustentação, posicionamento quanto a temas em discussão) e textos reivindicatórios: cartas de reclamação, petição (proposta, suas justificativas e ações a serem adotadas) e suas marcas linguísticas, de forma a complementarizar a compreensão de textos pertencentes a esses gêneros e a possibilitar a produção de textos mais adequados e/ou fundamentados, quando isso for requerido.", "o": "Análise de textos legais/normativos, propositivos e reivindicatórios."}, {"a": "8", "t": "1", "c": "EF08LP01", "e": "", "h": "Identificar e comparar os vários editoriais de jornais impressos e digitais e de sites noticiosos, de forma a refletir sobre os tipos de fato que são noticiados e comentados, as escolhas sobre o que noticiar e o que não noticiar e o destaque/enfoque dado e a fidedignidade da informação.", "o": "Caracterização do campo jornalístico e relação entre os gêneros em circulação, mídias e práticas da cultura digital"}, {"a": "8", "t": "1", "c": "EF08LP04", "e": "", "h": "Utilizar, ao produzir texto, conhecimentos linguísticos e gramaticais: ortografia, regências e concordâncias nominal e verbal, modos e tempos verbais, pontuação etc.", "o": "Fono-ortografia."}, {"a": "8", "t": "1", "c": "EF08LP06/ES", "e": "", "h": "Identificar, em textos lidos ou de produção própria, os termos constitutivos da oração (sujeito e seus modificadores, verbo e seus complementos e modificadores) com foco nos efeitos de sentido que podem se associar às estruturas sintáticas em estudo.", "o": "Morfossintaxe."}, {"a": "8", "t": "1", "c": "EF89LP07", "e": "", "h": "Analisar, em notícias, reportagens e peças publicitárias em várias mídias, os efeitos de sentido devidos ao tratamento e à composição dos elementos nas imagens em movimento, à performance, à montagem feita (ritmo, duração e sincronização entre as linguagens – complementaridades, interferências etc.) e ao ritmo, melodia, instrumentos e sampleamentos das músicas e efeitos sonoros.", "o": "Efeitos de sentido Exploração da multissemiose"}, {"a": "8", "t": "1", "c": "EF89LP08", "e": "", "h": "Planejar reportagem impressa e em outras mídias (rádio ou TV/vídeo, sites), tendo em vista as condições de produção do texto – objetivo, leitores/espectadores, veículos e mídia de circulação etc. – a partir da escolha do fato a ser aprofundado ou do tema a ser focado (de relevância para a turma, escola ou comunidade), do levantamento de dados e informações sobre o fato ou tema – que pode envolver entrevistas com envolvidos ou com especialistas, consultas a fontes diversas, análise de documentos, cobertura de eventos etc. -, do registro dessas informações e dados, da escolha de fotos ou imagens a produzir ou a utilizar etc., da produção de infográficos, quando for o caso, e da organização hipertextual (no caso a publicação em sites ou blogs noticiosos ou mesmo de jornais impressos, por meio de boxes variados).", "o": "Estratégia de produção: planejamento de textos informativos."}, {"a": "8", "t": "1", "c": "EF89LP09", "e": "", "h": "Produzir reportagem impressa, com título, linha fina (optativa), organização composicional (expositiva, interpretativa e/ ou opinativa), progressão temática e uso de recursos linguísticos compatíveis com as escolhas feitas e reportagens multimidiáticas, tendo em vista as condições de produção, as características do gênero, os recursos e mídias disponíveis, sua organização hipertextual e o manejo adequado de recursos de captação e edição de áudio e imagem e adequação à norma-padrão.", "o": "Estratégias de produção: textualização de textos informativos."}, {"a": "8", "t": "1", "c": "EF69LP29", "e": "", "h": "Refletir sobre a relação entre os contextos de produção dos gêneros de divulgação científica – texto didático, artigo de divulgação científica, reportagem de divulgação científica, verbete de enciclopédia (impressa e digital), esquema, infográfico (estático e animado), relatório, relato multimidiático de campo, podcasts e vídeos variados de divulgação científica etc. – e os aspectos relativos à construção composicional e às marcas linguísticas características desses gêneros, de forma a ampliar suas possibilidades de compreensão (e produção) de textos pertencentes a esses gêneros.", "o": "Reconstrução das condições de produção e recepção dos textos e adequação do texto à construção composicional e ao estilo de gênero."}, {"a": "8", "t": "1", "c": "EF69LP33", "e": "", "h": "Articular o verbal com os esquemas, infográficos, imagens variadas etc. na (re)construção dos sentidos dos textos de divulgação científica e retextualizar do discursivo para o esquemático – infográfico, esquema, tabela, gráfico, ilustração etc. – e, ao contrário, transformar o conteúdo das tabelas, esquemas, infográficos, ilustrações etc. em texto discursivo, como forma de ampliar as possibilidades de compreensão desses textos e analisar as características das multissemioses e dos gêneros em questão.", "o": "Estratégias e procedimentos de leitura / Relação do verbal com outras semioses. Procedimentos e gêneros de apoio à compreensão."}, {"a": "8", "t": "1", "c": "EF69LP37", "e": "", "h": "Produzir roteiros para elaboração de vídeos de diferentes tipos (vlog científico, vídeominuto, programa de rádio, podcasts) para divulgação de conhecimentos científicos e resultados de pesquisa, tendo em vista seu contexto de produção, os elementos e a construção composicional dos roteiros.", "o": "Estratégias de produção."}, {"a": "8", "t": "1", "c": "EF69LP42", "e": "", "h": "Analisar a construção composicional dos textos pertencentes a gêneros relacionados à divulgação de conhecimentos: título, (olho), introdução, divisão do texto em subtítulos, imagens ilustrativas de conceitos, relações, ou resultados complexos (fotos, ilustrações, esquemas, gráficos, infográficos, diagramas, figuras, tabelas, mapas) etc., exposição, contendo definições, descrições, comparações, enumerações, exemplificações e remissões a conceitos e relações por meio de notas de rodapé, boxes ou links; ou título, contextualização do campo, ordenação temporal ou temática por tema ou subtema, intercalação de trechos verbais com fotos, ilustrações, áudios, vídeos etc. e reconhecer traços da linguagem dos textos de divulgação científica, fazendo uso consciente das estratégias de impessoalização da linguagem (ou de pessoalização, se o tipo de publicação e objetivos assim o demandarem, como em alguns podcasts e vídeos de divulgação científica), 3ª pessoa, presente atemporal, recurso à citação, uso de vocabulário técnico/especializado etc., como forma de ampliar suas capacidades de compreensão e produção de textos nesses gêneros.", "o": "Construção composicional e estilo."}, {"a": "8", "t": "2", "c": "EF69LP01", "e": "", "h": "Diferenciar liberdade de expressão de discursos de ódio, posicionando-se contrariamente a esse tipo de discurso e vislumbrando possibilidades de denúncia, quando for o caso.", "o": "Apreciação e réplica Relação entre gêneros e mídias."}, {"a": "8", "t": "2", "c": "EF08LP02/ES", "e": "", "h": "Analisar diferentes práticas (curtir, compartilhar, comentar, curar etc.) e textos pertencentes a diferentes gêneros da cultura digital (meme, gif, comentário, charge digital etc.) envolvidos no trato com a informação e opinião, de forma a possibilitar uma presença mais crítica e ética nas redes, considerando a proposta editorial dos veículos em que circulam e a sua natureza.", "o": "Relação entre textos."}, {"a": "8", "t": "2", "c": "EF89LP03", "e": "", "h": "Analisar textos de opinião (artigos de opinião, editoriais, cartas de leitores, comentários, posts de blog e de redes sociais, charges, memes, gifs etc.) e posicionar-se de forma crítica e fundamentada, ética e respeitosa frente a fatos e opiniões relacionados a esses textos.", "o": "Estratégias de leitura: aprender os sentidos globais do texto Apreciação e réplica"}, {"a": "8", "t": "2", "c": "EF08LP07", "e": "", "h": "Diferenciar, em textos lidos ou de produção própria, complementos diretos e indiretos de verbos transitivos, apropriando-se da regência de verbos de uso frequente.", "o": "Morfossintaxe."}, {"a": "8", "t": "2", "c": "EF08LP08/ES", "e": "", "h": "Identificar, em textos lidos ou de produção própria, verbos na voz ativa e na voz passiva, interpretando os efeitos de sentido de sujeito ativo e passivo (agente da passiva), refletindo sobre o estudo comparativo de enunciados organizados na voz passiva e na ativa e analisando os efeitos de sentido decorrentes dessa organização sintática.", "o": "Morfossintaxe."}, {"a": "8", "t": "2", "c": "EF08LP10", "e": "", "h": "Interpretar, em textos lidos ou de produção própria, efeitos de sentido de modificadores do verbo (adjuntos adverbiais, advérbios e expressões adverbiais), usando-os para enriquecer seus próprios textos.", "o": "Morfossintaxe."}, {"a": "8", "t": "2", "c": "EF69LP30", "e": "", "h": "Comparar, com a ajuda do professor, conteúdos, dados e informações de diferentes fontes, levando em conta seus contextos de produção e referências, identificando coincidências, complementaridades e contradições, de forma a poder identificar erros/imprecisões conceituais, compreender e posicionar-se criticamente sobre os conteúdos e informações em questão.", "o": "Relação entre textos."}, {"a": "8", "t": "3", "c": "EF08LP03", "e": "", "h": "Produzir artigos de opinião, tendo em vista o contexto de produção dado, a defesa de um ponto de vista, utilizando argumentos e contra-argumentos e articuladores de coesão que marquem relações de oposição, contraste, exemplificação, ênfase.", "o": "Textualização de textos argumentativos e apreciativos."}, {"a": "8", "t": "3", "c": "EF89LP04/ES", "e": "", "h": "Identificar e avaliar teses, opiniões, posicionamentos explícitos e implícitos, argumentos e contra-argumentos em textos argumentativos do campo (carta de leitor, comentário, artigo de opinião, resenha crítica etc.), posicionando-se frente à questão controversa de forma sustentada, a partir de conhecimentos prévios.", "o": "Estratégias de leitura: aprender os sentidos globais do texto Apreciação e réplica."}, {"a": "8", "t": "3", "c": "EF89LP06/ES", "e": "", "h": "Analisar o uso de recursos persuasivos em textos argumentativos diversos (como a elaboração do título, escolhas lexicais, construções metafóricas, a explicitação ou a ocultação de fontes de informação) compreendendo seus efeitos de sentido.", "o": "Efeitos de sentido."}, {"a": "8", "t": "3", "c": "EF08LP13", "e": "", "h": "Inferir efeitos de sentido decorrentes do uso de recursos de coesão sequencial: conjunções e articuladores textuais.", "o": "Morfossintaxe."}, {"a": "8", "t": "3", "c": "EF08LP14/ES", "e": "", "h": "Utilizar, ao produzir texto, recursos de coesão sequencial (articuladores) e referencial (léxica e pronominal), construções passivas e impessoais, discurso direto e indireto e outros recursos expressivos adequados ao gênero textual à luz das práticas de oralidade, leitura ou escrita de textos dos gêneros previstos para estudo.", "o": "Semântica."}, {"a": "8", "t": "3", "c": "EF08LP15", "e": "", "h": "Estabelecer relações entre partes do texto, identificando o antecedente de um pronome relativo ou o referente comum de uma cadeia de substituições lexicais.", "o": "Coesão."}, {"a": "8", "t": "3", "c": "EF89LP31", "e": "", "h": "Analisar e utilizar modalização epistêmica, isto é, modos de indicar uma avaliação sobre o valor de verdade e as condições de verdade de uma proposição, tais como os asseverativos – quando se concorda com (realmente, evidentemente, naturalmente, efetivamente, claro, certo, lógico, sem dúvida etc.) ou discorda de (de jeito nenhum, de forma alguma) uma ideia; e os quase asseverativos, que indicam que se considera o conteúdo como quase certo (talvez, assim, possivelmente, provavelmente, eventualmente)", "o": "Modalização."}, {"a": "8", "t": "3", "c": "EF89LP33", "e": "", "h": "Ler, de forma autônoma, e compreender – selecionando procedimentos e estratégias de leitura adequados a diferentes objetivos e levando em conta características dos gêneros e suportes – romances, contos contemporâneos, minicontos, fábulas contemporâneas, romances juvenis, biografias romanceadas, novelas, crônicas visuais, narrativas de ficção científica, narrativas de suspense, poemas de forma livre e fixa (como haicai), poema concreto, ciberpoema, dentre outros, expressando avaliação sobre o texto lido e estabelecendo preferências por gêneros, temas, autores.", "o": "Estratégias de leitura Apreciação e réplica."}, {"a": "8", "t": "3", "c": "EF89LP35", "e": "", "h": "Criar contos ou crônicas (em especial, líricas), crônicas visuais, minicontos, narrativas de aventura e de ficção científica, dentre outros, com temáticas próprias ao gênero, usando os conhecimentos sobre os constituintes estruturais e recursos expressivos típicos dos gêneros narrativos pretendidos, e, no caso de produção em grupo, ferramentas de escrita colaborativa.", "o": "Construção da textualidade."}, {"a": "8", "t": "3", "c": "EF69LP47", "e": "", "h": "Analisar, em textos narrativos ficcionais, as diferentes formas de composição próprias de cada gênero, os recursos coesivos que constroem a passagem do tempo e articulam suas partes, a escolha lexical típica de cada gênero para a caracterização dos cenários e dos personagens e os efeitos de sentido decorrentes dos tempos verbais, dos tipos de discurso, dos verbos de enunciação e das variedades linguísticas (no discurso direto, se houver) empregados, identificando o enredo e o foco narrativo e percebendo como se estrutura a narrativa nos diferentes gêneros e os efeitos de sentido decorrentes do foco narrativo típico de cada gênero, da caracterização dos espaços físico e psicológico e dos tempos cronológico e psicológico, das diferentes vozes no texto (do narrador, de personagens em discurso direto e indireto), do uso de pontuação expressiva, palavras e expressões conotativas e processos figurativos e do uso de recursos linguísticogramaticais próprios a cada gênero narrativo.", "o": "Reconstrução da textualidade e compreensão dos efeitos de sentidos provocados pelos usos de recursos linguísticos e multissemióticos."}, {"a": "9", "t": "1", "c": "EF89LP03/ES", "e": "", "h": "Analisar textos de opinião (artigos de opinião, editoriais, cartas de leitores, comentários, posts de blog e de redes sociais, charges, memes, gifs etc.) e posicionar-se de forma crítica e fundamentada, ética e respeitosa frente a fatos e opiniões relacionados a esses textos.", "o": "Estratégia de leitura: apreender os sentidos globais do texto Apreciação e réplica."}, {"a": "9", "t": "1", "c": "EF09LP03", "e": "", "h": "Produzir artigos de opinião, tendo em vista o contexto de produção dado, assumindo posição diante de tema polêmico, argumentando de acordo com a estrutura própria desse tipo de texto e utilizando diferentes tipos de argumentos – de autoridade, comprovação, exemplificação princípio etc.", "o": "Textualização de textos argumentativos e apreciativos."}, {"a": "9", "t": "1", "c": "EF89LP04", "e": "", "h": "Identificar e avaliar teses, opiniões, posicionamentos explícitos e implícitos, argumentos e contra-argumentos em textos argumentativos do campo (carta de leitor, comentário, artigo de opinião, resenha crítica etc.), posicionando-se frente à questão controversa de forma sustentada.", "o": "Estratégia de leitura: apreender os sentidos globais do texto Apreciação e réplica"}, {"a": "9", "t": "1", "c": "EF09LP04/ES", "e": "", "h": "Escrever textos corretamente, de acordo com a norma- padrão, com estruturas sintáticas complexas no nível da oração e do período à luz das práticas de leitura e/ou produção de textos dos mais diversos gêneros e campos de atuação.", "o": "Fono-ortografia."}, {"a": "9", "t": "1", "c": "EF09LP05/ES", "e": "", "h": "Identificar, em textos lidos e em produções próprias, orações com a estrutura sujeito - verbo de ligação - predicativo, associando essas análises à leitura e à produção de textos, com foco nos efeitos de sentido que podem se relacionar às estruturas sintáticas em estudo.", "o": "Morfossintaxe."}, {"a": "9", "t": "1", "c": "EF09LP06/ES", "e": "", "h": "Diferenciar, em textos lidos e em produções próprias, o efeito de sentido do uso dos verbos de ligação “ser”, “estar”, “ficar”, “parecer” e “permanecer”, dentre outros, com foco nos efeitos de sentido que podem se concatenar às estruturas sintáticas em estudo.", "o": "Morfossintaxe."}, {"a": "9", "t": "1", "c": "EF09LP08/ES", "e": "", "h": "Identificar, em textos lidos e em produções próprias, a relação que conjunções (e locuções conjuntivas) coordenativas e subordinativas estabelecem entre as orações que conectam, focalizando diferentes possibilidades de articulação dos trechos, e considerando tanto a legibilidade do texto, como as intenções de significação e as possibilidades de compreensão do interlocutor.", "o": "Morfossintaxe."}, {"a": "9", "t": "1", "c": "EF69LP08", "e": "", "h": "Revisar/editar o texto produzido – notícia, reportagem, resenha, artigo de opinião, dentre outros –, tendo em vista sua adequação ao contexto de produção, a mídia em questão, características do gênero, aspectos relativos à textualidade, a relação entre as diferentes semioses, a formatação e uso adequado das ferramentas de edição (de texto, foto, áudio e vídeo, dependendo do caso) e adequação à norma culta.", "o": "Revisão/edição de texto informativo e opinativo."}, {"a": "9", "t": "1", "c": "EF09LP09/ES", "e": "", "h": "Identificar efeitos de sentido do uso de orações adjetivas restritivas e explicativas em um período composto, considerando a legibilidade do texto, as intenções de significação e as possibilidades de compreensão do interlocutor.", "o": "Morfologia."}, {"a": "9", "t": "1", "c": "EF89LP10", "e": "", "h": "Planejar artigos de opinião, tendo em vista as condições de produção do texto – objetivo, leitores/espectadores, veículos e mídia de circulação etc. –, a partir da escolha do tema ou questão a ser discutido(a), da relevância para a turma, escola ou comunidade, do levantamento de dados e informações sobre a questão, de argumentos relacionados a diferentes posicionamentos em jogo, da definição – o que pode envolver consultas a fontes diversas, entrevistas com especialistas, análise de textos, organização esquemática das informações e argumentos – dos (tipos de) argumentos e estratégias que pretende utilizar para convencer os leitores", "o": "Estratégia de produção: planejamento de textos argumentativos e apreciativos."}, {"a": "9", "t": "1", "c": "EF09LP11/ES", "e": "", "h": "Inferir efeitos de sentido decorrentes do uso de recursos de coesão sequencial (conjunções e articuladores textuais), focalizando as diferentes possibilidades de articulação de trechos de enunciados, considerando a legibilidade do texto, as intenções de significação e as possibilidades de compreensão do interlocutor, para, assim, recorrer à metalinguagem.", "o": "Coesão."}, {"a": "9", "t": "1", "c": "EF89LP14/ES", "e": "", "h": "Analisar, em textos argumentativos e propositivos, os movimentos argumentativos de sustentação, refutação e negociação e os tipos de argumentos, avaliando a força/ tipo dos argumentos utilizados em atividades permanentes de alimentação temática com reflexões sobre temas atuais e controversos.", "o": "Argumentação: movimentos argumentativos, tipos de argumento e força argumentativa."}, {"a": "9", "t": "1", "c": "EF89LP16", "e": "", "h": "Analisar a modalização realizada em textos noticiosos e argumentativos, por meio das modalidades apreciativas, viabilizadas por classes e estruturas gramaticais como adjetivos, locuções adjetivas, advérbios, locuções adverbiais, orações adjetivas e adverbiais, orações relativas restritivas e explicativas etc., de maneira a perceber a apreciação ideológica sobre os fatos noticiados ou as posições implícitas ou assumidas.", "o": "Modalização."}, {"a": "9", "t": "1", "c": "EF69LP18", "e": "", "h": "Utilizar, na escrita/reescrita de textos argumentativos, recursos linguísticos que marquem as relações de sentido entre parágrafos e enunciados do texto e operadores de conexão adequados aos tipos de argumento e à forma de composição de textos argumentativos, de maneira a garantir a coesão, a coerência e a progressão temática nesses textos (primeiramente, mas, no entanto, em primeiro/segundo/ terceiro lugar, finalmente, em conclusão etc.).", "o": "Estilo."}, {"a": "9", "t": "1", "c": "EF89LP21", "e": "", "h": "Realizar enquetes e pesquisas de opinião, de forma a levantar prioridades, problemas a resolver ou propostas que possam contribuir para melhoria da escola ou da comunidade, caracterizar emanda/necessidade, documentando-a de diferentes maneiras por meio de diferentes procedimentos, gêneros e mídias e, quando for o caso, selecionar informações e dados relevantes de fontes pertinentes diversas (sites, impressos, vídeos e outros), avaliando a qualidade e a utilidade dessas fontes, que possam servir de contextualização e fundamentação de propostas, de forma a justificar a sugestão de propostas, projetos culturais e ações de intervenção.", "o": "Estratégia de produção: planejamento de textos reivindicatórios ou propositivos.."}, {"a": "9", "t": "1", "c": "EF89LP23", "e": "", "h": "Analisar, em textos argumentativos, reivindicatórios e propositivos, os movimentos argumentativos utilizados (sustentação, refutação e negociação), avaliando a força dos argumentos utilizados.", "o": "Movimentos argumentativos e força dos argumentos."}, {"a": "9", "t": "2", "c": "EF69LP02", "e": "", "h": "Analisar e comparar peças publicitárias variadas (cartazes, folhetos, outdoor, anúncios e propagandas em diferentes mídias, spots, jingle, vídeos etc.), de forma a perceber a articulação entre elas em campanhas, as especificidades das várias semioses e mídias, a adequação dessas peças ao público-alvo, aos objetivos do anunciante e/ou da campanha e à construção composicional e estilo dos gêneros em questão, como forma de ampliar suas possibilidades de compreensão (e produção) de textos pertencentes a esses gêneros.", "o": "Apreciação e réplica Relação entre gêneros e mídias."}, {"a": "9", "t": "2", "c": "EF09LP10/ES", "e": "", "h": "Comparar as regras de colocação pronominal na norma- padrão com o seu uso no português brasileiro coloquial, selecionando as variedades linguísticas adequadas à situação comunicativa, repudiando qualquer preconceito linguístico relativo ao uso delas.", "o": "Coesão."}, {"a": "9", "t": "2", "c": "EF89LP11", "e": "", "h": "Produzir, revisar e editar peças e campanhas publicitárias, envolvendo o uso articulado e complementar de diferentes peças publicitárias: cartaz, banner, indoor, folheto, panfleto, anúncio de jornal/revista, para internet, spot, propaganda de rádio, TV, a partir da escolha da questão/problema/causa significativa para a escola e/ou a comunidade escolar, da definição do público-alvo, das peças que serão produzidas, das estratégias de persuasão e convencimento que serão utilizadas.", "o": "Estratégias de produção: planejamento e textualização e edição de textos publicitários."}, {"a": "9", "t": "2", "c": "EF89LP15", "e": "", "h": "Utilizar, nos debates, operadores argumentativos que marcam a defesa de ideia e de diálogo com a tese do outro: concordo, discordo, concordo parcialmente, do meu ponto de vista, na perspectiva aqui assumida etc.", "o": "Estilo."}, {"a": "9", "t": "2", "c": "EF89LP32", "e": "", "h": "Analisar os efeitos de sentido decorrentes do uso de mecanismos de intertextualidade (referências, alusões, retomadas) entre os textos literários, entre esses textos literários e outras manifestações artísticas (cinema, teatro, artes visuais e midiáticas, música), quanto aos temas, personagens, estilos, autores etc., e entre o texto original e paródias, paráfrases, pastiches, trailer honesto, vídeos-minuto, vidding, dentre outros.", "o": "Relação entre textos."}, {"a": "9", "t": "2", "c": "EF89LP37", "e": "", "h": "Analisar os efeitos de sentido do uso de figuras de linguagem como ironia, eufemismo, antítese, aliteração, assonância, dentre outras.", "o": "Figuras de linguagem."}, {"a": "9", "t": "3", "c": "EF09LP01", "e": "", "h": "Analisar o fenômeno da disseminação de notícias falsas nas redes sociais - a partir de experiências dos adolescentes nesses espaços - e desenvolver estratégias para reconhecê- las, a partir da verificação/avaliação do veículo, fonte, data e local da publicação, autoria, URL, da análise da formatação, da comparação de diferentes fontes, da consulta a sites de curadoria que atestam a fidedignidade do relato dos fatos e denunciam boatos etc.", "o": "Reconstrução do contexto de produção, circulação e recepção de textos Caracterização do campo jornalístico e relação entre os gêneros em circulação, mídias e práticas da cultura digital"}, {"a": "9", "t": "3", "c": "EF09LP02", "e": "", "h": "Analisar e comentar a cobertura da imprensa sobre fatos de relevância social, comparando diferentes enfoques por meio do uso de ferramentas de curadoria.", "o": "Relação entre textos."}, {"a": "9", "t": "3", "c": "EF09LP12", "e": "", "h": "Identificar estrangeirismos, caracterizando-os segundo a conservação, ou não, de sua forma gráfica de origem, avaliando a pertinência, ou não, de seu uso.", "o": "Variação linguística."}, {"a": "9", "t": "3", "c": "EF89LP13", "e": "", "h": "Planejar entrevistas orais com pessoas ligadas ao fato noticiado, especialistas etc., como forma de obter dados e informações sobre os fatos cobertos sobre o tema ou questão discutida ou temáticas em estudo, levando em conta o gênero e seu contexto de produção, partindo do levantamento de informações sobre o entrevistado e sobre a temática e da elaboração de um roteiro de perguntas, garantindo a relevância das informações mantidas e a continuidade temática, realizar entrevista e fazer edição em áudio ou vídeo, incluindo uma contextualização inicial e uma fala de encerramento para publicação da entrevista isoladamente ou como parte integrante de reportagem multimidiática, adequando-a a seu contexto de publicação e garantindo a relevância das informações mantidas e a continuidade temática.", "o": "Estratégias de produção: planejamento e realização e edição de entrevistas orais."}, {"a": "9", "t": "3", "c": "EF89LP17/ES", "e": "", "h": "Relacionar textos e documentos legais e normativos de importância universal, nacional ou local que envolvam direitos, em especial, de crianças, adolescentes e jovens – tais como a Declaração dos Direitos Humanos, a Constituição Brasileira, o ECA -, e a regulamentação da organização escolar – por exemplo, regimento escolar -, a seus contextos de produção, reconhecendo e analisando possíveis motivações, finalidades e sua vinculação com experiências humanas e fatos históricos e sociais, como forma de ampliar a compreensão dos direitos e deveres, de fomentar os princípios democráticos e uma atuação pautada pela ética da responsabilidade (o outro tem direito a uma vida digna tanto quanto eu tenho).", "o": "Reconstrução do contexto de produção, circulação e recepção de textos legais e normativos."}, {"a": "9", "t": "3", "c": "EF89LP19", "e": "", "h": "Analisar, a partir do contexto de produção, a forma de organização das cartas abertas, abaixo-assinados e petições on-line (identificação dos signatários, explicitação da reivindicação feita, acompanhada ou não de uma breve apresentação da problemática e/ou de justificativas que visam sustentar a reivindicação) e a proposição, discussão e aprovação de propostas políticas ou de soluções para problemas de interesse público, apresentadas ou lidas nos canais digitais de participação, identificando suas marcas linguísticas, como forma de possibilitar a escrita ou a subscrição consciente de abaixoassinados e textos dessa natureza e poder se posicionar de forma crítica e fundamentada frente às propostas.", "o": "Relação entre contexto de produção e características composicionais e estilísticas dos gêneros Apreciação e réplica."}, {"a": "9", "t": "3", "c": "EF69LP20", "e": "", "h": "Identificar, tendo em vista o contexto de produção, a forma de organização dos textos normativos e legais, a lógica de hierarquização de seus itens e subitens e suas partes: parte inicial (título – nome e data – e ementa), blocos de artigos (parte, livro, capítulo, seção, subseção), artigos (caput e parágrafos e incisos) e parte final (disposições pertinentes à sua implementação) e analisar efeitos de sentido causados pelo uso de vocabulário técnico, pelo uso do imperativo, de palavras e expressões que indicam circunstâncias, como advérbios e locuções adverbiais, de palavras que indicam generalidade, como alguns pronomes indefinidos, de forma a poder compreender o caráter imperativo, coercitivo e generalista das leis e de outras formas de regulamentação.", "o": "Reconstrução das condições de produção e circulação e adequação do texto à construção composicional e ao estilo de gênero (Lei, código, estatuto,código, regimento etc.)."}, {"a": "9", "t": "3", "c": "EF89LP24", "e": "", "h": "Realizar pesquisa, estabelecendo o recorte das questões, usando fontes abertas e confiáveis.", "o": "Curadoria de informação."}, {"a": "9", "t": "3", "c": "EF89LP25/ES", "e": "", "h": "Divulgar o resultado de pesquisas - envolvendo as diferentes áreas no interior de projetos integradores - por meio de apresentações orais, verbetes de enciclopédias colaborativas, reportagens de divulgação científica, vlogs científicos, vídeos de diferentes tipos etc.", "o": "Estratégias de escrita: textualização, revisão e edição."}, {"a": "9", "t": "3", "c": "EF89LP29/ES", "e": "", "h": "ES Utilizar e perceber mecanismos de progressão temática, tais como retomadas anafóricas (“que, cujo, onde”, pronomes do caso reto e oblíquos, pronomes demonstrativos, nomes correferentes etc.), catáforas (remetendo para adiante ao invés de retomar o já dito), uso de organizadores textuais, de coesivos etc., e analisar os mecanismos de reformulação e paráfrase utilizados nos textos de divulgação do conhecimento.", "o": "Textualização Progressão temática"}, {"a": "9", "t": "3", "c": "EF89LP33", "e": "", "h": "Ler, de forma autônoma, e compreender – selecionando procedimentos e estratégias de leitura adequados a diferentes objetivos e levando em conta características dos gêneros e suportes – romances, contos contemporâneos, minicontos, fábulas contemporâneas, romances juvenis, biografias romanceadas, novelas, crônicas visuais, narrativas de ficção científica, narrativas de suspense, poemas de forma livre e fixa (como haicai), poema concreto, ciberpoema, dentre outros, expressando avaliação sobre o texto lido e estabelecendo preferências por gêneros, temas, autores.", "o": "Estratégias de leitura Apreciação e réplica."}, {"a": "9", "t": "3", "c": "EF89LP36", "e": "", "h": "Parodiar poemas conhecidos da literatura e criar textos em versos (como poemas concretos, ciberpoemas, haicais, liras, microrroteiros, lambe-lambes e outros tipos de poemas), explorando o uso de recursos sonoros e semânticos (como figuras de linguagem e jogos de palavras) e visuais (como relações entre imagem e texto verbal e distribuição da mancha gráfica), de forma a propiciar diferentes efeitos de sentido.", "o": "Relação entre textos."}, {"a": "9", "t": "3", "c": "EF69LP44", "e": "", "h": "Inferir a presença de valores sociais, culturais e humanos e de diferentes visões de mundo, em textos literários, reconhecendo nesses textos formas de estabelecer múltiplos olhares sobre as identidades, sociedades e culturas e considerando a autoria e o contexto social e histórico de sua produção.", "o": "Reconstrução das condições de produção, circulação e recepção Apreciação e réplica."}, {"a": "9", "t": "3", "c": "EF69LP47", "e": "", "h": "Analisar, em textos narrativos ficcionais, as diferentes formas de composição próprias de cada gênero, os recursos coesivos que constroem a passagem do tempo e articulam suas partes, a escolha lexical típica de cada gênero para a caracterização dos cenários e dos personagens e os efeitos de sentido decorrentes dos tempos verbais, dos tipos de discurso, dos verbos de enunciação e das variedades linguísticas (no discurso direto, se houver) empregados, identificando o enredo e o foco narrativo e percebendo como se estrutura a narrativa nos diferentes gêneros e os efeitos de sentido decorrentes do foco narrativo típico de cada gênero, da caracterização dos espaços físico e psicológico e dos tempos cronológico e psicológico, das diferentes vozes no texto (do narrador, de personagens em discurso direto e indireto), do uso de pontuação expressiva, palavras e expressões conotativas e processos figurativos e do uso de recursos linguísticogramaticais próprios a cada gênero narrativo.", "o": "Reconstrução da textualidade e compreensão dos efeitos de sentidos provocados pelos usos de recursos linguísticos e multissemióticos."}, {"a": "9", "t": "3", "c": "EF69LP48", "e": "", "h": "Interpretar, em poemas, efeitos produzidos pelo uso de recursos expressivos sonoros (estrofação, rimas, aliterações etc), semânticos (figuras de linguagem, por exemplo), gráfico- espacial (distribuição da mancha gráfica no papel), imagens e sua relação com o texto verbal.", "o": "Reconstrução da textualidade e compreensão dos efeitos de sentidos provocados pelos usos de recursos linguísticos e multissemióticos."}, {"a": "9", "t": "3", "c": "EF69LP54", "e": "", "h": "Analisar os efeitos de sentido decorrentes da interação entre os elementos linguísticos e os recursos paralinguísticos e cinésicos, como as variações no ritmo, as modulações no tom de voz, as pausas, as manipulações do estrato sonoro da linguagem, obtidos por meio da estrofação, das rimas e de figuras de linguagem como as aliterações, as assonâncias, as onomatopeias, dentre outras, a postura corporal e a gestualidade, na declamação de poemas, apresentações musicais e teatrais, tanto em gêneros em prosa quanto nos gêneros poéticos, os efeitos de sentido decorrentes do emprego de figuras de linguagem, tais como comparação, metáfora, personificação, metonímia, hipérbole, eufemismo, ironia, paradoxo e antítese e os efeitos de sentido decorrentes do emprego de palavras e expressões denotativas e conotativas (adjetivos, locuções adjetivas, orações subordinadas adjetivas etc.), que funcionam como modificadores, percebendo sua função na caracterização dos espaços, tempos, personagens e ações próprios de cada gênero narrativo.", "o": "Recursos linguísticos e semióticos que operam nos textos pertencentes aos gêneros literários."}]};
